-- #####################################################################################################
-- ### PART 1 of 7 — tutors add their own one-off lessons and weekly slots, Create lessons, price pending (centre option)
-- ### source branch: claude/t6-3-tutor-own-lessons   file: db/migration_tutor_own_lessons.sql   undo: db/migration_tutor_own_lessons_down.sql
-- ### (if an error appears, search this file for the nearest "### PART" line above the error line: that is the part that failed)
-- #####################################################################################################
-- =====================================================================================================
-- T6 step 3 + 4 — tutors add their OWN one-off lessons, keep their OWN weekly slots and press "Create lessons"      undo: migration_tutor_own_lessons_down.sql
-- =====================================================================================================
-- Needs migration_tutor_moves.sql (T6 step 2) and, through it, tutor_schedule, staff_slots (student_tutors, the slot columns, the generator's key), staff_reassign
-- (lesson_locked_reason), staff_charges (the gate the price function reuses) and centre_invoice_run (the one function this file patches). Run on DEV first. Safe to run twice.
--
-- THE CENTRE'S CHOICE (owner decisions 2026-11-27). Three more of the six switches become BUILT (all under lessons.tutors_edit, read as of the centre's TODAY, all off
-- by default; each needs lessons.timetable_editing = tutors_direct):
--   tutors_edit.one_off       a tutor may add a one-off lesson for a student ASSIGNED to them          tutor_add_lesson
--   tutors_edit.weekly_slots  a tutor may add, change or stop their OWN weekly slots                    tutor_save_slot, tutor_stop_slot
--   tutors_edit.generate      a tutor may press "Create lessons" for their OWN slots                    tutor_generate_lessons
--   (tutors_edit.link stays "soon" until step 5; tutors_propose stays "soon" until step 6.)
-- The existing limits apply where they mean something: the NOTICE (a new lesson, or a generated one, must start min_notice_hours or more from now; nothing in the
-- past) and max_changes_per_month (adding a lesson, adding / changing / stopping a slot each count as one change, like a move or a cancel; "Create lessons" is a
-- batch of already-agreed slots and does not count).
--
-- WHAT A TUTOR CAN DO (functions only; tutors still have NO table access, no policy is added anywhere)
--   tutor_my_students()                                       read   the students assigned to me (name, level, a suggested subject) for the Add lesson form
--   tutor_add_lesson(student, date, start, end, subject, note) one lesson for ONE assigned student. Never a group class, never a trial (trials_flagged_by is the centre's).
--   tutor_save_slot(slot, student, weekday, start, end, subject)  slot null = add (one student); slot set = change my own slot (day, time, subject; not the student)
--   tutor_stop_slot(slot)                                     stop my own slot (switched off, never deleted; lessons it already made stay)
--   tutor_generate_lessons(org, from, to)                     the SAME generator as staff (same key: slot + day, skips whole-centre holidays when calendar.skip_holidays is on,
--                                                             skips ended students, never the past), for MY slots and MY assigned students only. Default today + 4 weeks, at most 62 days
--   tutor_my_schedule / tutor_my_slots (replaced)             the same answers plus the new buttons the centre allows and "awaiting_centre" (the centre will confirm the lesson's details)
--
-- THE PRICE OF A LESSON A TUTOR MADE (owner decision). A tutor never sees, types or receives a price. The database fills it in:
--   * the rate per hour of that student's LATEST staff-made weekly slot or lesson (not one a tutor made, not one still waiting) is copied, or
--   * if the student has none, the lesson / slot is created with the price EMPTY and flagged `price_pending`: it HOLDS BACK that family's invoice, like a pending charge
--     (centre_invoice_run_rows, patched below: the invoice screen says "charge pending: <student>") until staff type it with staff_set_lesson_price (needs issue_invoices,
--     the same gate as the pending charges). Any non-zero rate or amount typed straight into the table clears the flag too (trigger), so no path leaves it stuck.
--   Every money word in this file lives in the INTERNAL helpers below (tutor_basis_for, tutor_own_insert_lesson, tutor_own_insert_slot, tutor_own_generate,
--   staff_set_lesson_price, the invoice run); the functions a tutor calls contain none (tests/sql/tutor_own_lessons_test.sql greps their text and their answers).
--
-- THE RULES (the first word of a refusal is the code for the screen; the same order as the step-2 functions)
--   NOT_FOUND       not a student assigned to you, not your slot, a solo organisation, a parent, staff, a switched-off tutor, another centre, an unknown id: ALL the same word
--   NOT_ALLOWED     the centre's setting is admin_only (or tutors_propose, not built yet)         SWITCH_OFF the centre hasn't switched this on
--   LIMIT           max_changes_per_month reached                                                  STUDENT_ENDED that student's lessons have ended
--   BAD_DATE / BAD_TIME / TOO_LONG   a date still to come within a year, a start and end on one day (15 minutes to 8 hours), short texts
--   TOO_LATE        closer to its start than min_notice_hours     HOLIDAY  a whole-centre holiday     ALREADY_THERE  that student already has a lesson then (so a double press adds nothing)
--   CLASH           you already teach someone at that time (YOUR lessons only, never another tutor's students)
--   SLOT_CLASH / TUTOR_CLASH   the same student, or you, already have a weekly slot at that time        GROUP_CLASS  a group class is changed by an admin
-- Days and times are the centre's own (organisations.timezone). Every write has an audit_log row (tutor_add_lesson | tutor_save_slot | tutor_stop_slot | tutor_generate_lessons).
--
-- WHAT STAFF SEE: the amber "changed by tutor" flag and the Home "Tutor changes" list now also show lessons a tutor ADDED, slots a tutor added / changed / stopped, and one
-- line per "Create lessons" run (staff_tutor_changes, replaced). lessons.created_by_tutor / recurring_slots.created_by_tutor remember WHO made a row for good (the
-- "changed_by_tutor_*" fields describe the latest change and are overwritten by the next one).
-- The Supabase API refuses a DELETE / UPDATE without WHERE (pg-safeupdate): every statement below has one.
-- =====================================================================================================

-- ---------------------------------------------------------------- 1. the columns
alter table public.lessons add column if not exists price_pending    boolean not null default false;   -- a tutor made it and the centre has not confirmed its price
alter table public.lessons add column if not exists created_by_tutor uuid;                              -- memberships.id of the tutor who made this lesson (never changes)
alter table public.recurring_slots add column if not exists price_pending         boolean not null default false;
alter table public.recurring_slots add column if not exists created_by_tutor      uuid;
alter table public.recurring_slots add column if not exists changed_by_tutor_at   timestamptz;
alter table public.recurring_slots add column if not exists changed_by_tutor      uuid;
alter table public.recurring_slots add column if not exists changed_by_tutor_what text;                 -- added | changed | stopped
alter table public.recurring_slots add column if not exists changed_by_tutor_reason text;
do $$ begin
  -- lessons: a tutor can now also ADD one (T6 step 2 allowed moved | reverted | cancelled)
  alter table public.lessons drop constraint if exists lessons_changed_by_tutor_what_ok;
  alter table public.lessons add constraint lessons_changed_by_tutor_what_ok check (changed_by_tutor_what is null or changed_by_tutor_what in ('moved', 'reverted', 'cancelled', 'added'));
  if not exists (select 1 from pg_constraint where conname = 'lessons_created_by_tutor_same_org') then
    alter table public.lessons add constraint lessons_created_by_tutor_same_org
      foreign key (created_by_tutor, org_id) references public.memberships(id, org_id) on delete set null (created_by_tutor);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'slots_created_by_tutor_same_org') then
    alter table public.recurring_slots add constraint slots_created_by_tutor_same_org
      foreign key (created_by_tutor, org_id) references public.memberships(id, org_id) on delete set null (created_by_tutor);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'slots_changed_by_tutor_same_org') then
    alter table public.recurring_slots add constraint slots_changed_by_tutor_same_org
      foreign key (changed_by_tutor, org_id) references public.memberships(id, org_id) on delete set null (changed_by_tutor);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'slots_changed_by_tutor_what_ok') then
    alter table public.recurring_slots add constraint slots_changed_by_tutor_what_ok check (changed_by_tutor_what is null or changed_by_tutor_what in ('added', 'changed', 'stopped'));
  end if;
end $$;
create index if not exists slots_changed_by_tutor on public.recurring_slots(org_id, changed_by_tutor_at desc) where changed_by_tutor_at is not null;
create index if not exists lessons_price_pending on public.lessons(org_id) where price_pending;

-- Two rules, in one trigger on lessons and slots:
--  * the flag CLEARS when anyone types a real price straight into the row (staff_set_lesson_price clears it explicitly, also for a price of 0);
--  * a lesson that is made from a slot that is still waiting for its price (by the STAFF "Create lessons" button too, which knows nothing of this flag) is born waiting.
--    Without this a waiting slot would make zero-price lessons that no invoice ever noticed.
create or replace function public.price_pending_guard() returns trigger language plpgsql security definer set search_path = public as $$
declare j jsonb := to_jsonb(new);
begin
  if new.price_pending and (coalesce((j->>'rate')::numeric, 0) > 0 or coalesce((j->>'amount')::numeric, 0) > 0) then new.price_pending := false; end if;
  if tg_op = 'INSERT' and tg_table_name = 'lessons' and not new.price_pending and nullif(j->>'slot_id', '') is not null
     and coalesce((j->>'rate')::numeric, 0) = 0 and coalesce((j->>'amount')::numeric, 0) = 0
     and exists (select 1 from recurring_slots s where s.id = (j->>'slot_id')::uuid and s.price_pending) then
    new.price_pending := true;
  end if;
  return new;
end $$;
revoke all on function public.price_pending_guard() from public, anon, authenticated;
drop trigger if exists price_pending_guard on public.lessons;
create trigger price_pending_guard before insert or update on public.lessons for each row execute function public.price_pending_guard();
drop trigger if exists price_pending_guard on public.recurring_slots;
create trigger price_pending_guard before insert or update on public.recurring_slots for each row execute function public.price_pending_guard();

-- ---------------------------------------------------------------- 2. what counts toward max_changes_per_month (internal)
-- One place, so tutor_change_block, tutor_my_schedule and the new functions can't disagree. Counts this tutor's audit rows since the 1st (centre time).
create or replace function public.tutor_changes_used(p_org uuid, p_user uuid, p_tz text) returns int
language sql stable security definer set search_path = public as $$
  select count(*)::int from audit_log a
   where a.org_id = p_org and a.actor = p_user
     and a.action in ('tutor_postpone_lesson', 'tutor_revert_lesson', 'tutor_cancel_lesson', 'tutor_add_lesson', 'tutor_save_slot', 'tutor_stop_slot')
     and a.at >= date_trunc('month', now() at time zone p_tz) at time zone p_tz
$$;

-- ---------------------------------------------------------------- 3. step 2's rulebook, now counting every kind of change (the rest is word for word)
create or replace function public.tutor_change_block(p_lesson uuid, p_what text) returns text
language plpgsql stable security definer set search_path = public as $$
declare me uuid := auth.uid(); l lessons; tz text; today date; cfg jsonb; mode text; sw boolean; notice int; mx int; used int; start_ts timestamptz; lk text;
        sl recurring_slots; tdate date;
begin
  if me is null or p_what not in ('postpone', 'revert', 'cancel') then return 'NOT_FOUND'; end if;
  select * into l from lessons where id = p_lesson;
  if not found or l.taught_by is null then return 'NOT_FOUND'; end if;
  select o.timezone into tz from memberships m join organisations o on o.id = m.org_id and o.kind = 'centre'
   where m.id = l.taught_by and m.org_id = l.org_id and m.user_id = me and m.role = 'tutor' and m.status = 'active';
  if tz is null then return 'NOT_FOUND'; end if;
  if not exists (select 1 from student_tutors st where st.org_id = l.org_id and st.student_id = l.student_id and st.membership_id = l.taught_by and st.active) then
    return 'NOT_FOUND'; end if;
  today := (now() at time zone tz)::date;
  cfg := org_settings_on(l.org_id, today);
  mode := coalesce(cfg #>> '{lessons,timetable_editing}', 'admin_only');
  if mode <> 'tutors_direct' then
    return 'NOT_ALLOWED: at this centre the admins change the timetable. Ask them to change this lesson'; end if;
  sw := case when p_what = 'cancel' then coalesce((cfg #>> '{lessons,tutors_edit,cancel}')::boolean, false)
             else coalesce((cfg #>> '{lessons,tutors_edit,postpone}')::boolean, true) end;
  if not sw then
    return 'SWITCH_OFF: this centre doesn''t let tutors ' || case when p_what = 'cancel' then 'cancel' else 'move' end || ' lessons. Ask an admin'; end if;
  lk := lesson_locked_reason(l.id);
  if lk is not null then
    return case lk when 'MARKED'    then 'ALREADY_MARKED: this lesson is already marked, so it can''t be changed here. Ask an admin'
                   when 'CANCELLED' then 'CANCELLED: this lesson was cancelled'
                   else                  'LOCKED: your centre has already closed this lesson, so it can''t be changed here. Ask an admin' end;   -- one word for every closed reason: a tutor is never told which
  end if;
  if p_what = 'revert' then
    if not l.postponed then return 'NOT_MOVED: this lesson is already at its usual time'; end if;
    select * into sl from recurring_slots x where x.id = l.slot_id and x.org_id = l.org_id;
    if not found or l.slot_date is null or not sl.active then
      return 'NO_SLOT: this lesson has no usual slot to go back to. Ask an admin'; end if;
    if sl.taught_by is distinct from l.taught_by or sl.end_time - sl.start_time <> l.end_time - l.start_time then
      return 'SLOT_CHANGED: the usual slot has changed since this lesson was moved. Ask an admin'; end if;
  end if;
  start_ts := (l.lesson_date + l.start_time) at time zone tz;
  if start_ts <= now() then return 'PAST: this lesson has already started'; end if;
  notice := coalesce((cfg #>> '{lessons,min_notice_hours}')::int, 24);
  if start_ts < now() + make_interval(hours => notice) then
    return 'TOO_LATE: a lesson can only be changed ' || notice || ' hour' || case when notice = 1 then '' else 's' end || ' or more before it starts. Ask an admin'; end if;
  mx := coalesce((cfg #>> '{lessons,max_changes_per_month}')::int, 0);
  if mx > 0 then
    used := public.tutor_changes_used(l.org_id, me, tz);
    if used >= mx then
      return 'LIMIT: you have used your ' || mx || ' schedule change' || case when mx = 1 then '' else 's' end || ' for this month. Ask an admin'; end if;
  end if;
  return null;
end $$;

-- ---------------------------------------------------------------- 4. the gate every new tutor function starts with (internal; reads no money)
-- p_switch: one_off | weekly_slots | generate. p_student null = no student to check (the generator, a slot's own checks). The first refusal wins, in the order of the
-- list in the header; "not yours" and "no such thing" are the same NOT_FOUND. Returns what the caller needs as jsonb: mem (my membership), tz, today, notice, mx, skip_holidays.
create or replace function public.tutor_own_gate(p_org uuid, p_student uuid, p_switch text) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare me uuid := auth.uid(); mem uuid; tz text; today date; cfg jsonb; mode text; sw boolean;
begin
  if me is null or p_org is null or p_switch not in ('one_off', 'weekly_slots', 'generate') then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  select m.id, o.timezone into mem, tz from memberships m join organisations o on o.id = m.org_id and o.kind = 'centre'
   where m.org_id = p_org and m.user_id = me and m.role = 'tutor' and m.status = 'active';
  if mem is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  if p_student is not null and not exists (select 1 from student_tutors st join students s on s.id = st.student_id and s.org_id = st.org_id
                                            where st.org_id = p_org and st.student_id = p_student and st.membership_id = mem and st.active) then
    raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  today := (now() at time zone tz)::date;
  cfg := org_settings_on(p_org, today);
  mode := coalesce(cfg #>> '{lessons,timetable_editing}', 'admin_only');
  if mode <> 'tutors_direct' then
    raise exception 'NOT_ALLOWED: at this centre the admins change the timetable. Ask them' using errcode = 'P0001'; end if;
  sw := coalesce((cfg #>> array['lessons', 'tutors_edit', p_switch])::boolean, false);
  if not sw then
    raise exception 'SWITCH_OFF: this centre doesn''t let tutors % . Ask an admin', case p_switch when 'one_off' then 'add lessons' when 'weekly_slots' then 'change their weekly slots' else 'create lessons' end
      using errcode = 'P0001'; end if;
  return jsonb_build_object('mem', mem, 'tz', tz, 'today', today,
                            'notice', coalesce((cfg #>> '{lessons,min_notice_hours}')::int, 24),
                            'mx', coalesce((cfg #>> '{lessons,max_changes_per_month}')::int, 0),
                            'skip_holidays', case when jsonb_typeof(cfg #> '{calendar,skip_holidays}') = 'boolean' then (cfg #>> '{calendar,skip_holidays}')::boolean else true end);
end $$;

-- the monthly limit, for the functions that count as one change
create or replace function public.tutor_own_limit_check(p_org uuid, p_gate jsonb) returns void
language plpgsql stable security definer set search_path = public as $$
declare mx int := (p_gate->>'mx')::int; used int;
begin
  if mx > 0 then
    used := public.tutor_changes_used(p_org, auth.uid(), p_gate->>'tz');
    if used >= mx then
      raise exception 'LIMIT: you have used your % schedule change% for this month. Ask an admin', mx, case when mx = 1 then '' else 's' end using errcode = 'P0001'; end if;
  end if;
end $$;

-- ---------------------------------------------------------------- 5. the money helpers (INTERNAL: the browser can't call them; the only place a tutor's action touches a price)
-- tutor_basis_for: the rate of the student's LATEST staff-made slot or lesson (not tutor-made, not still waiting) and its subject, with known = true; {"known": false} when there is none.
create or replace function public.tutor_basis_for(p_org uuid, p_student uuid) returns jsonb
language sql stable security definer set search_path = public as $$
  select coalesce((select jsonb_build_object('known', true, 'rate', x.rate, 'subject', x.subject)
                     from (select s.rate, s.subject, s.created_at, s.id::text as k from recurring_slots s
                            where s.org_id = p_org and s.student_id = p_student and s.created_by_tutor is null and not s.price_pending
                           union all
                           select l.rate, l.subject, l.created_at, l.id::text from lessons l
                            where l.org_id = p_org and l.student_id = p_student and l.created_by_tutor is null and not l.price_pending) x
                    order by x.created_at desc, x.k desc limit 1), '{"known": false}'::jsonb)
$$;

-- one lesson, made for a tutor: the rate comes from the basis, or the price is left empty and flagged. Returns the id and whether the centre must confirm.
create or replace function public.tutor_own_insert_lesson(p_org uuid, p_student uuid, p_mem uuid, p_date date, p_start time, p_end time, p_subject text, p_note text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare b jsonb := public.tutor_basis_for(p_org, p_student); r numeric(8,2) := coalesce((b->>'rate')::numeric, 0); known boolean := (b->>'known')::boolean;
        owner_uid uuid; st students; new_id uuid;
begin
  select m.user_id into owner_uid from memberships m where m.org_id = p_org and m.role = 'owner' and m.status = 'active' and m.user_id is not null order by m.created_at limit 1;
  select * into st from students where id = p_student and org_id = p_org;
  if owner_uid is null or not found then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  insert into lessons(tutor_id, org_id, student_id, lesson_date, start_time, end_time, subject, level, rate, amount, split, status, paid, one_off, taught_by,
                      price_pending, created_by_tutor, changed_by_tutor_at, changed_by_tutor, changed_by_tutor_what, changed_by_tutor_reason)
  values (owner_uid, p_org, p_student, p_date, p_start, p_end, coalesce(p_subject, b->>'subject'), st.level, r,
          round(r * (extract(epoch from (p_end - p_start)) / 3600)::numeric, 2), 1, 'scheduled', false, true, p_mem,
          not known, p_mem, now(), p_mem, 'added', p_note)
  returning id into new_id;
  return jsonb_build_object('id', new_id, 'awaiting_centre', not known);
end $$;

-- one weekly slot, made for a tutor (same rule for the rate)
create or replace function public.tutor_own_insert_slot(p_org uuid, p_student uuid, p_mem uuid, p_weekday int, p_start time, p_end time, p_subject text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare b jsonb := public.tutor_basis_for(p_org, p_student); r numeric(8,2) := coalesce((b->>'rate')::numeric, 0); known boolean := (b->>'known')::boolean;
        owner_uid uuid; st students; new_id uuid;
begin
  select m.user_id into owner_uid from memberships m where m.org_id = p_org and m.role = 'owner' and m.status = 'active' and m.user_id is not null order by m.created_at limit 1;
  select * into st from students where id = p_student and org_id = p_org;
  if owner_uid is null or not found then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  insert into recurring_slots(tutor_id, org_id, student_id, weekday, start_time, end_time, subject, rate, level, split, taught_by,
                              price_pending, created_by_tutor, changed_by_tutor_at, changed_by_tutor, changed_by_tutor_what)
  values (owner_uid, p_org, p_student, p_weekday, p_start, p_end, coalesce(p_subject, b->>'subject'), r, st.level, 1, p_mem,
          not known, p_mem, now(), p_mem, 'added')
  returning id into new_id;
  return jsonb_build_object('id', new_id, 'awaiting_centre', not known);
end $$;

-- the generator for ONE tutor's slots: staff_generate_lessons' own statement (same key = slot + day, a hand-made lesson for the same student, day and start counts),
-- restricted to the tutor's slots and assigned students, and skipping what starts inside the notice. A group class gets the same session_id staff would give it.
create or replace function public.tutor_own_generate(p_org uuid, p_mem uuid, p_from date, p_to date, p_skip boolean, p_notice int, p_tz text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare res jsonb;
begin
  with days as (select d::date as d from generate_series(p_from, p_to, interval '1 day') d),
  cand as (
    select sl.id as slot_id, sl.session_key, sl.tutor_id, sl.student_id, sl.start_time, sl.end_time, sl.subject, sl.level, sl.rate, sl.split, sl.price_pending as ppend,
           days.d, st.end_date,
           exists (select 1 from student_tutors x where x.org_id = p_org and x.student_id = sl.student_id and x.membership_id = p_mem and x.active) as assigned,
           exists (select 1 from holidays h where h.org_id = p_org and h.branch_id is null and days.d between h.starts_on and h.ends_on) as is_hol,
           exists (select 1 from lessons l where l.org_id = p_org
                    and ((l.slot_id = sl.id and l.slot_date = days.d)
                      or (l.student_id = sl.student_id and l.lesson_date = days.d and l.start_time = sl.start_time))) as there
      from recurring_slots sl
      join students st on st.id = sl.student_id and st.org_id = sl.org_id
      join days on (extract(isodow from days.d)::int - 1) = sl.weekday
     where sl.org_id = p_org and sl.active and sl.taught_by = p_mem),
  cls as (
    select cand.*, case when end_date is not null and d > end_date then 'ended'
                        when not assigned then 'not_assigned'
                        when there then 'there'
                        when is_hol and p_skip then 'holiday'
                        when ((d + start_time) at time zone p_tz) < now() + make_interval(hours => p_notice) then 'soon'
                        else 'new' end as kind
      from cand),
  ins as (
    insert into lessons(tutor_id, org_id, student_id, slot_id, lesson_date, slot_date, start_time, end_time, subject, level, rate, split, amount,
                        status, paid, one_off, taught_by, session_id, price_pending, created_by_tutor)
    select tutor_id, p_org, student_id, slot_id, d, d, start_time, end_time, subject, level, rate, coalesce(split, 1),
           round(round(rate * (extract(epoch from (end_time - start_time)) / 3600)::numeric, 2) / greatest(coalesce(split, 1), 1), 2),
           'scheduled', false, false, p_mem,
           case when session_key is null then null else md5(session_key::text || d::text)::uuid end,
           ppend, p_mem
      from cls where kind = 'new'
    returning id)
  select jsonb_build_object(
           'from', p_from, 'to', p_to,
           'created', (select count(*) from ins),
           'skipped', count(*) filter (where kind = 'there'),
           'holidays', count(distinct d) filter (where kind = 'holiday'),
           'ended', count(*) filter (where kind = 'ended'),
           'too_soon', count(*) filter (where kind = 'soon'),
           'not_assigned', count(*) filter (where kind = 'not_assigned'),
           'awaiting_centre', count(*) filter (where kind = 'new' and ppend),
           'slots', (select count(*) from recurring_slots x where x.org_id = p_org and x.active and x.taught_by = p_mem))
    into res from cls;
  return res;
end $$;

-- ---------------------------------------------------------------- 6. my assigned students (for the Add lesson and weekly slot forms)
-- Active students assigned to me whose lessons haven't ended; name, level and a suggested subject only. awaiting_centre = the centre has no earlier lesson of theirs to
-- copy the details from, so a lesson made now is confirmed by the centre first.
create or replace function public.tutor_my_students() returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if auth.uid() is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  if not exists (select 1 from memberships m join organisations o on o.id = m.org_id and o.kind = 'centre'
                  where m.user_id = auth.uid() and m.role = 'tutor' and m.status = 'active') then
    raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('org_id', o.id, 'org_name', o.trading_name, 'student_id', s.id, 'name', s.name, 'level', s.level,
                                                         'subject', b.v->>'subject', 'awaiting_centre', not (b.v->>'known')::boolean)
                                    order by lower(s.name), s.id)
                     from memberships m
                     join organisations o on o.id = m.org_id and o.kind = 'centre'
                     join student_tutors st on st.org_id = m.org_id and st.membership_id = m.id and st.active
                     join students s on s.id = st.student_id and s.org_id = st.org_id
                    cross join lateral (select public.tutor_basis_for(s.org_id, s.id) as v) b
                    where m.user_id = auth.uid() and m.role = 'tutor' and m.status = 'active'
                      and (s.end_date is null or s.end_date >= (now() at time zone o.timezone)::date)), '[]'::jsonb);
end $$;

-- ---------------------------------------------------------------- 7. add one lesson
create or replace function public.tutor_add_lesson(p_student uuid, p_date date, p_start time, p_end time, p_subject text default null, p_note text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare org uuid; g jsonb; mem uuid; tz text; today date; notice int; st students; mins int; start_ts timestamptz; hol text; same text; clash text; made jsonb;
        subj text := nullif(trim(coalesce(p_subject, '')), ''); note text := nullif(trim(coalesce(p_note, '')), '');
begin
  if auth.uid() is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  select s.org_id into org from students s where s.id = p_student;
  if org is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  g := public.tutor_own_gate(org, p_student, 'one_off');
  mem := (g->>'mem')::uuid; tz := g->>'tz'; today := (g->>'today')::date; notice := (g->>'notice')::int;
  perform pg_advisory_xact_lock(hashtextextended('tutor_own:' || mem::text, 0));                  -- two presses together: the second one finds the first one's lesson
  perform public.tutor_own_limit_check(org, g);
  select * into st from students where id = p_student and org_id = org;
  if st.end_date is not null and st.end_date < today then raise exception 'STUDENT_ENDED: %''s lessons have ended', st.name using errcode = 'P0001'; end if;
  if p_date is null or p_start is null or p_end is null then raise exception 'BAD_DATE: pick a day, a start time and an end time' using errcode = 'P0001'; end if;
  if p_date > today + 365 then raise exception 'BAD_DATE: pick a date within the next year' using errcode = 'P0001'; end if;
  mins := (extract(epoch from (p_end - p_start)) / 60)::int;
  if mins <= 0 then raise exception 'BAD_TIME: the lesson must end after it starts' using errcode = 'P0001'; end if;
  if mins < 15 or mins > 480 then raise exception 'BAD_TIME: a lesson lasts 15 minutes to 8 hours' using errcode = 'P0001'; end if;
  if subj is not null and length(subj) > 60 then raise exception 'TOO_LONG: keep the subject under 60 characters' using errcode = 'P0001'; end if;
  if note is not null and length(note) > 300 then raise exception 'TOO_LONG: keep the note under 300 characters' using errcode = 'P0001'; end if;
  start_ts := (p_date + p_start) at time zone tz;
  if start_ts <= now() then raise exception 'BAD_DATE: that time has already passed. Pick a later one' using errcode = 'P0001'; end if;
  if start_ts < now() + make_interval(hours => notice) then
    raise exception 'TOO_LATE: a new lesson must start % hour% or more from now. Ask an admin', notice, case when notice = 1 then '' else 's' end using errcode = 'P0001'; end if;
  select h.name into hol from holidays h where h.org_id = org and h.branch_id is null and p_date between h.starts_on and h.ends_on order by h.starts_on, h.name limit 1;
  if hol is not null then raise exception 'HOLIDAY: % is a holiday at this centre. Pick another day', hol using errcode = 'P0001'; end if;
  select s.name into same from lessons y join students s on s.id = y.student_id and s.org_id = y.org_id
   where y.org_id = org and y.student_id = p_student and y.status <> 'cancelled' and y.lesson_date = p_date and y.start_time < p_end and y.end_time > p_start limit 1;
  if same is not null then raise exception 'ALREADY_THERE: % already has a lesson at that time', same using errcode = 'P0001'; end if;
  select s.name into clash from lessons y join students s on s.id = y.student_id and s.org_id = y.org_id
   where y.org_id = org and y.taught_by = mem and y.status <> 'cancelled' and y.lesson_date = p_date and y.start_time < p_end and y.end_time > p_start
   order by y.start_time, y.id limit 1;
  if clash is not null then raise exception 'CLASH: you already teach % at that time. Pick another time', clash using errcode = 'P0001'; end if;

  made := public.tutor_own_insert_lesson(org, p_student, mem, p_date, p_start, p_end, subj, note);
  insert into audit_log(org_id, actor, action, table_name, row_id, after)
  values (org, auth.uid(), 'tutor_add_lesson', 'lessons', made->>'id',
          jsonb_build_object('student_id', p_student, 'lesson_date', p_date, 'start_time', p_start, 'end_time', p_end, 'note', note, 'awaiting_centre', (made->>'awaiting_centre')::boolean));
  return jsonb_build_object('lesson_id', (made->>'id')::uuid, 'lesson_date', p_date, 'start_time', p_start, 'end_time', p_end,
                            'awaiting_centre', (made->>'awaiting_centre')::boolean);
end $$;

-- ---------------------------------------------------------------- 8. add / change one of my weekly slots
-- p_slot null = add a slot for p_student (one student; a group class is staff's). p_slot set = change MY slot's day, time and subject (the student can't be changed:
-- stop it and add a new one, as staff do). Lessons already made from a slot are never rewritten; the answer says how many upcoming ones are left.
create or replace function public.tutor_save_slot(p_slot uuid, p_student uuid, p_weekday int, p_start time, p_end time, p_subject text default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare org uuid; sid uuid := p_student; sl recurring_slots; g jsonb; mem uuid; today date; st students; mins int; clash text; made jsonb; left_n int; new_id uuid; aw boolean := false;
        subj text := nullif(trim(coalesce(p_subject, '')), '');
begin
  if auth.uid() is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  if p_slot is not null then
    select * into sl from recurring_slots where id = p_slot;
    if not found or sl.taught_by is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
    org := sl.org_id; sid := sl.student_id;
  else
    select s.org_id into org from students s where s.id = p_student;
    if org is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  end if;
  g := public.tutor_own_gate(org, sid, 'weekly_slots');
  mem := (g->>'mem')::uuid; today := (g->>'today')::date;
  if p_slot is not null and (sl.taught_by is distinct from mem or not sl.active) then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  if p_slot is not null and sl.session_key is not null then
    raise exception 'GROUP_CLASS: this is a group class. Ask an admin to change it' using errcode = 'P0001'; end if;
  perform pg_advisory_xact_lock(hashtextextended('tutor_own:' || mem::text, 0));
  perform public.tutor_own_limit_check(org, g);
  select * into st from students where id = sid and org_id = org;
  if p_slot is null and st.end_date is not null and st.end_date < today then raise exception 'STUDENT_ENDED: %''s lessons have ended', st.name using errcode = 'P0001'; end if;
  if p_weekday is null or p_weekday < 0 or p_weekday > 6 then raise exception 'BAD_SLOT: pick a day of the week' using errcode = 'P0001'; end if;
  if p_start is null or p_end is null then raise exception 'BAD_TIME: give a start and an end time' using errcode = 'P0001'; end if;
  mins := (extract(epoch from (p_end - p_start)) / 60)::int;
  if mins <= 0 then raise exception 'BAD_TIME: the lesson must end after it starts' using errcode = 'P0001'; end if;
  if mins < 15 or mins > 480 then raise exception 'BAD_TIME: a lesson lasts 15 minutes to 8 hours' using errcode = 'P0001'; end if;
  if subj is not null and length(subj) > 60 then raise exception 'TOO_LONG: keep the subject under 60 characters' using errcode = 'P0001'; end if;
  select s.name into clash from recurring_slots x join students s on s.id = x.student_id and s.org_id = x.org_id
   where x.org_id = org and x.active and x.student_id = sid and (p_slot is null or x.id <> p_slot) and x.weekday = p_weekday and x.start_time < p_end and x.end_time > p_start limit 1;
  if clash is not null then raise exception 'SLOT_CLASH: % already has a weekly lesson at that time', clash using errcode = 'P0001'; end if;
  select s.name into clash from recurring_slots x join students s on s.id = x.student_id and s.org_id = x.org_id
   where x.org_id = org and x.active and x.taught_by = mem and (p_slot is null or x.id <> p_slot) and x.weekday = p_weekday and x.start_time < p_end and x.end_time > p_start
   order by x.start_time, x.id limit 1;
  if clash is not null then raise exception 'TUTOR_CLASH: you already teach % at that time every week. Pick another time', clash using errcode = 'P0001'; end if;

  if p_slot is null then
    made := public.tutor_own_insert_slot(org, sid, mem, p_weekday, p_start, p_end, subj);
    new_id := (made->>'id')::uuid; aw := (made->>'awaiting_centre')::boolean; left_n := 0;
  else
    update recurring_slots set weekday = p_weekday, start_time = p_start, end_time = p_end, subject = subj,
           changed_by_tutor_at = now(), changed_by_tutor = mem, changed_by_tutor_what = 'changed'
     where id = p_slot;
    new_id := p_slot; aw := sl.price_pending;
    select count(*) into left_n from lessons l where l.org_id = org and l.slot_id = p_slot and l.lesson_date >= today and l.attendance is null and l.status <> 'cancelled';
  end if;
  insert into audit_log(org_id, actor, action, table_name, row_id, before, after)
  values (org, auth.uid(), 'tutor_save_slot', 'recurring_slots', new_id::text,
          case when p_slot is null then null else jsonb_build_object('weekday', sl.weekday, 'start', sl.start_time, 'end', sl.end_time, 'subject', sl.subject) end,
          jsonb_build_object('added', p_slot is null, 'student_id', sid, 'weekday', p_weekday, 'start', p_start, 'end', p_end, 'subject', subj));
  return jsonb_build_object('slot_id', new_id, 'added', p_slot is null, 'lessons_left', left_n, 'awaiting_centre', aw);
end $$;

-- ---------------------------------------------------------------- 9. stop one of my weekly slots
create or replace function public.tutor_stop_slot(p_slot uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare sl recurring_slots; g jsonb; mem uuid; today date; left_n int;
begin
  if auth.uid() is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  select * into sl from recurring_slots where id = p_slot;
  if not found or sl.taught_by is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  g := public.tutor_own_gate(sl.org_id, sl.student_id, 'weekly_slots');
  mem := (g->>'mem')::uuid; today := (g->>'today')::date;
  if sl.taught_by is distinct from mem then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  if sl.session_key is not null then raise exception 'GROUP_CLASS: this is a group class. Ask an admin to change it' using errcode = 'P0001'; end if;
  perform pg_advisory_xact_lock(hashtextextended('tutor_own:' || mem::text, 0));
  select * into sl from recurring_slots where id = p_slot;
  select count(*) into left_n from lessons l where l.org_id = sl.org_id and l.slot_id = p_slot and l.lesson_date >= today and l.attendance is null and l.status <> 'cancelled';
  if not sl.active then return jsonb_build_object('stopped', 0, 'lessons_left', left_n); end if;      -- pressed twice: nothing more happens, nothing is counted
  perform public.tutor_own_limit_check(sl.org_id, g);
  update recurring_slots set active = false, changed_by_tutor_at = now(), changed_by_tutor = mem, changed_by_tutor_what = 'stopped' where id = p_slot;
  insert into audit_log(org_id, actor, action, table_name, row_id, after)
  values (sl.org_id, auth.uid(), 'tutor_stop_slot', 'recurring_slots', p_slot::text, jsonb_build_object('lessons_left', left_n, 'student_id', sl.student_id));
  return jsonb_build_object('stopped', 1, 'lessons_left', left_n);
end $$;

-- ---------------------------------------------------------------- 10. "Create lessons" for my own slots
-- p_from default = the centre's today (never earlier); p_to default = p_from + 27 days; at most 62 days. Answer: created, skipped (already there), holidays (days skipped),
-- ended, too_soon (inside the notice), not_assigned (a slot of mine for a student not assigned to me), awaiting_centre (new lessons the centre must confirm), slots.
create or replace function public.tutor_generate_lessons(p_org uuid, p_from date default null, p_to date default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare g jsonb := public.tutor_own_gate(p_org, null, 'generate'); mem uuid := (g->>'mem')::uuid; today date := (g->>'today')::date; f date; t date; res jsonb;
begin
  f := coalesce(p_from, today); t := coalesce(p_to, f + 27);
  if f < today then raise exception 'BAD_RANGE: lessons can''t be created for days that have passed' using errcode = 'P0001'; end if;
  if t < f or t - f > 62 then raise exception 'BAD_RANGE: create at most 62 days at a time' using errcode = 'P0001'; end if;
  perform pg_advisory_xact_lock(hashtextextended('staff_generate_lessons:' || p_org::text, 0));    -- the same lock as the staff button: together they can't make a lesson twice
  res := public.tutor_own_generate(p_org, mem, f, t, (g->>'skip_holidays')::boolean, (g->>'notice')::int, g->>'tz');
  insert into audit_log(org_id, actor, action, table_name, row_id, after)
  values (p_org, auth.uid(), 'tutor_generate_lessons', 'lessons', null, res || jsonb_build_object('tutor_id', mem));
  return res;
end $$;

-- ---------------------------------------------------------------- 11. tutor_my_schedule: same answer as step 2, plus the new buttons the centre allows (can_one_off, can_slots,
--     can_generate) and, per lesson, awaiting_centre (the centre will confirm its details) and added_by_you. The monthly count comes from the shared helper. No money.
drop function if exists public.tutor_my_schedule(date, date);
create or replace function public.tutor_my_schedule(p_from date, p_to date) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare orgs jsonb; lessons jsonb; hols jsonb; today date;
begin
  if auth.uid() is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  if not exists (select 1 from memberships m join organisations o on o.id = m.org_id and o.kind = 'centre'
                  where m.user_id = auth.uid() and m.role = 'tutor' and m.status = 'active') then
    raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  if p_from is null or p_to is null or p_to < p_from or p_to - p_from > 62 then
    raise exception 'BAD_RANGE: ask for at most 62 days' using errcode = 'P0001'; end if;

  select jsonb_agg(jsonb_build_object('org_id', o.id, 'name', o.trading_name, 'today', (now() at time zone o.timezone)::date,
                                      'timetable_editing', c.mode,
                                      'can_edit', (c.mode = 'tutors_direct' and (c.sw_postpone or c.sw_cancel)),
                                      'can_postpone', (c.mode = 'tutors_direct' and c.sw_postpone), 'can_cancel', (c.mode = 'tutors_direct' and c.sw_cancel),
                                      'min_notice_hours', c.notice, 'max_changes_per_month', c.mx,
                                      'can_one_off', (c.mode = 'tutors_direct' and c.sw_one_off), 'can_slots', (c.mode = 'tutors_direct' and c.sw_slots),
                                      'can_generate', (c.mode = 'tutors_direct' and c.sw_generate),
                                      'changes_left', case when c.mx > 0 and c.mode = 'tutors_direct' then greatest(0, c.mx - public.tutor_changes_used(o.id, auth.uid(), o.timezone)) end)
                      order by o.trading_name, o.id),
         min((now() at time zone o.timezone)::date)
    into orgs, today
    from memberships m join organisations o on o.id = m.org_id and o.kind = 'centre'
    cross join lateral (select org_settings_on(o.id, (now() at time zone o.timezone)::date) as s) cfg
    cross join lateral (select coalesce(cfg.s #>> '{lessons,timetable_editing}', 'admin_only') as mode,
                               coalesce((cfg.s #>> '{lessons,tutors_edit,postpone}')::boolean, true) as sw_postpone,
                               coalesce((cfg.s #>> '{lessons,tutors_edit,cancel}')::boolean, false) as sw_cancel,
                               coalesce((cfg.s #>> '{lessons,tutors_edit,one_off}')::boolean, false) as sw_one_off,
                               coalesce((cfg.s #>> '{lessons,tutors_edit,weekly_slots}')::boolean, false) as sw_slots,
                               coalesce((cfg.s #>> '{lessons,tutors_edit,generate}')::boolean, false) as sw_generate,
                               coalesce((cfg.s #>> '{lessons,min_notice_hours}')::int, 24) as notice,
                               coalesce((cfg.s #>> '{lessons,max_changes_per_month}')::int, 0) as mx) c
   where m.user_id = auth.uid() and m.role = 'tutor' and m.status = 'active';

  select coalesce(jsonb_agg(jsonb_build_object(
           'lesson_id', l.id, 'org_id', l.org_id, 'org_name', o.trading_name,
           'student_id', s.id, 'student_name', s.name, 'student_level', s.level,
           'parent_contact', case when coalesce((org_settings_on(l.org_id, current_date) #>> '{lessons,tutors_see_parent_contact}')::boolean, false) then s.contact end,
           'lesson_date', l.lesson_date, 'start_time', l.start_time, 'end_time', l.end_time,
           'minutes', (extract(epoch from (l.end_time - l.start_time)) / 60)::int, 'subject', l.subject,
           'trial', l.trial, 'attendance', l.attendance, 'status', l.status, 'cancelled', (l.status = 'cancelled'),
           'postponed', l.postponed, 'covering', (l.covered_for is not null), 'online_link', s.online_link,
           'holiday', (select h.name from holidays h where h.org_id = l.org_id and h.branch_id is null
                        and l.lesson_date between h.starts_on and h.ends_on order by h.starts_on, h.name limit 1),
           'can_postpone', (b.postpone is null), 'can_revert', (b.revert is null), 'can_cancel', (b.cancel is null),
           'change_block', case when b.postpone is null or b.cancel is null then null
                                when b.postpone not like 'NOT_ALLOWED%' and b.postpone not like 'SWITCH_OFF%' then split_part(b.postpone, ':', 1)
                                when b.cancel not like 'NOT_ALLOWED%' and b.cancel not like 'SWITCH_OFF%' then split_part(b.cancel, ':', 1) end,
           'changed_by_you', (l.changed_by_tutor_what), 'awaiting_centre', l.price_pending, 'added_by_you', (l.created_by_tutor is not null), 'class_size', (select count(*)::int from lessons y where l.session_id is not null and y.org_id = l.org_id and y.session_id = l.session_id)
         ) order by l.lesson_date, l.start_time, s.name, l.id), '[]'::jsonb)
    into lessons
    from lessons l
    join memberships m on m.id = l.taught_by and m.org_id = l.org_id and m.user_id = auth.uid() and m.role = 'tutor' and m.status = 'active'
    join organisations o on o.id = l.org_id and o.kind = 'centre'
    join students s on s.id = l.student_id and s.org_id = l.org_id
    cross join lateral (select tutor_change_block(l.id, 'postpone') as postpone, tutor_change_block(l.id, 'revert') as revert, tutor_change_block(l.id, 'cancel') as cancel) b
   where l.lesson_date between p_from and p_to;

  select coalesce(jsonb_agg(jsonb_build_object('org_id', h.org_id, 'name', h.name, 'starts_on', h.starts_on, 'ends_on', h.ends_on)
                            order by h.starts_on, h.name, h.id), '[]'::jsonb)
    into hols
    from holidays h
   where h.branch_id is null and h.starts_on <= p_to and h.ends_on >= p_from
     and exists (select 1 from memberships m join organisations o on o.id = m.org_id and o.kind = 'centre'
                  where m.org_id = h.org_id and m.user_id = auth.uid() and m.role = 'tutor' and m.status = 'active');

  return jsonb_build_object('today', today, 'from', p_from, 'to', p_to, 'orgs', orgs, 'lessons', lessons, 'holidays', hols);
end $$;

-- ---------------------------------------------------------------- 12. tutor_my_slots: same rows as step 1, plus can_change (this centre lets me change this slot), is_group, awaiting_centre
drop function if exists public.tutor_my_slots();
create or replace function public.tutor_my_slots()
returns table(slot_id uuid, org_id uuid, org_name text, weekday int, start_time time, end_time time, subject text,
              student_id uuid, student_name text, student_level text, session_key uuid, timetable_editing text,
              can_change boolean, is_group boolean, awaiting_centre boolean)
language plpgsql stable security definer set search_path = public as $$
begin
  if auth.uid() is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  if not exists (select 1 from memberships m join organisations o on o.id = m.org_id and o.kind = 'centre'
                  where m.user_id = auth.uid() and m.role = 'tutor' and m.status = 'active') then
    raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  return query
    select sl.id, sl.org_id, o.trading_name, sl.weekday::int, sl.start_time, sl.end_time, sl.subject,
           s.id, s.name, s.level, sl.session_key,
           c.mode,
           (c.mode = 'tutors_direct' and c.sw_slots and sl.session_key is null
              and exists (select 1 from student_tutors st where st.org_id = sl.org_id and st.student_id = sl.student_id and st.membership_id = m.id and st.active)),
           (sl.session_key is not null), sl.price_pending
      from recurring_slots sl
      join memberships m on m.id = sl.taught_by and m.org_id = sl.org_id and m.user_id = auth.uid() and m.role = 'tutor' and m.status = 'active'
      join organisations o on o.id = sl.org_id and o.kind = 'centre'
      join students s on s.id = sl.student_id and s.org_id = sl.org_id
     cross join lateral (select coalesce(org_settings_on(sl.org_id, (now() at time zone o.timezone)::date) #>> '{lessons,timetable_editing}', 'admin_only') as mode,
                                coalesce((org_settings_on(sl.org_id, (now() at time zone o.timezone)::date) #>> '{lessons,tutors_edit,weekly_slots}')::boolean, false) as sw_slots) c
     where sl.active and (s.end_date is null or s.end_date >= (now() at time zone o.timezone)::date)
     order by sl.weekday, sl.start_time, s.name, sl.id;
end $$;

-- ---------------------------------------------------------------- 13. staff: what tutors did in the last 7 days (replaces step 2's list; the lesson rows are unchanged)
-- `rows` is now ONE list, newest first, at most 100, each with kind: 'lesson' (a lesson a tutor moved, put back, cancelled or ADDED), 'slot' (a weekly slot a tutor added,
-- changed or stopped) or 'run' (a "Create lessons" press that made lessons). Needs manage_timetable. NO MONEY: awaiting_centre only says the lesson's details need the centre.
create or replace function public.staff_tutor_changes(p_org uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare today date := staff_attendance_gate(p_org, false); rows jsonb; tell boolean;
begin
  if not org_can(p_org, 'manage_timetable') then
    raise exception 'NOT_ALLOWED: your account can''t see timetable changes at this centre' using errcode = '42501'; end if;
  tell := coalesce(org_settings_on(p_org, today) #>> '{lessons,notify_family}', 'list_for_admin') = 'list_for_admin';
  select coalesce(jsonb_agg(u.j order by u.at desc, u.k), '[]'::jsonb) into rows from (
    select * from (
      select x.changed_by_tutor_at as at, x.id::text as k,
             jsonb_build_object(
               'kind', 'lesson', 'lesson_id', x.id, 'what', x.changed_by_tutor_what, 'changed_at', x.changed_by_tutor_at, 'reason', x.changed_by_tutor_reason,
               'tutor_id', x.changed_by_tutor,
               'tutor_name', case when t.id is null or t.status = 'disabled' then 'Former tutor' else coalesce(t.display_name, 'Tutor') end,
               'student_id', s.id, 'student_name', s.name, 'subject', x.subject,
               'lesson_date', x.lesson_date, 'start_time', x.start_time, 'end_time', x.end_time,
               'from_date', x.changed_from_date, 'from_start', x.changed_from_start, 'cancelled', (x.status = 'cancelled'), 'awaiting_centre', x.price_pending,
               'tell_family', tell) as j
        from lessons x
        join students s on s.id = x.student_id and s.org_id = x.org_id
        left join memberships t on t.id = x.changed_by_tutor and t.org_id = x.org_id
       where x.org_id = p_org and x.changed_by_tutor_at >= now() - interval '7 days'
      union all
      select x.changed_by_tutor_at, x.id::text,
             jsonb_build_object(
               'kind', 'slot', 'slot_id', x.id, 'what', x.changed_by_tutor_what, 'changed_at', x.changed_by_tutor_at, 'tutor_id', x.changed_by_tutor,
               'tutor_name', case when t.id is null or t.status = 'disabled' then 'Former tutor' else coalesce(t.display_name, 'Tutor') end,
               'student_id', s.id, 'student_name', s.name, 'subject', x.subject, 'weekday', x.weekday, 'start_time', x.start_time, 'end_time', x.end_time,
               'awaiting_centre', x.price_pending, 'tell_family', tell) as j
        from recurring_slots x
        join students s on s.id = x.student_id and s.org_id = x.org_id
        left join memberships t on t.id = x.changed_by_tutor and t.org_id = x.org_id
       where x.org_id = p_org and x.changed_by_tutor_at >= now() - interval '7 days'
      union all
      select a.at, a.id::text,
             jsonb_build_object(
               'kind', 'run', 'what', 'generated', 'changed_at', a.at, 'tutor_id', (a.after->>'tutor_id')::uuid,
               'tutor_name', case when t.id is null or t.status = 'disabled' then 'Former tutor' else coalesce(t.display_name, 'Tutor') end,
               'created', (a.after->>'created')::int, 'from_date', a.after->>'from', 'to_date', a.after->>'to', 'awaiting_centre', coalesce((a.after->>'awaiting_centre')::int, 0) > 0,
               'tell_family', tell) as j
        from audit_log a
        left join memberships t on t.id = (a.after->>'tutor_id')::uuid and t.org_id = a.org_id
       where a.org_id = p_org and a.action = 'tutor_generate_lessons' and a.at >= now() - interval '7 days' and coalesce((a.after->>'created')::int, 0) > 0
    ) z order by z.at desc, z.k limit 100) u;
  return jsonb_build_object('today', today, 'days', 7, 'tell_family', tell, 'rows', rows);
end $$;

-- ---------------------------------------------------------------- 14. staff: confirm the price of a lesson a tutor made (the one place the price is typed)
-- Needs issue_invoices (owner always): the same people who confirm pending charges. p_rate = S$ per hour, 0 to 1000 (0 = a free lesson, which is a valid answer).
-- p_same_student true = every still-waiting lesson and weekly slot of that student gets the same rate (a tutor's slot makes many lessons). A lesson that is paid, or already
-- on a draft or issued invoice, is not touched. Each lesson is audited with its before and after.
create or replace function public.staff_set_lesson_price(p_org uuid, p_lesson uuid, p_rate numeric, p_same_student boolean default false) returns jsonb
language plpgsql security definer set search_path = public as $$
declare today date := staff_charges_gate(p_org); l lessons; r numeric(8,2); n int := 0; ns int := 0; ids uuid[];
begin
  if p_rate is null or p_rate < 0 or p_rate > 1000 then raise exception 'BAD_RATE: the rate per hour must be between 0 and 1000' using errcode = 'P0001'; end if;
  r := round(p_rate, 2);
  select * into l from lessons where id = p_lesson and org_id = p_org;
  if not found then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  if not l.price_pending then raise exception 'NOT_WAITING: this lesson''s price has already been confirmed' using errcode = 'P0001'; end if;
  select coalesce(array_agg(y.id), '{}') into ids from lessons y
   where y.org_id = p_org and y.price_pending and not y.paid
     and (y.id = l.id or (p_same_student and y.student_id = l.student_id))
     and not exists (select 1 from centre_invoice_lines cl join centre_invoices ci on ci.id = cl.invoice_id and ci.org_id = cl.org_id
                      where cl.lesson_id = y.id and cl.org_id = p_org and ci.status <> 'void');
  update lessons set rate = r, amount = round(round(r * (extract(epoch from (end_time - start_time)) / 3600)::numeric, 2) / greatest(coalesce(split, 1), 1), 2), price_pending = false
   where id = any(ids);
  get diagnostics n = row_count;
  if p_same_student then
    update recurring_slots set rate = r, price_pending = false where org_id = p_org and student_id = l.student_id and price_pending;
    get diagnostics ns = row_count;
  end if;
  insert into audit_log(org_id, actor, action, table_name, row_id, after)
  values (p_org, auth.uid(), 'staff_set_lesson_price', 'lessons', l.id::text, jsonb_build_object('rate', r, 'lessons', n, 'slots', ns, 'student_id', l.student_id));
  return jsonb_build_object('lessons', n, 'slots', ns, 'rate', r);
end $$;

-- ---------------------------------------------------------------- 15. the invoice run: a lesson whose price is not confirmed holds that family's invoice back
-- centre_invoice_run_rows is migration_centre_invoice_run.sql's function with TWO lines added (marked T6 step 3): the column in `base` and one `when` in `cls` that makes a
-- not-yet-confirmed, not-cancelled lesson state 'pending' (the existing held-back state: "charge pending: <student>"). Nothing else in it changes.
create or replace function public.centre_invoice_run_rows(p_org uuid, p_month date, p_today date)
returns table(unit_key text, household_id uuid, unit_student uuid, unit_name text, student_id uuid, student_name text,
              state text, line_kind text, ord int, lesson_id uuid, lesson_date date, start_time time,
              description text, qty int, unit_cents bigint, ref_id uuid)
language plpgsql stable security definer set search_path = public as $$
#variable_conflict use_column
declare ms date := date_trunc('month', p_month)::date; me date := (date_trunc('month', p_month) + interval '1 month - 1 day')::date;
  s jsonb; v_post boolean; v_stu boolean; v_trials boolean; v_sib text; v_sib_bp bigint; v_sib_fix bigint; v_reg bigint; v_mat bigint; v_pct text;
begin
  s := coalesce(org_settings_on(p_org, ms), org_settings_on(p_org, p_today));
  if s is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  v_post   := coalesce(s#>>'{billing,model}', 'postpaid_lessons') = 'postpaid_lessons';
  v_stu    := coalesce(s#>>'{invoicing,grouping}', 'family') = 'student';
  v_trials := coalesce((s#>>'{billing,trials,charged}')::boolean, false);
  v_sib    := coalesce(s#>>'{billing,sibling_discount,type}', 'none');
  v_sib_bp := coalesce((s#>>'{billing,sibling_discount,percent_bp}')::bigint, 0);
  v_sib_fix:= coalesce((s#>>'{billing,sibling_discount,fixed_cents}')::bigint, 0);
  v_reg    := coalesce((s#>>'{billing,one_off_fees,registration_cents}')::bigint, 0);
  v_mat    := coalesce((s#>>'{billing,one_off_fees,materials_cents}')::bigint, 0);
  v_pct    := regexp_replace(to_char(v_sib_bp / 100.0, 'FM990.00'), '\.?0+$', '');

  return query
  with base as (                                   -- the month's lessons that are not already on a draft or issued document
    select l.id as lid, l.student_id as sid, l.lesson_date as ldate, l.start_time as stime, l.subject as subj,
           l.status as lstatus, l.attendance as att, l.trial as is_trial, l.compensation_cents as comp, l.price_pending as ppend,
           lesson_price_cents(l.amount, l.rate, l.start_time, l.end_time) as price
      from lessons l
     where l.org_id = p_org and l.lesson_date between ms and me
       and not exists (select 1 from centre_invoice_lines cl join centre_invoices ci on ci.id = cl.invoice_id and ci.org_id = cl.org_id
                        where cl.lesson_id = l.id and cl.org_id = p_org and ci.status <> 'void')
  ), cls as (
    select b.*,
      case
        when b.is_trial and not v_trials then 'free_trial'
        when b.ppend and b.lstatus <> 'cancelled' then 'pending'             -- T6 step 3: a tutor-made lesson whose price the centre has not confirmed yet
        when v_post and b.att in ('absent', 'cancelled_early', 'late_cancelled') and b.comp is null then 'pending'
        when b.lstatus = 'done' or (not v_post and b.lstatus = 'scheduled') then case when b.price > 0 then 'line' else 'no_price' end
        when v_post and b.lstatus = 'cancelled' and coalesce(b.comp, 0) > 0 then 'line'
        when v_post and b.lstatus = 'scheduled' and b.ldate < p_today then 'unmarked'
        else 'skip' end as st,
      case when b.lstatus = 'cancelled' then b.comp else b.price end as cents
      from base b
  ), keyed as (
    select c.*, st8.name as sname, st8.household_id as hid, st8.created_at as screated,
           case when v_stu then c.sid::text else coalesce(st8.household_id::text, c.sid::text) end as ukey,
           case when v_stu or st8.household_id is null then c.sid end as ustu,
           case when v_stu then st8.name else coalesce(h.name, st8.name) end as uname
      from cls c
      join students st8 on st8.id = c.sid and st8.org_id = p_org
      left join households h on h.id = st8.household_id and h.org_id = p_org
     where c.st <> 'skip'
  ), billed as (select * from keyed where st = 'line'),
  stu as (                                          -- per child billed in this run
    select b.sid, b.hid, min(b.screated) as screated, sum(b.cents)::bigint as total, sum(least(v_sib_fix, b.cents))::bigint as fixed_off,
           bool_or(not b.is_trial) as any_nontrial,
           (array_agg(b.ukey))[1] as ukey, (array_agg(b.ustu))[1] as ustu, (array_agg(b.uname))[1] as uname, (array_agg(b.sname))[1] as sname
      from billed b group by b.sid, b.hid
  ), ranked as (
    select st.*, case when st.hid is null then 1 else row_number() over (partition by st.hid order by st.screated, st.sid) end as rn from stu st
  ), disc as (
    select r.*, case v_sib when 'percent' then least(r.total, centre_div_round(r.total * v_sib_bp, 10000))
                           when 'fixed'   then least(r.total, r.fixed_off) else 0 end as off
      from ranked r where r.rn >= 2
  )
  select b.ukey, b.hid, b.ustu, b.uname, b.sid, b.sname, 'line'::text, 'lesson'::text, 0, b.lid, b.ldate, b.stime,
         left(coalesce(nullif(trim(b.subj), ''), 'Lesson'), 60) || case when b.lstatus = 'cancelled' then ' (cancelled, charged)' else '' end
           || ' · ' || to_char(b.ldate, 'Dy DD Mon') || ', ' || to_char(b.stime, 'FMHH12:MIam'),
         1, b.cents, null::uuid
    from billed b
  union all                                         -- signals the screen explains (no money on them)
  select k.ukey, k.hid, k.ustu, k.uname, k.sid, k.sname, k.st, 'lesson', 0, k.lid, k.ldate, k.stime, null::text, 1, 0::bigint, null::uuid
    from keyed k where k.st in ('pending', 'unmarked', 'no_price', 'free_trial')
  union all
  select d.ukey, d.hid, d.ustu, d.uname, d.sid, d.sname, 'line', 'sibling_discount', 1, null::uuid, null::date, null::time,
         case v_sib when 'percent' then 'Sibling discount (' || v_pct || '%)' else 'Sibling discount (S$' || to_char(v_sib_fix / 100.0, 'FM999990.00') || ' off each lesson)' end,
         1, -d.off, null::uuid
    from disc d where d.off > 0
  union all
  select r.ukey, r.hid, r.ustu, r.uname, r.sid, r.sname, 'line', k.kind, case k.kind when 'registration' then 2 else 3 end, null::uuid, null::date, null::time,
         case k.kind when 'registration' then 'Registration fee' else 'Materials fee' end, 1, k.amt, null::uuid
    from stu r cross join lateral (values ('registration', v_reg), ('materials', v_mat)) k(kind, amt)
   where r.any_nontrial and k.amt > 0
     and not exists (select 1 from centre_invoice_lines fl join centre_invoices fi on fi.id = fl.invoice_id and fi.org_id = fl.org_id
                      where fl.org_id = p_org and fl.student_id = r.sid and fl.fee_kind = k.kind and fi.status <> 'void')
  union all                                         -- a draft already exists for this household / student and month
  select coalesce(ci.student_id::text, ci.household_id::text), ci.household_id, ci.student_id,
         case when v_stu then sd.name else coalesce(hd.name, sd.name) end, ci.student_id, sd.name, 'draft_exists', 'invoice', 0,
         null::uuid, null::date, null::time, null::text, 1, ci.total_cents, ci.id
    from centre_invoices ci
    left join households hd on hd.id = ci.household_id and hd.org_id = ci.org_id
    left join students sd on sd.id = ci.student_id and sd.org_id = ci.org_id
   where ci.org_id = p_org and ci.kind = 'lesson' and ci.status = 'draft' and ci.period_start = ms;
end $$;

-- ---------------------------------------------------------------- who may call what
do $$
declare f text;
begin
  foreach f in array array['tutor_my_students()', 'tutor_add_lesson(uuid,date,time,time,text,text)', 'tutor_save_slot(uuid,uuid,int,time,time,text)', 'tutor_stop_slot(uuid)',
                           'tutor_generate_lessons(uuid,date,date)', 'tutor_my_schedule(date,date)', 'tutor_my_slots()', 'staff_tutor_changes(uuid)',
                           'staff_set_lesson_price(uuid,uuid,numeric,boolean)'] loop
    execute format('revoke all on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
  foreach f in array array['tutor_own_gate(uuid,uuid,text)', 'tutor_own_limit_check(uuid,jsonb)', 'tutor_changes_used(uuid,uuid,text)', 'tutor_basis_for(uuid,uuid)',
                           'tutor_own_insert_lesson(uuid,uuid,uuid,date,time,time,text,text)', 'tutor_own_insert_slot(uuid,uuid,uuid,int,time,time,text)',
                           'tutor_own_generate(uuid,uuid,date,date,boolean,int,text)', 'centre_invoice_run_rows(uuid,date,date)', 'tutor_change_block(uuid,text)'] loop
    execute format('revoke all on function public.%s from public, anon, authenticated', f);
  end loop;
end $$;

-- #####################################################################################################
-- ### PART 2 of 7 — centre import stage A: dry run, commit, undo, history, billing-start setting
-- ### source branch: claude/t33-i1-stage-a   file: db/migration_import.sql   undo: db/migration_import_down.sql
-- ### (if an error appears, search this file for the nearest "### PART" line above the error line: that is the part that failed)
-- #####################################################################################################
-- =====================================================================================================
-- T33 I1 — centre import, stage A (families, students, tutors, weekly lessons)        undo: migration_import_down.sql
-- =====================================================================================================
-- Run order everywhere: org_foundation → billing → attendance → tutor_access → org_delete → function_lockdown → org_separation → import.
-- Needs migration_tutor_access.sql (memberships.id + organisation key). Run on the DEV project first. Safe to run twice.
--
-- WHAT THIS ADDS
--   1. Import bookkeeping: import_batches (one row per committed import) and import_items (one row per record an import created,
--      with the owner's own code for it and a fingerprint of the row as it was created). No cell values are kept: ids, codes, counts.
--   2. import_dry_run(org, payload)            check everything, write NOTHING (works on any centre the caller owns)
--      import_commit(org, payload, hashes)     the same checks, then ONE all-or-nothing transaction that creates the records
--      import_existing(org)                    the owner's codes already imported (so a later file can point at them)
--      import_history(org)                     batches, newest first, with "can be undone until"
--      import_undo_preview(batch) / import_undo(batch)   remove what a batch created, but ONLY rows nobody has since edited, marked or
--                                              invoiced; everything else is kept and reported
--   3. A centre setting billing.starts_from (a date): the invoice run ignores lessons before it (org_billing_start(org) reads it).
--   4. Three optional columns the import fills: students.online_link, students.start_date, recurring_slots.taught_by (the tutor of
--      a weekly lesson: memberships.id, same organisation only; a removed tutor leaves the slot with no tutor).
--
-- RULES (owner's decisions, 2026-11-26)
--   * OWNER ONLY, CENTRES ONLY. Anyone else (staff, tutor, parent, anonymous, a solo tutor, a non-member) gets NOT_FOUND, same as a
--     missing organisation, so nothing can be probed.
--   * CREATE-ONLY: never updates or deletes existing rows (undo deletes only rows its own batch created). A row whose code already
--     exists is skipped; if its content differs it is skipped with a warning (the import never overwrites).
--   * IDEMPOTENT: the match key is the owner's own code per row: family_ref, student_ref, tutor email, student+tutor+day+start.
--     The same file twice creates nothing the second time and records no batch.
--   * The browser is never trusted: every rule is checked again here, and problems come back as DATA (file, line, column, code),
--     never as an exception message, so no cell value can land in a database log.
--   * No email, no queue, no login is created. Tutors become memberships with status 'invited' and no user (org_invite, the screen's rule).
--     Lessons are not created either (the weekly lesson is the recurring slot; lessons come from the usual generation). Past lessons,
--     deposits, unpaid invoices and pay rates are NOT part of stage A.
--   * Per-row audit rows are switched off while an import or its undo runs (a batch of 3,000 rows would copy every name into the
--     audit log, which an undo could never remove). Instead ONE audit row per commit and per undo: who, when, counts, file hashes.
-- =====================================================================================================

-- ---------------------------------------------------------------- columns the import fills
alter table public.students add column if not exists online_link text;
alter table public.students add column if not exists start_date date;
alter table public.recurring_slots add column if not exists taught_by uuid;
create unique index if not exists memberships_id_org on public.memberships(id, org_id);
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'recurring_slots_taught_by_same_org') then
    alter table public.recurring_slots add constraint recurring_slots_taught_by_same_org
      foreign key (taught_by, org_id) references public.memberships(id, org_id) on delete set null (taught_by);
  end if;
end $$;
create index if not exists recurring_slots_taught_by on public.recurring_slots(taught_by) where taught_by is not null;

-- ---------------------------------------------------------------- bookkeeping tables (no browser write policy at all)
create table if not exists public.import_batches (
  id           uuid primary key default gen_random_uuid(),
  org_id       uuid not null references public.organisations(id) on delete cascade,
  created_by   uuid,
  created_at   timestamptz not null default now(),
  stage        text not null default 'A',
  status       text not null default 'committed' check (status in ('committed','partly_undone','undone')),
  counts       jsonb not null default '{}',
  file_hashes  jsonb not null default '{}',
  undo_until   timestamptz not null,
  undone_at    timestamptz,
  undo_report  jsonb,
  unique (id, org_id)
);
create index if not exists import_batches_org on public.import_batches(org_id, created_at desc);

create table if not exists public.import_items (
  org_id       uuid not null references public.organisations(id) on delete cascade,
  batch_id     uuid not null,
  kind         text not null check (kind in ('family','guardian','student','tutor','slot')),
  key          text,                                    -- the owner's own code, lowercased; null for guardians
  tbl          text not null check (tbl in ('households','guardians','students','memberships','recurring_slots')),
  row_id       uuid not null,
  fp           text not null,                           -- fingerprint of the row as the import created it
  kept_reason  text,                                    -- set by an undo that could not remove it
  primary key (batch_id, tbl, row_id),
  foreign key (batch_id, org_id) references public.import_batches(id, org_id) on delete cascade
);
create unique index if not exists import_items_key on public.import_items(org_id, kind, key) where key is not null;
create index if not exists import_items_row on public.import_items(tbl, row_id);

alter table public.import_batches enable row level security;
alter table public.import_items enable row level security;
drop policy if exists import_batches_read on public.import_batches;
create policy import_batches_read on public.import_batches for select using (org_can(org_id, 'owner'));
-- import_items: no policy (the owner reads history through import_history); nobody writes either table except the functions below
revoke all on public.import_batches, public.import_items from anon, authenticated;
grant select on public.import_batches to authenticated;

-- ---------------------------------------------------------------- the billing start setting
-- billing.starts_from = a date (YYYY-MM-DD) or empty/null. The invoice run ignores lessons dated before it.
create or replace function public.org_validate_settings(s jsonb) returns void language plpgsql immutable set search_path = public as $$
declare k text; v jsonb; r record; bs text;
begin
  if coalesce((s->>'schema_version')::int, 0) <> 1 then raise exception 'Unknown settings schema_version'; end if;
  foreach k in array array['profile','calendar','billing','invoicing','payments','lessons','tutor_pay','data'] loop
    if jsonb_typeof(s->k) is distinct from 'object' then raise exception 'Settings section "%" is missing', k; end if;
  end loop;
  if (s#>>'{profile,gst_registered}')::boolean and not ((s#>>'{profile,gst_rate_bp}')::int between 0 and 5000) then
    raise exception 'GST rate must be between 0%% and 50%%'; end if;
  if s#>>'{billing,model}' not in ('prepaid_packages','fixed_in_advance','postpaid_lessons','pay_per_lesson') then
    raise exception 'Unknown billing model'; end if;
  if s#>>'{tutor_pay,mode}' not in ('off','report','full') then raise exception 'Unknown tutor pay mode'; end if;
  if s#>>'{tutor_pay,payable_when}' not in ('taught','parent_paid') then raise exception 'Unknown payable rule'; end if;
  if s#>>'{invoicing,grouping}' not in ('family','student') then raise exception 'Unknown invoice grouping'; end if;
  if s#>>'{lessons,attendance_by}' not in ('tutor','admin') then raise exception 'Unknown attendance setting'; end if;
  if s#>>'{lessons,cancellations_marked_by}' not in ('admin','tutor') then raise exception 'Unknown cancellation setting'; end if;
  if s#>>'{lessons,compensation_entered_by}' not in ('admin','tutor') then raise exception 'Unknown compensation setting'; end if;
  if s#>>'{lessons,trials_flagged_by}' not in ('admin','tutor') then raise exception 'Unknown trial setting'; end if;
  if s#>>'{lessons,attendance_window_days}' is not null and (s#>>'{lessons,attendance_window_days}' !~ '^[0-9]{1,3}$'
     or (s#>>'{lessons,attendance_window_days}')::int not between 1 and 60) then raise exception 'Attendance window must be 1-60 days'; end if;
  if not (s#>'{payments,modes}' ?| array['manual_paynow','statement_matching','hitpay','stripe']) then
    raise exception 'Pick at least one way for parents to pay'; end if;
  -- T4 S0 (centre money options). Every new key is optional, so settings saved before this migration stay valid;
  -- a key that is present must be right. assets/js/org-settings.js holds the labels and defaults (tests/org-settings.test.js compares the enums).
  if s#>>'{tutor_pay,rate_model}' is not null and s#>>'{tutor_pay,rate_model}' not in ('per_lesson','per_hour','per_student_lesson','monthly_fixed','percent_of_fee') then raise exception 'Unknown tutor pay rate'; end if;
  if s#>>'{tutor_pay,percent_base}' is not null and s#>>'{tutor_pay,percent_base}' not in ('billed_after_discounts','list_price') then raise exception 'Unknown percentage pay base'; end if;
  if s#>>'{tutor_pay,part_payments}' is not null and s#>>'{tutor_pay,part_payments}' not in ('after_full','pro_rata') then raise exception 'Unknown part-payment pay rule'; end if;
  if s#>>'{tutor_pay,cancelled_lessons}' is not null and s#>>'{tutor_pay,cancelled_lessons}' not in ('pay_if_charged','pay_rate','pay_nothing') then raise exception 'Unknown cancelled-lesson pay rule'; end if;
  if s#>>'{tutor_pay,group_count}' is not null and s#>>'{tutor_pay,group_count}' not in ('attended','enrolled') then raise exception 'Unknown group pay count'; end if;
  if s#>>'{billing,deposit,mode}' is not null and s#>>'{billing,deposit,mode}' not in ('none','fixed','percent_first_month') then raise exception 'Unknown deposit mode'; end if;
  if s#>>'{billing,deposit,due}' is not null and s#>>'{billing,deposit,due}' not in ('with_first_invoice','before_first_lesson') then raise exception 'Unknown deposit due rule'; end if;
  if s#>>'{billing,deposit,waived_by}' is not null and s#>>'{billing,deposit,waived_by}' not in ('owner','issue_invoices','nobody') then raise exception 'Unknown deposit waiver rule'; end if;
  if s#>>'{billing,deposit,release}' is not null and s#>>'{billing,deposit,release}' not in ('refund_full','refund_less_unpaid','admin_decides') then raise exception 'Unknown deposit release rule'; end if;
  if s#>>'{billing,deposit,refund_approved_by}' is not null and s#>>'{billing,deposit,refund_approved_by}' not in ('owner','staff','four_eyes') then raise exception 'Unknown deposit refund approver'; end if;
  if s#>>'{billing,late_fee,repeat}' is not null and s#>>'{billing,late_fee,repeat}' not in ('none','once','monthly') then raise exception 'Unknown late fee repeat'; end if;
  if s#>>'{billing,late_fee,type}' is not null and s#>>'{billing,late_fee,type}' not in ('fixed','percent') then raise exception 'Unknown late fee type'; end if;
  if s#>>'{billing,late_fee,show_as}' is not null and s#>>'{billing,late_fee,show_as}' not in ('next_invoice_line','own_invoice') then raise exception 'Unknown late fee placement'; end if;
  if s#>>'{billing,late_fee,waived_by}' is not null and s#>>'{billing,late_fee,waived_by}' not in ('owner','issue_invoices') then raise exception 'Unknown late fee waiver rule'; end if;
  if s#>>'{lessons,class_type}' is not null and s#>>'{lessons,class_type}' not in ('one_to_one','group','both') then raise exception 'Unknown class type'; end if;
  foreach k in array array['{billing,deposit,taxable}','{billing,deposit,top_up}','{billing,deposit,set_off_unpaid}','{billing,deposit,final_month}','{billing,trials,charged}'] loop
    v := s #> k::text[];
    if v is not null and jsonb_typeof(v) not in ('boolean','null') then raise exception 'Setting % must be yes or no', k; end if;
  end loop;
  for r in select * from (values
    ('{billing,deposit,percent_bp}', 0, 10000, 'Deposit percentage must be between 0% and 100%'),
    ('{billing,deposit,forfeit_notice_days}', 0, 90, 'Deposit notice must be 0-90 days'),
    ('{billing,late_fee,percent_bp}', 0, 10000, 'Late fee percentage must be between 0% and 100%'),
    ('{billing,late_fee,after_days}', 0, 365, 'Late fee grace period must be 0-365 days'),
    ('{billing,late_fee,cap_cents}', 0, 100000000, 'Late fee limit must be a whole number of cents, 0 to 100000000'),
    ('{billing,late_fee,amount_cents}', 0, 100000000, 'Late fee amount must be a whole number of cents, 0 to 100000000'),
    ('{billing,one_off_fees,deposit_cents}', 0, 100000000, 'Deposit amount must be a whole number of cents, 0 to 100000000'),
    ('{profile,next_invoice_number}', 1, 999999999, 'Next invoice number must be a whole number, 1 or more')
  ) as c(p, lo, hi, msg) loop
    v := s #> r.p::text[];
    if v is not null and jsonb_typeof(v) <> 'null' and not (case when jsonb_typeof(v) = 'number' and v::text ~ '^[0-9]{1,12}$'
         then (v#>>'{}')::bigint between r.lo and r.hi else false end) then
      raise exception '%', r.msg; end if;
  end loop;
  -- a percentage mode needs a real percentage (1 = 0.01%)
  if s#>>'{billing,deposit,mode}' = 'percent_first_month' and coalesce((s#>>'{billing,deposit,percent_bp}')::int, 0) < 1 then
    raise exception 'Deposit percentage must be between 0.01%% and 100%%'; end if;
  if s#>>'{billing,late_fee,type}' = 'percent' and coalesce((s#>>'{billing,late_fee,percent_bp}')::int, 0) < 1 then
    raise exception 'Late fee percentage must be between 0.01%% and 100%%'; end if;
  -- T6 step 2 (tutors change their own lessons). Every key is optional; a key that is present must be right. assets/js/org-settings.js has the labels and defaults.
  if s#>>'{lessons,timetable_editing}' is not null and s#>>'{lessons,timetable_editing}' not in ('admin_only','tutors_direct','tutors_propose') then raise exception 'Unknown timetable editing setting'; end if;
  if s#>>'{lessons,notify_family}' is not null and s#>>'{lessons,notify_family}' not in ('off','list_for_admin') then raise exception 'Unknown family notice setting'; end if;
  if s#>'{lessons,tutors_edit}' is not null and jsonb_typeof(s#>'{lessons,tutors_edit}') not in ('object','null') then raise exception 'Tutor editing switches are malformed'; end if;
  foreach k in array array['{lessons,tutors_edit,postpone}','{lessons,tutors_edit,cancel}','{lessons,tutors_edit,weekly_slots}','{lessons,tutors_edit,generate}','{lessons,tutors_edit,one_off}','{lessons,tutors_edit,link}'] loop
    v := s #> k::text[];
    if v is not null and jsonb_typeof(v) not in ('boolean','null') then raise exception 'Setting % must be yes or no', k; end if;
  end loop;
  for r in select * from (values
    ('{lessons,min_notice_hours}', 0, 168, 'Notice before a change must be 0-168 hours'),
    ('{lessons,max_changes_per_month}', 0, 500, 'Changes per tutor per month must be 0-500 (0 = no limit)')
  ) as c(p, lo, hi, msg) loop
    v := s #> r.p::text[];
    if v is not null and jsonb_typeof(v) <> 'null' and not (case when jsonb_typeof(v) = 'number' and v::text ~ '^[0-9]{1,4}$'
         then (v#>>'{}')::bigint between r.lo and r.hi else false end) then
      raise exception '%', r.msg; end if;
  end loop;
  -- billing starts from: empty, or a real date between 2020-01-01 and 2100-01-01
  if s#>'{billing,starts_from}' is not null and jsonb_typeof(s#>'{billing,starts_from}') <> 'null' then
    if jsonb_typeof(s#>'{billing,starts_from}') <> 'string' then raise exception 'Billing start must be a date'; end if;
    bs := s#>>'{billing,starts_from}';
    if bs <> '' then
      if bs !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then raise exception 'Billing start must be a date (YYYY-MM-DD)'; end if;
      begin perform make_date(substr(bs,1,4)::int, substr(bs,6,2)::int, substr(bs,9,2)::int);
      exception when others then raise exception 'Billing start must be a real date'; end;
      if bs < '2020-01-01' or bs > '2100-01-01' then raise exception 'Billing start must be between 2020 and 2100'; end if;
    end if;
  end if;
end $$;

-- The date billing starts from, as of today (null = every lesson can be billed). Read as of TODAY: it is a cut-off, not a fee rule.
create or replace function public.org_billing_start(p_org uuid) returns date
language plpgsql stable security definer set search_path = public as $$
declare v text;
begin
  v := org_settings_on(p_org, current_date) #>> '{billing,starts_from}';
  if v is null or v = '' or v !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then return null; end if;
  return v::date;
end $$;
revoke all on function public.org_billing_start(uuid) from public, anon;
grant execute on function public.org_billing_start(uuid) to authenticated, service_role;

-- ---------------------------------------------------------------- small internal helpers
create or replace function public.import_fp(j jsonb) returns text language sql immutable set search_path = public as $$
  select md5((j - 'gcal_event_id')::text) $$;
create or replace function public.import_try_date(s text) returns date language plpgsql immutable set search_path = public as $$
begin
  if s is null or s !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then return null; end if;
  return make_date(substr(s,1,4)::int, substr(s,6,2)::int, substr(s,9,2)::int);
exception when others then return null; end $$;
create or replace function public.import_minutes(s text) returns int language sql immutable set search_path = public as $$
  select case when s ~ '^([01]?[0-9]|2[0-3]):[0-5][0-9]$' then split_part(s, ':', 1)::int * 60 + split_part(s, ':', 2)::int end $$;
create or replace function public.import_row_exists(p_tbl text, p_id uuid) returns boolean language sql stable set search_path = public as $$
  select case p_tbl when 'households' then exists (select 1 from households where id = p_id)
                    when 'guardians' then exists (select 1 from guardians where id = p_id)
                    when 'students' then exists (select 1 from students where id = p_id)
                    when 'memberships' then exists (select 1 from memberships where id = p_id)
                    when 'recurring_slots' then exists (select 1 from recurring_slots where id = p_id) else false end $$;
-- a lesson somebody has worked on: marked, charged, paid, noted, moved, hand-added or on an invoice
create or replace function public.import_lesson_touched(l lessons) returns boolean language sql stable set search_path = public as $$
  select l.status <> 'scheduled' or l.attendance is not null or l.paid or l.compensation is not null or l.postponed or l.one_off or l.trial
      or l.topics is not null or l.homework is not null or l.remarks is not null
      or exists (select 1 from invoices i where i.org_id = l.org_id and jsonb_typeof(i.data->'lesson_ids') = 'array' and i.data->'lesson_ids' ? l.id::text) $$;

-- ---------------------------------------------------------------- the run: check everything, and (commit) write it, in ONE call
-- p_payload = { families:[…], students:[…], tutors:[…], weekly_lessons:[…] }, built by assets/js/import-core.js (buildPayload).
-- Returns jsonb { ok, errors:[{file,line,column,code}] (first 300), error_count, warnings, created:{…}, skipped:{…}, batch_id, undo_until }.
create or replace function public.import_run_a(p_org uuid, p_payload jsonb, p_commit boolean, p_hashes jsonb)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  me uuid := auth.uid(); v_n int; v_errs jsonb; v_warn jsonb; v_batch uuid := gen_random_uuid(); v_until timestamptz := now() + interval '7 days';
  v_created jsonb; v_skipped jsonb; v_hashes jsonb; tr record; m uuid; tn text;
begin
  if me is null or not org_can(p_org, 'owner')
     or not exists (select 1 from organisations o where o.id = p_org and o.kind = 'centre' and o.status <> 'suspended') then
    raise exception 'NOT_FOUND' using errcode = 'P0001';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('import:' || p_org::text, 0));    -- one import per centre at a time

  -- (only drop what an earlier call in this same transaction left: DROP is refused in a read-only transaction, CREATE TEMP is not)
  foreach tn in array array['imp_f','imp_s','imp_t','imp_w','imp_err','imp_live','imp_tut','imp_nf','imp_ng','imp_ns','imp_nt','imp_nw','imp_wres'] loop
    if to_regclass('pg_temp.' || tn) is not null then execute 'drop table pg_temp.' || tn; end if;
  end loop;
  create temp table imp_err(file text, line int, col text, code text) on commit drop;
  if jsonb_typeof(p_payload) is distinct from 'object' then
    return jsonb_build_object('ok', false, 'errors', jsonb_build_array(jsonb_build_object('file','payload','line',0,'column','','code','BAD_PAYLOAD')), 'error_count', 1);
  end if;
  if coalesce(jsonb_array_length(p_payload->'families'), 0) > 18000 or coalesce(jsonb_array_length(p_payload->'students'), 0) > 3000
     or coalesce(jsonb_array_length(p_payload->'tutors'), 0) > 1500 or coalesce(jsonb_array_length(p_payload->'weekly_lessons'), 0) > 20000 then
    return jsonb_build_object('ok', false, 'errors', jsonb_build_array(jsonb_build_object('file','payload','line',0,'column','','code','TOO_MANY_ROWS')), 'error_count', 1);
  end if;

  -- ---- load (all cells as trimmed text; empty = null). A payload of the wrong shape is refused as data.
  begin
    create temp table imp_f on commit drop as
      select r.line, nullif(btrim(r.family_ref), '') family_ref, lower(nullif(btrim(r.family_ref), '')) fk, nullif(btrim(r.family_name), '') family_name,
             nullif(btrim(r.guardian_name), '') guardian_name, nullif(btrim(r.relation), '') relation, nullif(btrim(r.phone), '') phone,
             lower(nullif(btrim(r.email), '')) email, r.main
      from jsonb_to_recordset(coalesce(p_payload->'families', '[]'::jsonb)) as r(line int, family_ref text, family_name text, guardian_name text, relation text, phone text, email text, main boolean);
    create temp table imp_s on commit drop as
      select r.line, nullif(btrim(r.student_ref), '') student_ref, lower(nullif(btrim(r.student_ref), '')) sk, nullif(btrim(r.family_ref), '') family_ref,
             lower(nullif(btrim(r.family_ref), '')) fk, nullif(btrim(r.student_name), '') student_name, nullif(btrim(r.level), '') level,
             nullif(btrim(r.lesson_location), '') location, nullif(btrim(r.online_link), '') online_link, nullif(btrim(r.start_date), '') start_date,
             nullif(btrim(r.notes), '') notes
      from jsonb_to_recordset(coalesce(p_payload->'students', '[]'::jsonb)) as r(line int, student_ref text, family_ref text, student_name text, level text, lesson_location text, online_link text, start_date text, notes text);
    create temp table imp_t on commit drop as
      select r.line, lower(nullif(btrim(r.tutor_email), '')) email, nullif(btrim(r.tutor_name), '') tutor_name, nullif(btrim(r.phone), '') phone,
             nullif(btrim(r.subjects), '') subjects, nullif(btrim(r.employment), '') employment
      from jsonb_to_recordset(coalesce(p_payload->'tutors', '[]'::jsonb)) as r(line int, tutor_email text, tutor_name text, phone text, subjects text, employment text);
    create temp table imp_w on commit drop as
      select r.line, nullif(btrim(r.student_ref), '') student_ref, lower(nullif(btrim(r.student_ref), '')) sk, lower(nullif(btrim(r.tutor_email), '')) email,
             r.day, import_minutes(nullif(btrim(r.start), '')) smin, import_minutes(nullif(btrim(r."end"), '')) emin,
             nullif(btrim(r.subject), '') subject, nullif(btrim(r.level), '') level, r.rate_cents
      from jsonb_to_recordset(coalesce(p_payload->'weekly_lessons', '[]'::jsonb)) as r(line int, student_ref text, tutor_email text, day int, start text, "end" text, subject text, level text, rate_cents int);
  exception when others then
    return jsonb_build_object('ok', false, 'errors', jsonb_build_array(jsonb_build_object('file','payload','line',0,'column','','code','BAD_PAYLOAD')), 'error_count', 1);
  end;

  -- ---- what is already in this centre (live = the imported row still exists)
  create temp table imp_live on commit drop as
    select i.kind, i.key, i.tbl, i.row_id from import_items i
    where i.org_id = p_org and i.key is not null and import_row_exists(i.tbl, i.row_id);
  create temp table imp_tut on commit drop as
    select m.id, m.role, m.status, lower(coalesce(m.invited_email, (select u.email from auth.users u where u.id = m.user_id))) em
    from memberships m where m.org_id = p_org;
  create index on imp_tut(em);

  -- =========================================================== validation (set-based; every rule the page also checks)
  -- families.csv
  insert into imp_err select 'families', line, 'family_ref', 'REQUIRED' from imp_f where family_ref is null;
  insert into imp_err select 'families', line, 'family_ref', 'TOO_LONG' from imp_f where char_length(family_ref) > 40;
  insert into imp_err select 'families', line, 'family_name', 'REQUIRED' from imp_f where family_name is null;
  insert into imp_err select 'families', line, 'family_name', 'TOO_LONG' from imp_f where char_length(family_name) > 120;
  insert into imp_err select 'families', line, 'guardian_name', 'REQUIRED' from imp_f where guardian_name is null;
  insert into imp_err select 'families', line, 'guardian_name', 'TOO_LONG' from imp_f where char_length(guardian_name) > 120;
  insert into imp_err select 'families', line, 'relation', 'TOO_LONG' from imp_f where char_length(relation) > 40;
  insert into imp_err select 'families', line, 'phone', 'BAD_PHONE' from imp_f where phone is not null and regexp_replace(phone, '[\s\-()]', '', 'g') !~ '^\+?[0-9]{6,15}$';
  insert into imp_err select 'families', line, 'email', 'BAD_EMAIL' from imp_f where email is not null and (email !~ '^[^@\s,;]+@[^@\s,;]+\.[^@\s,;]+$' or char_length(email) > 254);
  insert into imp_err select 'families', line, 'phone', 'NEED_CONTACT' from imp_f where phone is null and email is null and guardian_name is not null;
  insert into imp_err select 'families', f.line, 'family_name', 'FAMILY_NAME_MISMATCH' from imp_f f
    where f.fk is not null and f.family_name is not null and f.family_name <> (select x.family_name from imp_f x where x.fk = f.fk and x.family_name is not null order by x.line limit 1);
  insert into imp_err select 'families', line, 'guardian_name', 'TOO_MANY_GUARDIANS' from
    (select line, row_number() over (partition by fk order by line) n from imp_f where fk is not null) q where n > 6;
  insert into imp_err select 'families', line, 'main', 'MULTIPLE_MAIN' from
    (select line, row_number() over (partition by fk order by line) n from imp_f where fk is not null and main) q where n > 1;
  insert into imp_err select 'families', line, 'guardian_name', 'DUPLICATE_ROW' from
    (select line, row_number() over (partition by fk, lower(guardian_name), phone, email order by line) n from imp_f where fk is not null and guardian_name is not null) q where n > 1;

  -- students.csv
  insert into imp_err select 'students', line, 'student_ref', 'REQUIRED' from imp_s where student_ref is null;
  insert into imp_err select 'students', line, 'student_ref', 'TOO_LONG' from imp_s where char_length(student_ref) > 40;
  insert into imp_err select 'students', line, 'family_ref', 'REQUIRED' from imp_s where family_ref is null;
  insert into imp_err select 'students', line, 'student_name', 'REQUIRED' from imp_s where student_name is null;
  insert into imp_err select 'students', line, 'student_name', 'TOO_LONG' from imp_s where char_length(student_name) > 120;
  insert into imp_err select 'students', line, 'level', 'TOO_LONG' from imp_s where char_length(level) > 40;
  insert into imp_err select 'students', line, 'lesson_location', 'TOO_LONG' from imp_s where char_length(location) > 120;
  insert into imp_err select 'students', line, 'online_link', 'BAD_URL' from imp_s where online_link is not null and (online_link !~* '^https://[^\s/]+\.[^\s/]+\S*$' or char_length(online_link) > 300);
  insert into imp_err select 'students', line, 'start_date', 'REQUIRED' from imp_s where start_date is null;
  insert into imp_err select 'students', line, 'start_date', 'BAD_DATE' from imp_s where start_date is not null and import_try_date(start_date) is null;
  insert into imp_err select 'students', line, 'start_date', 'FUTURE_DATE' from imp_s where import_try_date(start_date) > current_date + 365;
  insert into imp_err select 'students', line, 'notes', 'TOO_LONG' from imp_s where char_length(notes) > 1000;
  insert into imp_err select 'students', line, 'student_ref', 'DUPLICATE_KEY' from
    (select line, row_number() over (partition by sk order by line) n from imp_s where sk is not null) q where n > 1;
  insert into imp_err select 'students', s.line, 'family_ref', 'UNKNOWN_FAMILY' from imp_s s
    where s.fk is not null and not exists (select 1 from imp_f f where f.fk = s.fk) and not exists (select 1 from imp_live l where l.kind = 'family' and l.key = s.fk);
  insert into imp_err select 'students', line, 'student_name', 'DUPLICATE_STUDENT_NAME' from
    (select line, row_number() over (partition by fk, lower(student_name) order by line) n from imp_s where fk is not null and student_name is not null) q where n > 1;

  -- tutors.csv
  insert into imp_err select 'tutors', line, 'tutor_email', 'REQUIRED' from imp_t where email is null;
  insert into imp_err select 'tutors', line, 'tutor_email', 'BAD_EMAIL' from imp_t where email is not null and (email !~ '^[^@\s,;]+@[^@\s,;]+\.[^@\s,;]+$' or char_length(email) > 254);
  insert into imp_err select 'tutors', line, 'tutor_name', 'REQUIRED' from imp_t where tutor_name is null;
  insert into imp_err select 'tutors', line, 'tutor_name', 'TOO_LONG' from imp_t where char_length(tutor_name) > 120;
  insert into imp_err select 'tutors', line, 'phone', 'BAD_PHONE' from imp_t where phone is not null and regexp_replace(phone, '[\s\-()]', '', 'g') !~ '^(\+?65)?[689][0-9]{7}$';
  insert into imp_err select 'tutors', line, 'subjects', 'TOO_LONG' from imp_t where char_length(subjects) > 200;
  insert into imp_err select 'tutors', line, 'employment', 'REQUIRED' from imp_t where employment is null;
  insert into imp_err select 'tutors', line, 'employment', 'BAD_VALUE' from imp_t where employment is not null and employment not in ('employee', 'freelancer');
  insert into imp_err select 'tutors', line, 'tutor_email', 'DUPLICATE_KEY' from
    (select line, row_number() over (partition by email order by line) n from imp_t where email is not null) q where n > 1;
  insert into imp_err select 'tutors', t.line, 'tutor_email', 'TUTOR_OTHER_ROLE' from imp_t t
    where t.email is not null and exists (select 1 from imp_tut x where x.em = t.email and x.role <> 'tutor');

  -- weekly_lessons.csv
  insert into imp_err select 'weekly_lessons', line, 'student_ref', 'REQUIRED' from imp_w where student_ref is null;
  insert into imp_err select 'weekly_lessons', line, 'tutor_email', 'REQUIRED' from imp_w where email is null;
  insert into imp_err select 'weekly_lessons', line, 'tutor_email', 'BAD_EMAIL' from imp_w where email is not null and (email !~ '^[^@\s,;]+@[^@\s,;]+\.[^@\s,;]+$' or char_length(email) > 254);
  insert into imp_err select 'weekly_lessons', line, 'day', 'BAD_VALUE' from imp_w where day is null or day not between 0 and 6;
  insert into imp_err select 'weekly_lessons', line, 'start', 'BAD_TIME' from imp_w where smin is null;
  insert into imp_err select 'weekly_lessons', line, 'end', 'BAD_TIME' from imp_w where emin is null;
  insert into imp_err select 'weekly_lessons', line, 'end', 'END_BEFORE_START' from imp_w where smin is not null and emin is not null and emin <= smin;
  insert into imp_err select 'weekly_lessons', line, 'end', 'BAD_DURATION' from imp_w where smin is not null and emin is not null and emin > smin and (emin - smin < 15 or emin - smin > 480);
  insert into imp_err select 'weekly_lessons', line, 'subject', 'TOO_LONG' from imp_w where char_length(subject) > 60;
  insert into imp_err select 'weekly_lessons', line, 'level', 'TOO_LONG' from imp_w where char_length(level) > 40;
  insert into imp_err select 'weekly_lessons', line, 'family_rate_per_hour', 'REQUIRED' from imp_w where rate_cents is null;
  insert into imp_err select 'weekly_lessons', line, 'family_rate_per_hour', 'OUT_OF_RANGE' from imp_w where rate_cents is not null and rate_cents not between 0 and 100000;
  insert into imp_err select 'weekly_lessons', w.line, 'student_ref', 'UNKNOWN_STUDENT' from imp_w w
    where w.sk is not null and not exists (select 1 from imp_s s where s.sk = w.sk) and not exists (select 1 from imp_live l where l.kind = 'student' and l.key = w.sk);
  insert into imp_err select 'weekly_lessons', w.line, 'tutor_email', 'UNKNOWN_TUTOR' from imp_w w
    where w.email is not null and not exists (select 1 from imp_t t where t.email = w.email) and not exists (select 1 from imp_tut x where x.em = w.email and x.role = 'tutor');
  insert into imp_err select 'weekly_lessons', w.line, 'tutor_email', 'TUTOR_NOT_AVAILABLE' from imp_w w
    where w.email is not null and exists (select 1 from imp_tut x where x.em = w.email and x.role = 'tutor' and x.status = 'disabled');
  insert into imp_err select 'weekly_lessons', line, 'start', 'DUPLICATE_KEY' from
    (select line, row_number() over (partition by sk, email, day, smin order by line) n from imp_w where sk is not null and email is not null and day is not null and smin is not null) q where n > 1;
  -- a student cannot have two overlapping lessons: inside the file, and against weekly lessons already in the centre
  insert into imp_err select 'weekly_lessons', b.line, 'start', 'SLOT_CLASH' from imp_w a join imp_w b
    on a.sk = b.sk and a.day = b.day and a.line < b.line and a.smin < b.emin and b.smin < a.emin and not (a.email = b.email and a.smin = b.smin)
    where a.smin is not null and b.smin is not null and a.emin > a.smin and b.emin > b.smin;
  insert into imp_err select 'weekly_lessons', w.line, 'start', 'SLOT_CLASH' from imp_w w
    join imp_live l on l.kind = 'student' and l.key = w.sk
    join recurring_slots x on x.student_id = l.row_id and x.active and x.weekday = w.day
    where w.smin is not null and w.emin > w.smin and x.start_time < (w.emin || ' minutes')::interval + time '00:00' and (w.smin || ' minutes')::interval + time '00:00' < x.end_time
      and not exists (select 1 from import_items it where it.kind = 'slot' and it.row_id = x.id and it.key = w.sk || '|' || w.email || '|' || w.day || '|' || lpad((w.smin / 60)::text, 2, '0') || ':' || lpad((w.smin % 60)::text, 2, '0'));

  select count(*) into v_n from (select distinct file, line, col, code from imp_err) e;
  select coalesce(jsonb_agg(jsonb_build_object('file', file, 'line', line, 'column', col, 'code', code) order by file, line, code), '[]') into v_errs
    from (select distinct file, line, col, code from imp_err order by file, line, code limit 300) e;
  if v_n > 0 then
    return jsonb_build_object('ok', false, 'errors', v_errs, 'error_count', v_n);
  end if;

  -- =========================================================== what would be created (the same lists the commit uses)
  create temp table imp_nf on commit drop as
    select distinct on (f.fk) f.fk, f.family_name, gen_random_uuid() hid from imp_f f
    where not exists (select 1 from imp_live l where l.kind = 'family' and l.key = f.fk) order by f.fk, f.line;
  create temp table imp_ng on commit drop as
    select f.line, f.fk, f.guardian_name, f.relation, f.phone, f.email, nf.hid, gen_random_uuid() gid,
           row_number() over (partition by f.fk order by (not coalesce(f.main, false)), f.line) rn
    from imp_f f join imp_nf nf on nf.fk = f.fk;
  create temp table imp_ns on commit drop as
    select s.*, gen_random_uuid() sid, coalesce(nf.hid, (select l.row_id from imp_live l where l.kind = 'family' and l.key = s.fk)) hid
    from imp_s s left join imp_nf nf on nf.fk = s.fk
    where not exists (select 1 from imp_live l where l.kind = 'student' and l.key = s.sk);
  create temp table imp_nt on commit drop as
    select t.*, gen_random_uuid() mid from imp_t t where not exists (select 1 from imp_tut x where x.em = t.email);
  create temp table imp_wres on commit drop as
    select w.line, w.sk, w.email, w.day, w.smin, w.emin, w.subject, w.level, w.rate_cents,
           w.sk || '|' || w.email || '|' || w.day || '|' || lpad((w.smin / 60)::text, 2, '0') || ':' || lpad((w.smin % 60)::text, 2, '0') wkey,
           coalesce(ns.sid, (select l.row_id from imp_live l where l.kind = 'student' and l.key = w.sk)) sid,
           coalesce(ns.level, (select s2.level from students s2 where s2.id = (select l.row_id from imp_live l where l.kind = 'student' and l.key = w.sk))) slevel,
           coalesce(nt.mid, (select x.id from imp_tut x where x.em = w.email and x.role = 'tutor' limit 1)) tid
    from imp_w w left join imp_ns ns on ns.sk = w.sk left join imp_nt nt on nt.email = w.email;
  create temp table imp_nw on commit drop as
    select r.*, gen_random_uuid() slid from imp_wres r where not exists (select 1 from imp_live l where l.kind = 'slot' and l.key = r.wkey);

  -- rows that exist already but whose content differs: skipped, and the owner is told (the import never overwrites)
  select coalesce(jsonb_agg(jsonb_build_object('file', file, 'line', line, 'code', 'DIFFERS') order by file, line), '[]') into v_warn from (
    select 'students' file, s.line from imp_s s join imp_live l on l.kind = 'student' and l.key = s.sk join students x on x.id = l.row_id
      where x.name is distinct from s.student_name or x.level is distinct from s.level or x.location is distinct from s.location
         or x.online_link is distinct from s.online_link or x.start_date is distinct from import_try_date(s.start_date) or x.notes is distinct from s.notes
    union all
    select 'families', f.line from imp_f f join imp_live l on l.kind = 'family' and l.key = f.fk join households h on h.id = l.row_id
      where h.name is distinct from f.family_name
    union all
    select 'weekly_lessons', w.line from imp_wres w join imp_live l on l.kind = 'slot' and l.key = w.wkey join recurring_slots x on x.id = l.row_id
      where x.end_time is distinct from ((w.emin || ' minutes')::interval + time '00:00') or x.rate is distinct from (w.rate_cents / 100.0)::numeric(8,2)
         or x.subject is distinct from w.subject or x.level is distinct from coalesce(w.level, w.slevel)
    limit 200) d;

  v_created := jsonb_build_object('families', (select count(*) from imp_nf), 'guardians', (select count(*) from imp_ng), 'students', (select count(*) from imp_ns),
                                  'tutors', (select count(*) from imp_nt), 'weekly_lessons', (select count(*) from imp_nw));
  v_skipped := jsonb_build_object('families', (select count(distinct fk) from imp_f) - (select count(*) from imp_nf),
                                  'guardians', (select count(*) from imp_f) - (select count(*) from imp_ng),
                                  'students', (select count(*) from imp_s) - (select count(*) from imp_ns),
                                  'tutors', (select count(*) from imp_t) - (select count(*) from imp_nt),
                                  'weekly_lessons', (select count(*) from imp_w) - (select count(*) from imp_nw));

  if not p_commit then
    return jsonb_build_object('ok', true, 'dry_run', true, 'errors', '[]'::jsonb, 'error_count', 0, 'warnings', v_warn, 'created', v_created, 'skipped', v_skipped);
  end if;

  -- =========================================================== commit: one transaction (a failure anywhere undoes the lot)
  if (select count(*) from imp_ng) + (select count(*) from imp_ns) + (select count(*) from imp_nt) + (select count(*) from imp_nw) = 0 then
    return jsonb_build_object('ok', true, 'dry_run', false, 'errors', '[]'::jsonb, 'error_count', 0, 'warnings', v_warn, 'created', v_created, 'skipped', v_skipped, 'batch_id', null);
  end if;
  perform set_config('td.skip_audit', '1', true);
  -- forget keys whose rows have since been removed by hand (so the code can be imported again)
  delete from import_items i where i.org_id = p_org and not import_row_exists(i.tbl, i.row_id);
  v_hashes := case when jsonb_typeof(p_hashes) = 'object' and length(p_hashes::text) <= 2000 then p_hashes else '{}'::jsonb end;
  insert into import_batches(id, org_id, created_by, stage, counts, file_hashes, undo_until)
  values (v_batch, p_org, me, 'A', jsonb_build_object('created', v_created, 'skipped', v_skipped), v_hashes, v_until);

  insert into households(id, org_id, name, phone_key)
    select nf.hid, p_org, nf.family_name, (select org_phone_key(g.phone) from imp_ng g where g.hid = nf.hid and g.rn = 1) from imp_nf nf;
  -- created_at is staggered by a millisecond so "the first guardian of a family" (the main contact) stays the first, in any later query
  insert into guardians(id, org_id, household_id, name, relation, phone, email, created_at)
    select g.gid, p_org, g.hid, g.guardian_name, g.relation, g.phone, g.email, now() + g.rn * interval '1 millisecond' from imp_ng g order by g.fk, g.rn;

  insert into students(id, tutor_id, org_id, household_id, name, level, contact, recipient_name, notes, location, online_link, start_date)
    select s.sid, me, p_org, s.hid, s.student_name, s.level, coalesce(ng.phone, eg.phone), coalesce(ng.guardian_name, eg.name),
           s.notes, s.location, s.online_link, import_try_date(s.start_date)
    from imp_ns s
    left join lateral (select g.phone, g.guardian_name from imp_ng g where g.hid = s.hid and g.rn = 1) ng on true
    left join lateral (select x.phone, x.name from guardians x where x.household_id = s.hid order by x.created_at, x.id limit 1) eg on true;

  -- tutors go in through the same function as the Users screen (owner check, invited status, no email)
  for tr in select * from imp_nt order by line loop
    m := org_invite(p_org, tr.email, tr.tutor_name, 'tutor', '{}', tr.employment);
    update imp_nt set mid = m where email = tr.email;
    update imp_nw set tid = m where tid = tr.mid;
  end loop;

  insert into recurring_slots(id, tutor_id, org_id, student_id, weekday, start_time, end_time, subject, rate, level, taught_by)
    select w.slid, me, p_org, w.sid, w.day, (w.smin || ' minutes')::interval + time '00:00', (w.emin || ' minutes')::interval + time '00:00',
           w.subject, (w.rate_cents / 100.0)::numeric(8,2), coalesce(w.level, w.slevel), w.tid
    from imp_nw w order by w.line;

  insert into import_items(org_id, batch_id, kind, key, tbl, row_id, fp)
    select p_org, v_batch, 'family', nf.fk, 'households', h.id, import_fp(to_jsonb(h)) from imp_nf nf join households h on h.id = nf.hid
    union all select p_org, v_batch, 'guardian', null, 'guardians', g.id, import_fp(to_jsonb(g)) from imp_ng x join guardians g on g.id = x.gid
    union all select p_org, v_batch, 'student', ns.sk, 'students', s.id, import_fp(to_jsonb(s)) from imp_ns ns join students s on s.id = ns.sid
    union all select p_org, v_batch, 'tutor', nt.email, 'memberships', mm.id, import_fp(to_jsonb(mm)) from imp_nt nt join memberships mm on mm.id = nt.mid
    union all select p_org, v_batch, 'slot', w.wkey, 'recurring_slots', sl.id, import_fp(to_jsonb(sl)) from imp_nw w join recurring_slots sl on sl.id = w.slid;

  insert into audit_log(org_id, actor, action, table_name, row_id, after)
  values (p_org, me, 'import_commit', 'import_batches', v_batch::text, jsonb_build_object('stage', 'A', 'created', v_created, 'skipped', v_skipped, 'files', v_hashes));
  perform set_config('td.skip_audit', '', true);

  return jsonb_build_object('ok', true, 'dry_run', false, 'errors', '[]'::jsonb, 'error_count', 0, 'warnings', v_warn, 'created', v_created, 'skipped', v_skipped,
                            'batch_id', v_batch, 'undo_until', v_until);
end $$;

-- ---------------------------------------------------------------- the public entry points
create or replace function public.import_dry_run(p_org uuid, p_payload jsonb) returns jsonb
language sql security definer set search_path = public as $$ select import_run_a(p_org, p_payload, false, null) $$;
create or replace function public.import_commit(p_org uuid, p_payload jsonb, p_hashes jsonb default '{}') returns jsonb
language sql security definer set search_path = public as $$ select import_run_a(p_org, p_payload, true, p_hashes) $$;

-- the owner's codes already in the centre (families, students, tutors), for the page's own checks
create or replace function public.import_existing(p_org uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if auth.uid() is null or not org_can(p_org, 'owner') or not exists (select 1 from organisations o where o.id = p_org and o.kind = 'centre') then
    raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  return jsonb_build_object(
    'families', coalesce((select jsonb_agg(i.key order by i.key) from import_items i where i.org_id = p_org and i.kind = 'family' and import_row_exists(i.tbl, i.row_id)), '[]'),
    'students', coalesce((select jsonb_agg(i.key order by i.key) from import_items i where i.org_id = p_org and i.kind = 'student' and import_row_exists(i.tbl, i.row_id)), '[]'),
    'tutors', coalesce((select jsonb_agg(lower(coalesce(m.invited_email, u.email)) order by m.created_at) from memberships m left join auth.users u on u.id = m.user_id
                         where m.org_id = p_org and m.role = 'tutor'), '[]'));
end $$;

create or replace function public.import_history(p_org uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if auth.uid() is null or not org_can(p_org, 'owner') or not exists (select 1 from organisations o where o.id = p_org and o.kind = 'centre') then
    raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('id', b.id, 'created_at', b.created_at, 'stage', b.stage, 'status', b.status, 'counts', b.counts, 'file_hashes', b.file_hashes,
           'undo_until', b.undo_until, 'can_undo', (b.status <> 'undone' and now() <= b.undo_until), 'undone_at', b.undone_at, 'undo_report', b.undo_report) order by b.created_at desc)
     from import_batches b where b.org_id = p_org), '[]');
end $$;

-- ---------------------------------------------------------------- undo
-- Removes what the batch created, EXCEPT anything someone has since edited, marked or invoiced. Everything kept is reported with a reason:
--   EDITED  a person changed the row after the import (a name, a rate, a tutor accepted the invitation…)
--   ACTIVITY  lessons of it were marked, charged, paid, noted or invoiced, or it has exams or invoices
--   IN_USE  something added later (a lesson, a student, a weekly lesson) still depends on it
create or replace function public.import_undo_run(p_batch uuid, p_do boolean) returns jsonb
language plpgsql security definer set search_path = public as $$
declare b import_batches; me uuid := auth.uid(); v_del jsonb; v_kept jsonb; v_gone int; v_left int; v_status text;
begin
  select * into b from import_batches where id = p_batch;
  if me is null or not found or not org_can(b.org_id, 'owner') then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  perform pg_advisory_xact_lock(hashtextextended('import:' || b.org_id::text, 0));
  if b.status = 'undone' then return jsonb_build_object('ok', false, 'code', 'ALREADY_UNDONE'); end if;
  if now() > b.undo_until then return jsonb_build_object('ok', false, 'code', 'UNDO_EXPIRED', 'undo_until', b.undo_until); end if;

  if to_regclass('pg_temp.imp_u') is not null then drop table pg_temp.imp_u; end if;
  -- one row per record of the batch that still exists, with its verdict
  create temp table imp_u on commit drop as
    select i.tbl, i.kind, i.key, i.row_id, i.fp, false keep, null::text reason,
           case i.tbl when 'households' then (select import_fp(to_jsonb(h)) from households h where h.id = i.row_id)
                      when 'guardians' then (select import_fp(to_jsonb(g)) from guardians g where g.id = i.row_id)
                      when 'students' then (select import_fp(to_jsonb(s)) from students s where s.id = i.row_id)
                      when 'memberships' then (select import_fp(to_jsonb(m)) from memberships m where m.id = i.row_id)
                      when 'recurring_slots' then (select import_fp(to_jsonb(x)) from recurring_slots x where x.id = i.row_id) end now_fp
    from import_items i where i.batch_id = p_batch and import_row_exists(i.tbl, i.row_id);
  create index on imp_u(tbl, row_id);
  select count(*) into v_gone from import_items i where i.batch_id = p_batch and not import_row_exists(i.tbl, i.row_id);

  -- weekly lessons: kept if changed, or any lesson of it has been worked on
  update imp_u u set keep = true, reason = 'EDITED' where u.tbl = 'recurring_slots' and u.now_fp is distinct from u.fp;
  update imp_u u set keep = true, reason = 'ACTIVITY' where u.tbl = 'recurring_slots' and not u.keep
    and exists (select 1 from lessons l where l.slot_id = u.row_id and import_lesson_touched(l));
  -- students: kept if changed, if they have worked-on lessons / exams / invoices, or a weekly lesson that is staying
  update imp_u u set keep = true, reason = 'EDITED' where u.tbl = 'students' and u.now_fp is distinct from u.fp;
  update imp_u u set keep = true, reason = 'ACTIVITY' where u.tbl = 'students' and not u.keep and (
      exists (select 1 from lessons l where l.student_id = u.row_id and import_lesson_touched(l))
      or exists (select 1 from exams e where e.student_id = u.row_id) or exists (select 1 from invoices v where v.student_id = u.row_id));
  update imp_u u set keep = true, reason = 'IN_USE' where u.tbl = 'students' and not u.keep and (
      exists (select 1 from recurring_slots x where x.student_id = u.row_id and not exists (select 1 from imp_u y where y.tbl = 'recurring_slots' and y.row_id = x.id and not y.keep)));
  -- a kept student keeps the weekly lessons it has (they would otherwise be deleted with it)
  update imp_u u set keep = true, reason = 'IN_USE' where u.tbl = 'recurring_slots' and not u.keep
    and exists (select 1 from imp_u s where s.tbl = 'students' and s.keep and s.row_id = (select x.student_id from recurring_slots x where x.id = u.row_id));
  -- families: kept if changed, if any guardian was changed or added by a person, or if a student stays in it
  update imp_u u set keep = true, reason = 'EDITED' where u.tbl = 'households' and u.now_fp is distinct from u.fp;
  update imp_u u set keep = true, reason = 'EDITED' where u.tbl = 'households' and not u.keep and exists (
      select 1 from guardians g where g.household_id = u.row_id and not exists (select 1 from imp_u y where y.tbl = 'guardians' and y.row_id = g.id and y.now_fp is not distinct from y.fp));
  update imp_u u set keep = true, reason = 'IN_USE' where u.tbl = 'households' and not u.keep and exists (
      select 1 from students s where s.household_id = u.row_id and not exists (select 1 from imp_u y where y.tbl = 'students' and y.row_id = s.id and not y.keep));
  update imp_u u set keep = true, reason = 'IN_USE' where u.tbl = 'guardians' and exists (
      select 1 from imp_u h where h.tbl = 'households' and h.keep and h.row_id = (select g.household_id from guardians g where g.id = u.row_id));
  -- tutors: kept if the person accepted or was edited, or a weekly lesson / lesson of someone still there is theirs
  update imp_u u set keep = true, reason = case when (select m.user_id from memberships m where m.id = u.row_id) is not null then 'ACCEPTED' else 'EDITED' end
    where u.tbl = 'memberships' and u.now_fp is distinct from u.fp;
  update imp_u u set keep = true, reason = 'IN_USE' where u.tbl = 'memberships' and not u.keep and (
      exists (select 1 from recurring_slots x where x.taught_by = u.row_id and not exists (select 1 from imp_u y where y.tbl = 'recurring_slots' and y.row_id = x.id and not y.keep))
      or exists (select 1 from lessons l where l.taught_by = u.row_id and not exists (select 1 from imp_u y where y.tbl = 'students' and y.row_id = l.student_id and not y.keep)));

  select coalesce(jsonb_object_agg(tbl, n), '{}') into v_del from (select tbl, count(*) n from imp_u where not keep group by tbl) q;
  select coalesce(jsonb_agg(jsonb_build_object('type', kind, 'code', key, 'reason', reason) order by kind, key) filter (where kind <> 'guardian'), '[]') into v_kept from (select * from imp_u where keep limit 500) q;
  select count(*) into v_left from imp_u where keep;

  if not p_do then
    return jsonb_build_object('ok', true, 'preview', true, 'would_delete', v_del, 'kept', v_kept, 'kept_count', v_left, 'already_gone', v_gone);
  end if;

  perform set_config('td.skip_audit', '1', true);
  -- lessons first (untouched ones only: a worked-on lesson always keeps its weekly lesson and its student), then the rest, children before parents
  delete from lessons l where l.org_id = b.org_id and (
        l.slot_id in (select row_id from imp_u where tbl = 'recurring_slots' and not keep)
     or l.student_id in (select row_id from imp_u where tbl = 'students' and not keep));
  delete from recurring_slots x where x.id in (select row_id from imp_u where tbl = 'recurring_slots' and not keep);
  delete from students s where s.id in (select row_id from imp_u where tbl = 'students' and not keep);
  delete from guardians g where g.id in (select row_id from imp_u where tbl = 'guardians' and not keep);
  delete from households h where h.id in (select row_id from imp_u where tbl = 'households' and not keep);
  delete from memberships m where m.id in (select row_id from imp_u where tbl = 'memberships' and not keep) and m.org_id = b.org_id;
  delete from import_items i where i.batch_id = p_batch and (not import_row_exists(i.tbl, i.row_id));
  update import_items i set kept_reason = u.reason from imp_u u where i.batch_id = p_batch and i.tbl = u.tbl and i.row_id = u.row_id and u.keep;

  v_status := case when v_left = 0 then 'undone' else 'partly_undone' end;
  update import_batches set status = v_status, undone_at = case when v_left = 0 then now() else undone_at end,
         undo_report = jsonb_build_object('deleted', v_del, 'kept', v_kept, 'kept_count', v_left, 'at', now())
   where id = p_batch;
  insert into audit_log(org_id, actor, action, table_name, row_id, after)
  values (b.org_id, me, 'import_undo', 'import_batches', p_batch::text, jsonb_build_object('deleted', v_del, 'kept_count', v_left));
  perform set_config('td.skip_audit', '', true);
  return jsonb_build_object('ok', true, 'preview', false, 'deleted', v_del, 'kept', v_kept, 'kept_count', v_left, 'already_gone', v_gone, 'status', v_status);
end $$;

create or replace function public.import_undo_preview(p_batch uuid) returns jsonb
language sql security definer set search_path = public as $$ select import_undo_run(p_batch, false) $$;
create or replace function public.import_undo(p_batch uuid) returns jsonb
language sql security definer set search_path = public as $$ select import_undo_run(p_batch, true) $$;

-- ---------------------------------------------------------------- who may call what
do $$
declare f text;
begin
  foreach f in array array['import_dry_run(uuid,jsonb)','import_commit(uuid,jsonb,jsonb)','import_existing(uuid)','import_history(uuid)',
                           'import_undo_preview(uuid)','import_undo(uuid)'] loop
    execute format('revoke all on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
  foreach f in array array['import_run_a(uuid,jsonb,boolean,jsonb)','import_undo_run(uuid,boolean)','import_fp(jsonb)','import_try_date(text)','import_minutes(text)',
                           'import_row_exists(text,uuid)','import_lesson_touched(lessons)'] loop
    execute format('revoke all on function public.%s from public, anon, authenticated', f);
  end loop;
end $$;

-- #####################################################################################################
-- ### PART 3 of 7 — tutor pay: rates, monthly pay list, adjustments, payments (owner / staff only)
-- ### source branch: claude/t4-s7-tutor-pay   file: db/migration_centre_tutor_pay.sql   undo: db/migration_centre_tutor_pay_down.sql
-- ### (if an error appears, search this file for the nearest "### PART" line above the error line: that is the part that failed)
-- #####################################################################################################
-- =====================================================================================================
-- T4 step S7 — centre tutor pay: effective-dated rates, the monthly pay list, "held until the parent pays", adjustments   undo: migration_centre_tutor_pay_down.sql
-- =====================================================================================================
-- Run order everywhere: org_foundation → billing → attendance → tutor_access → org_delete → function_lockdown → org_separation →
--   staff_home → staff_students → staff_attendance → staff_charges → staff_trials → staff_timetable → money_settings →
--   centre_money → centre_invoice_run → centre_payments → centre_deposits → centre_refunds → centre_late_fees → centre_credit_undo → centre_tutor_pay.
-- Needs money_settings (S0: the tutor_pay options), centre_money (S1), centre_invoice_run (S2: invoice lines), centre_payments (S3: allocations),
-- tutor_access (lessons.taught_by, session_id). Run on the DEV project first. LIVE only when the owner says ship: this migration adds three tables and
-- functions; it reads and changes no existing row. Safe to run twice.
--
-- WHO SEES WHAT (owner's rule): rates, pay and the pay list are for the centre OWNER and STAFF who have the permission `run_tutor_pay`. A TUTOR
--   NEVER sees a rate, a fee or any pay, not even their own: tutors have no table access and there is NO tutor-facing pay function (the plan's
--   tutor_my_pay / tutor_my_rates are deliberately NOT built; the setting tutor_pay.tutor_visibility is marked "soon"). Parents, switched-off staff,
--   staff without the permission, solo owners, strangers and anonymous callers get NOT_FOUND / NOT_ALLOWED. The three tables can be READ by the
--   same people and have NO write policy: browsers write nothing here, only the functions below do.
--
-- THE TABLES (all append-only: a change is a NEW row, nothing is edited or deleted; only deleting the whole organisation removes them)
--   tutor_pay_rates        one row per rate change. Scope: the tutor's DEFAULT, or one STUDENT, or one LEVEL. In force for a lesson = the newest row with
--                          effective_from on or before the LESSON DATE (money rules follow what was in force when the lesson happened), looking first at
--                          the student's rows, then the level's, then the tutor's default. method 'inherit' on a student/level scope = "back to the next
--                          level down"; 'none' = deliberately unpaid. A lesson with no rate at all shows as "no rate" and is NOT paid until staff set one.
--   tutor_pay_adjustments  a bonus (+) or deduction (−) in cents with a REASON, dated; a mistake is corrected by another adjustment.
--   tutor_pay_payments     "the centre paid this tutor S$x for the pay period ending d" (manual list: method, date, reference). A mistake is a REVERSAL row.
--                          Once a period is recorded as paid for a tutor, nothing dated inside it can be added for that tutor (no new rate effective on
--                          or before it, no adjustment dated in it): past pay is never rewritten. A late correction goes into the next period.
--
-- THE RATE METHODS (tutor_pay.rate_model only PRE-FILLS the form; every tutor can differ)
--   per_lesson          a fixed amount for each lesson taught.
--   per_hour            a fixed amount per hour × the lesson's minutes ÷ 60, half up to the cent.
--   per_student_lesson  classes only (refused when the centre runs one-to-one only): a fixed amount for each student in the class, counted per
--                       tutor_pay.group_count (attended = students marked attended · enrolled = also students who were absent or cancelled late,
--                       if tutor_pay.cancelled_lessons would pay for that cancelled lesson).
--   monthly_fixed       a fixed amount for each pay period, whatever was taught (default scope only). Never held back by a parent's payment: it does
--                       not belong to any family's invoice. It counts for the whole period even if the rate starts part-way through it.
--   percent_of_fee      percent_bp of what the family was BILLED for that lesson: tutor_pay.percent_base = billed_after_discounts (the lesson's invoice
--                       line plus its share of the student's sibling discount, before GST) or list_price (the line before discounts). GST, late fees and
--                       deposits are never in the base. A cancelled lesson's billed amount is its compensation, so a free cancellation gives 0 and an
--                       uncharged trial gives 0. Half up to the cent.
-- CLASSES (lessons of one class share session_id): per_lesson and per_hour pay the tutor ONCE for the class, not once per student: the class amount
--   (the average of the students' rates, half up) is shared between the students taught, remainder on the first, so each share can wait for its own family.
--   A student who was absent or cancelled earns nothing extra when the class was taught. A class where nobody was taught follows the cancelled rule once.
-- CANCELLED LESSONS (tutor_pay.cancelled_lessons, for the fixed methods): pay_if_charged = the usual rate only when the family is charged
--   (compensation above 0) · pay_rate = the usual rate · pay_nothing = 0. A cancelled lesson whose charge has not been typed yet (compensation empty)
--   is "waiting for the charge" and is not counted until it is. percent_of_fee needs the charge in every case.
-- WHEN IT BECOMES PAYABLE (tutor_pay.payable_when, read as of the LESSON'S date)
--   taught       the day it was marked taught (the lesson date, or the day attendance was marked if later).
--   parent_paid  only when the invoice line it sits on is paid for. Money received on the invoice (payments by their received date, minus reversals,
--                plus credit notes by their issue date) fills the invoice's lines OLDEST LINE FIRST, in proportion to its total (so GST is handled).
--                tutor_pay.part_payments: after_full (default) = the lesson is released only when its line is fully covered · pro_rata = released
--                in proportion to what is paid. A lesson that has no invoice line yet but WILL have one ("not invoiced") is held; one that never will
--                (an uncharged trial, a free cancellation) has no family to wait for and is released at once.
--   A held lesson shows as HELD and rolls into whichever pay period the parent's payment arrives in.
-- THE PAY LIST (one month, one tutor per row; period end = tutor_pay.cycle.cutoff_day, 31 = month end)
--   due = carried over + released in this period + monthly fixed + adjustments in this period
--   carried over = everything released and adjusted before the period − everything recorded as paid for earlier periods, so a payment that came in
--   late, a reversed payment or a part payment is never lost: it appears as "carried over". Figures are worked "as of" a date from the dated events
--   (lesson dates, marks, payments by received date) so a past period's figures do not move when later events arrive; they show up in a later one.
--   A credit note issued after the parent paid is NOT clawed back by itself: staff enter a negative adjustment with a reason if they want one.
-- MODES (tutor_pay.mode): off = nothing here works · report = the lessons-taught report and the rates screen (no money list) · full = everything.
--   Adjustments also need tutor_pay.adjustments on. bank_file payout stays "soon": this is the manual list only.
--
-- AUDIT: every row is copied to the audit log by the S1 trigger (free text — reasons, references, notes — replaced by "[redacted]"); each function adds a
--   summary row with amounts and counts only (never names). Exporting the pay list is logged too.
-- =====================================================================================================

-- ---------------------------------------------------------------------------------------------------
-- 1. tables
-- ---------------------------------------------------------------------------------------------------
create table if not exists public.tutor_pay_rates (
  id            uuid primary key default gen_random_uuid(),
  org_id        uuid not null references public.organisations(id) on delete cascade,
  membership_id uuid,                                    -- the tutor; becomes null if the person is removed (the row stays: it is the centre's record)
  student_id    uuid,                                    -- set = an override for this student only
  level         text,                                    -- set = an override for this level only (never together with student_id)
  method        text not null check (method in ('per_lesson', 'per_hour', 'per_student_lesson', 'monthly_fixed', 'percent_of_fee', 'none', 'inherit')),
  amount_cents  bigint check (amount_cents between 0 and 100000000),
  percent_bp    int check (percent_bp between 0 and 10000),
  effective_from date not null,
  reason        text not null check (length(trim(reason)) between 1 and 300),
  created_by    uuid default auth.uid(),
  created_at    timestamptz not null default now(),
  unique (id, org_id),
  foreign key (membership_id, org_id) references public.memberships(id, org_id) on delete set null (membership_id),
  foreign key (student_id, org_id)    references public.students(id, org_id),
  check (student_id is null or level is null),
  check (level is null or length(trim(level)) between 1 and 60),
  check ((method in ('per_lesson', 'per_hour', 'per_student_lesson', 'monthly_fixed') and amount_cents is not null and percent_bp is null)
      or (method = 'percent_of_fee' and percent_bp is not null and amount_cents is null)
      or (method in ('none', 'inherit') and amount_cents is null and percent_bp is null)),
  check (method <> 'monthly_fixed' or (student_id is null and level is null)),
  check (method <> 'inherit' or student_id is not null or level is not null)
);
create index if not exists tutor_pay_rates_lookup on public.tutor_pay_rates(org_id, membership_id, effective_from desc);

create table if not exists public.tutor_pay_adjustments (
  id            uuid primary key default gen_random_uuid(),
  org_id        uuid not null references public.organisations(id) on delete cascade,
  membership_id uuid,
  kind          text not null check (kind in ('bonus', 'deduction')),
  amount_cents  bigint not null check (amount_cents <> 0 and amount_cents between -100000000 and 100000000),
  effective_on  date not null,
  reason        text not null check (length(trim(reason)) between 1 and 300),
  created_by    uuid default auth.uid(),
  created_at    timestamptz not null default now(),
  unique (id, org_id),
  foreign key (membership_id, org_id) references public.memberships(id, org_id) on delete set null (membership_id),
  check ((kind = 'bonus') = (amount_cents > 0))
);
create index if not exists tutor_pay_adjustments_lookup on public.tutor_pay_adjustments(org_id, membership_id, effective_on);

create table if not exists public.tutor_pay_payments (
  id            uuid primary key default gen_random_uuid(),
  org_id        uuid not null references public.organisations(id) on delete cascade,
  kind          text not null default 'payment' check (kind in ('payment', 'reversal')),
  reverses_payment_id uuid,
  membership_id uuid,
  tutor_name    text not null,                           -- a copy of the name at the time (the centre's record survives the person leaving)
  period_from   date not null,
  period_to     date not null,
  amount_cents  bigint not null check (amount_cents > 0 and amount_cents <= 100000000),
  paid_on       date not null,
  method        text not null check (method in ('paynow', 'bank', 'cash', 'cheque', 'other')),
  reference     text,
  note          text,
  recorded_by   uuid default auth.uid(),
  created_at    timestamptz not null default now(),
  unique (id, org_id),
  foreign key (membership_id, org_id) references public.memberships(id, org_id) on delete set null (membership_id),
  foreign key (reverses_payment_id, org_id) references public.tutor_pay_payments(id, org_id),
  check (period_to >= period_from),
  check ((kind = 'reversal') = (reverses_payment_id is not null))
);
create unique index if not exists tutor_pay_payments_one_reversal on public.tutor_pay_payments(reverses_payment_id) where reverses_payment_id is not null;
create index if not exists tutor_pay_payments_lookup on public.tutor_pay_payments(org_id, membership_id, period_to);

-- ---------------------------------------------------------------------------------------------------
-- 2. guards: centres only, append-only, past pay is never rewritten
-- ---------------------------------------------------------------------------------------------------
-- append-only (the only change allowed is the database setting a removed person's id to null; deleting the whole organisation is allowed)
create or replace function public.tutor_pay_appendonly() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'DELETE' then
    if centre_money_deleting(old.org_id) then return old; end if;
    raise exception '% is append-only (add a correcting row instead)', tg_table_name using errcode = '42501';
  end if;
  if tg_op = 'UPDATE' and old.membership_id is not null and new.membership_id is null
     and (to_jsonb(new) - 'membership_id') = (to_jsonb(old) - 'membership_id') then
    return new;
  end if;
  raise exception '% is append-only (add a correcting row instead)', tg_table_name using errcode = '42501';
end $$;

-- The last day of the newest period recorded as paid (and not reversed) for a tutor; null if none.
create or replace function public.tutor_pay_frozen_to(p_org uuid, p_membership uuid) returns date
language sql stable security definer set search_path = public as $$
  select max(p.period_to) from tutor_pay_payments p
   where p.org_id = p_org and p.membership_id = p_membership and p.kind = 'payment'
     and not exists (select 1 from tutor_pay_payments r where r.reverses_payment_id = p.id)
$$;

create or replace function public.tutor_pay_freeze_guard() returns trigger
language plpgsql security definer set search_path = public as $$
declare f date; d date; m uuid;
begin
  m := new.membership_id; if m is null then return new; end if;
  d := coalesce((to_jsonb(new) ->> 'effective_from')::date, (to_jsonb(new) ->> 'effective_on')::date);
  f := tutor_pay_frozen_to(new.org_id, m);
  if f is not null and d <= f then
    raise exception 'PERIOD_PAID: pay for the period ending % is already recorded for this tutor, so nothing can be dated on or before then; use a later date', f using errcode = 'P0001';
  end if;
  return new;
end $$;

-- a payment: a reversal must repeat what it cancels; the tutor must be someone of this centre
create or replace function public.tutor_pay_payment_guard() returns trigger
language plpgsql security definer set search_path = public as $$
declare p record;
begin
  if new.kind = 'reversal' then
    select * into p from tutor_pay_payments where id = new.reverses_payment_id and org_id = new.org_id;
    if p.id is null or p.kind <> 'payment' then raise exception 'A reversal must cancel a payment of this centre' using errcode = '42501'; end if;
    if new.amount_cents <> p.amount_cents or new.membership_id is distinct from p.membership_id or new.period_to <> p.period_to or new.period_from <> p.period_from then
      raise exception 'A reversal must repeat the payment it cancels' using errcode = '42501';
    end if;
  end if;
  return new;
end $$;

do $$
declare t text;
begin
  foreach t in array array['tutor_pay_rates', 'tutor_pay_adjustments', 'tutor_pay_payments'] loop
    execute format('drop trigger if exists centre_money_org_guard on public.%I', t);
    execute format('create trigger centre_money_org_guard before insert on public.%I for each row execute function public.centre_money_org_guard()', t);
    execute format('drop trigger if exists audit_row on public.%I', t);
    execute format('create trigger audit_row after insert or update or delete on public.%I for each row execute function public.centre_money_audit()', t);
    execute format('drop trigger if exists tutor_pay_appendonly on public.%I', t);
    execute format('create trigger tutor_pay_appendonly before update or delete on public.%I for each row execute function public.tutor_pay_appendonly()', t);
  end loop;
end $$;
drop trigger if exists tutor_pay_freeze_guard on public.tutor_pay_rates;
create trigger tutor_pay_freeze_guard before insert on public.tutor_pay_rates for each row execute function public.tutor_pay_freeze_guard();
drop trigger if exists tutor_pay_freeze_guard on public.tutor_pay_adjustments;
create trigger tutor_pay_freeze_guard before insert on public.tutor_pay_adjustments for each row execute function public.tutor_pay_freeze_guard();
drop trigger if exists tutor_pay_payment_guard on public.tutor_pay_payments;
create trigger tutor_pay_payment_guard before insert on public.tutor_pay_payments for each row execute function public.tutor_pay_payment_guard();

-- row-level security: readable by the owner and staff with run_tutor_pay, in centres only; NO write policy
alter table public.tutor_pay_rates enable row level security;
alter table public.tutor_pay_adjustments enable row level security;
alter table public.tutor_pay_payments enable row level security;
drop policy if exists pay_read on public.tutor_pay_rates;
create policy pay_read on public.tutor_pay_rates for select using (org_can(org_id, 'run_tutor_pay') and not org_is_solo(org_id));
drop policy if exists pay_read on public.tutor_pay_adjustments;
create policy pay_read on public.tutor_pay_adjustments for select using (org_can(org_id, 'run_tutor_pay') and not org_is_solo(org_id));
drop policy if exists pay_read on public.tutor_pay_payments;
create policy pay_read on public.tutor_pay_payments for select using (org_can(org_id, 'run_tutor_pay') and not org_is_solo(org_id));
revoke all on public.tutor_pay_rates, public.tutor_pay_adjustments, public.tutor_pay_payments from anon, authenticated;
grant select on public.tutor_pay_rates, public.tutor_pay_adjustments, public.tutor_pay_payments to authenticated;

-- ---------------------------------------------------------------------------------------------------
-- 3. internal helpers
-- ---------------------------------------------------------------------------------------------------
-- the gate every screen function starts with. p_need: 'rates' / 'report' (mode report or full) · 'full' (mode full). Returns the centre's own today.
create or replace function public.centre_tutor_pay_gate(p_org uuid, p_need text) returns date
language plpgsql stable security definer set search_path = public as $$
declare tz text; mode text; today date;
begin
  if auth.uid() is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  select o.timezone into tz from organisations o where o.id = p_org and o.kind = 'centre';
  if tz is null or not exists (select 1 from memberships m where m.org_id = p_org and m.user_id = auth.uid() and m.status = 'active' and m.role in ('owner', 'staff')) then
    raise exception 'NOT_FOUND' using errcode = 'P0001';
  end if;
  if not org_can(p_org, 'run_tutor_pay') then
    raise exception 'NOT_ALLOWED: your account can''t see or change tutor pay at this centre' using errcode = '42501';
  end if;
  today := (now() at time zone tz)::date;
  mode := coalesce(org_settings_on(p_org, today) #>> '{tutor_pay,mode}', 'off');
  if mode = 'off' then raise exception 'PAY_OFF: tutor pay is switched off in Centre settings' using errcode = 'P0001'; end if;
  if p_need = 'full' and mode <> 'full' then
    raise exception 'PAY_REPORT_ONLY: this centre uses the lessons-taught report only; switch Tutor pay to "Full pay calculation" in Centre settings to work out pay' using errcode = 'P0001';
  end if;
  return today;
end $$;

-- the pay period that ends in a calendar month: the day after the previous period's end up to the cut-off day (31 = the month's last day)
create or replace function public.centre_tutor_period(p_month date, p_cutoff int) returns table(p_from date, p_to date)
language plpgsql immutable set search_path = public as $$
declare m0 date := date_trunc('month', p_month)::date; c int := case when p_cutoff between 1 and 31 then p_cutoff else 31 end; pm date; dm int; dp int;
begin
  dm := extract(day from (m0 + interval '1 month' - interval '1 day'))::int;
  pm := (m0 - interval '1 month')::date;
  dp := extract(day from (m0 - interval '1 day'))::int;
  p_to := m0 + (least(c, dm) - 1);
  p_from := pm + least(c, dp);
  return next;
end $$;

-- the rate in force for one lesson: the student's newest row, else the level's, else the tutor's default; 'inherit' means "look at the next level down".
-- No row at all = no rows returned (the lesson has no rate).
create or replace function public.centre_tutor_rate_for(p_org uuid, p_membership uuid, p_student uuid, p_level text, p_day date)
returns table(method text, amount_cents bigint, percent_bp int, rate_id uuid, scope text)
language plpgsql stable security definer set search_path = public as $$
declare r tutor_pay_rates;
begin
  select * into r from tutor_pay_rates x where x.org_id = p_org and x.membership_id = p_membership and x.student_id = p_student and x.effective_from <= p_day
   order by x.effective_from desc, x.created_at desc, x.id desc limit 1;
  if found and r.method <> 'inherit' then return query select r.method, r.amount_cents, r.percent_bp, r.id, 'student'::text; return; end if;
  if p_level is not null then
    select * into r from tutor_pay_rates x where x.org_id = p_org and x.membership_id = p_membership and x.student_id is null and lower(x.level) = lower(p_level)
       and x.effective_from <= p_day order by x.effective_from desc, x.created_at desc, x.id desc limit 1;
    if found and r.method <> 'inherit' then return query select r.method, r.amount_cents, r.percent_bp, r.id, 'level'::text; return; end if;
  end if;
  select * into r from tutor_pay_rates x where x.org_id = p_org and x.membership_id = p_membership and x.student_id is null and x.level is null and x.effective_from <= p_day
   order by x.effective_from desc, x.created_at desc, x.id desc limit 1;
  if found then return query select r.method, r.amount_cents, r.percent_bp, r.id, 'default'::text; end if;
end $$;

-- fixed monthly pay: one amount per pay period, from the month of the tutor's first rate to the period ending in p_to's month.
-- Returns (before, in_period): the sum for periods that ended before p_from, and the one that ends at p_to.
create or replace function public.centre_tutor_monthly(p_org uuid, p_membership uuid, p_from date, p_to date, p_cutoff int)
returns table(before_cents bigint, period_cents bigint)
language plpgsql stable security definer set search_path = public as $$
declare first_m date; m date; pe date; r record; b bigint := 0; i bigint := 0;
begin
  select date_trunc('month', min(effective_from))::date into first_m from tutor_pay_rates where org_id = p_org and membership_id = p_membership and method = 'monthly_fixed';
  if first_m is not null then
    m := first_m;
    while m <= date_trunc('month', p_to)::date loop
      select pp.p_to into pe from centre_tutor_period(m, p_cutoff) pp;
      select * into r from centre_tutor_rate_for(p_org, p_membership, null, null, pe);
      if r.method = 'monthly_fixed' then
        if pe < p_from then b := b + r.amount_cents; elsif pe = p_to then i := i + r.amount_cents; end if;
      end if;
      m := (m + interval '1 month')::date;
    end loop;
  end if;
  before_cents := b; period_cents := i; return next;
end $$;

-- THE CALCULATION. One row per lesson a tutor taught or was cancelled with, up to p_to, with what the tutor earns for it and what has been RELEASED
-- (made payable) as of the day before p_from and as of p_to. INTERNAL: only the screen functions below call it (they check who is asking).
create or replace function public.centre_tutor_pay_rows(p_org uuid, p_from date, p_to date, p_membership uuid default null)
returns table(lesson_id uuid, membership_id uuid, student_id uuid, lesson_date date, minutes int, lesson_status text, is_trial boolean, session_key uuid,
              method text, rate_scope text, earn_cents bigint, earn_on date, base_cents bigint, invoice_id uuid, state text, released_before bigint, released_to bigint)
language plpgsql stable security definer set search_path = public as $$
declare tz text; bef date := p_from - 1;
begin
  select o.timezone into tz from organisations o where o.id = p_org;
  return query
  with b as (
    select l.id as lid, l.taught_by as mid, l.student_id as sid, l.lesson_date as ld, l.start_time as st, l.status as stt, l.attendance as att,
           coalesce(l.trial, false) as trial, l.compensation_cents as comp, nullif(trim(l.level), '') as lvl, coalesce(l.session_id, l.id) as sk,
           greatest(l.lesson_date, coalesce((l.attendance_marked_at at time zone coalesce(tz, 'Asia/Singapore'))::date, l.lesson_date)) as eo,
           greatest((extract(epoch from (l.end_time - l.start_time)) / 60)::int, 0) as mins,
           lesson_price_cents(l.amount, l.rate, l.start_time, l.end_time) as price
      from lessons l
     where l.org_id = p_org and l.taught_by is not null and l.status in ('done', 'cancelled') and l.lesson_date <= p_to
       and (p_membership is null or l.taught_by = p_membership)
  ), sd as materialized (
    select x.d, org_settings_on(p_org, x.d) as s from (select distinct ld as d from b) x
  ), c as (
    select b.*,
           coalesce(sd.s #>> '{tutor_pay,payable_when}', 'parent_paid') as pw,
           coalesce(sd.s #>> '{tutor_pay,part_payments}', 'after_full') as pp,
           coalesce(sd.s #>> '{tutor_pay,cancelled_lessons}', 'pay_if_charged') as cr,
           coalesce(sd.s #>> '{tutor_pay,percent_base}', 'billed_after_discounts') as pb,
           coalesce(sd.s #>> '{tutor_pay,group_count}', 'attended') as gc,
           coalesce((sd.s #>> '{billing,trials,charged}')::boolean, false) as trials_charged
      from b join sd on sd.d = b.ld where b.eo <= p_to
  ), cand as (                                              -- every rate row that could apply to a lesson, keeping the NEWEST (by start date) of each kind: student, level, default
    select distinct on (x.clid, x.tier) x.*
      from (select c.lid as clid, case when r.student_id is not null then 1 when r.level is not null then 2 else 3 end as tier,
                   r.method as cm, r.amount_cents as ca, r.percent_bp as cp, r.effective_from as cf, r.created_at as cc, r.id as cid
              from c join tutor_pay_rates r on r.org_id = p_org and r.membership_id = c.mid and r.effective_from <= c.ld
               and (r.student_id = c.sid or (r.student_id is null and r.level is not null and lower(r.level) = lower(c.lvl)) or (r.student_id is null and r.level is null))) x
     order by x.clid, x.tier, x.cf desc, x.cc desc, x.cid desc
  ), pick as (                                              -- the first kind whose newest row is not "back to the usual rate"
    select distinct on (cand.clid) cand.clid, cand.tier, cand.cm, cand.ca, cand.cp from cand where cand.cm <> 'inherit' order by cand.clid, cand.tier
  ), u as (                                                 -- the rate in force on the lesson date, and the fixed amount it gives
    select c.*, p.cm as rm, p.ca as ra, p.cp as rp, case p.tier when 1 then 'student' when 2 then 'level' when 3 then 'default' end as rsc,
           case p.cm when 'per_lesson' then p.ca when 'per_hour' then centre_div_round(p.ca * c.mins, 60) when 'per_student_lesson' then p.ca else 0 end as unit
      from c left join pick p on p.clid = c.lid
  ), il as (                                                -- the issued lesson invoices these lessons sit on, with every line, in order
    select ln.id as line_id, ln.invoice_id as inv, ln.position as pos, ln.lesson_id as llid, ln.student_id as lsid, ln.fee_kind as fk, ln.line_cents as lc
      from centre_invoice_lines ln join centre_invoices ci on ci.id = ln.invoice_id and ci.org_id = ln.org_id
     where ln.org_id = p_org and ci.status = 'issued' and ci.kind = 'lesson'
       and ln.invoice_id in (select ln2.invoice_id from centre_invoice_lines ln2 where ln2.org_id = p_org and ln2.lesson_id in (select lid from c))
  ), il2 as (
    select il.*,
           (sum(lc) filter (where fk = 'sibling_discount') over (partition by inv, lsid))::bigint as dsum,
           (sum(lc) filter (where llid is not null) over (partition by inv, lsid))::bigint as lsum,
           (sum(lc) filter (where llid is not null) over (partition by inv, lsid order by pos, line_id))::bigint as lcum
      from il
  ), il3 as (                                               -- each lesson line's share of its student's sibling discount (telescoping, so the shares add up exactly)
    select il2.*, case when llid is not null and coalesce(lsum, 0) > 0 and dsum is not null
                       then centre_div_round(dsum * lcum, lsum) - centre_div_round(dsum * (lcum - lc), lsum) else 0 end as share
      from il2
  ), il4 as (
    select il3.*, case when fk = 'sibling_discount' and coalesce(lsum, 0) > 0 then 0 else lc + share end as net
      from il3
  ), il5 as (
    select il4.*, (sum(net) over (partition by inv order by pos, line_id))::bigint as cumnet, (sum(net) over (partition by inv))::bigint as subtotal
      from il4
  ), fund as (                                              -- money received on each invoice (payments by received date, plus credit notes by issue date) as of two days
    select ci.id as inv, ci.total_cents as tot,
           (coalesce((select sum(a.cents) from centre_payment_allocations a join centre_payments p on p.id = a.payment_id and p.org_id = a.org_id
                      where a.invoice_id = ci.id and p.received_on <= p_to), 0)
         + coalesce((select sum(n.total_cents) from centre_invoices n where n.credits_invoice_id = ci.id and n.status = 'issued' and n.issue_date <= p_to), 0))::bigint as f_to,
           (coalesce((select sum(a.cents) from centre_payment_allocations a join centre_payments p on p.id = a.payment_id and p.org_id = a.org_id
                      where a.invoice_id = ci.id and p.received_on <= bef), 0)
         + coalesce((select sum(n.total_cents) from centre_invoices n where n.credits_invoice_id = ci.id and n.status = 'issued' and n.issue_date <= bef), 0))::bigint as f_bef
      from centre_invoices ci where ci.id in (select inv from il)
  ), j as (
    select u.*, i5.inv as inv, i5.lc as lcents, i5.share as dshare, i5.cumnet, i5.subtotal, f.tot, f.f_to, f.f_bef,
           (i5.inv is null) as noline,
           -- will this lesson have an invoice line once it is invoiced?
           case when u.trial and not u.trials_charged then false
                when u.stt = 'done' then coalesce(u.price, 0) > 0
                else coalesce(u.comp, 0) > 0 end as expects_line,
           -- cancelled with the charge not typed yet (only matters when the rule needs the charge)
           (u.stt = 'cancelled' and u.comp is null and u.att in ('absent', 'cancelled_early', 'late_cancelled')) as charge_pending,
           (u.stt = 'cancelled' and (u.cr = 'pay_rate' or (u.cr = 'pay_if_charged' and coalesce(u.comp, 0) > 0))) as canc_paid
      from u left join il5 i5 on i5.llid = u.lid
           left join fund f on f.inv = i5.inv
  ), k as (
    select j.*,
           count(*) filter (where stt = 'done') over (partition by sk, mid) as n_done,
           (case when rm = 'percent_of_fee' then coalesce(case pb when 'list_price' then lcents else lcents + dshare end, 0) end) as pbase
      from j
  ), pm as (                                                -- members of a class's shared pot (per_lesson / per_hour only)
    select k.*, (rm in ('per_lesson', 'per_hour') and (stt = 'done' or (n_done = 0 and canc_paid and not (charge_pending and cr = 'pay_if_charged')))) as inpot
      from k
  ), pot as (
    select pm.*,
           count(*) filter (where inpot) over (partition by sk, mid) as n_pot,
           (sum(unit) filter (where inpot) over (partition by sk, mid))::bigint as s_pot,
           row_number() over (partition by sk, mid, inpot order by ld, st, lid) as rn_pot
      from pm
  ), e as (
    select pot.*,
      case
        when rm is null then null
        when rm in ('none', 'monthly_fixed', 'inherit') then 0
        when rm = 'percent_of_fee' then
          case when stt = 'cancelled' and charge_pending then null
               when noline and expects_line then null
               else centre_div_round(coalesce(pbase, 0) * rp, 10000) end
        when rm = 'per_student_lesson' then
          case when stt = 'done' then unit
               when stt = 'cancelled' and gc = 'enrolled' and canc_paid then unit
               when stt = 'cancelled' and gc = 'enrolled' and charge_pending and cr = 'pay_if_charged' then null
               else 0 end
        else   -- per_lesson / per_hour
          case when stt = 'cancelled' and n_done = 0 and charge_pending and cr = 'pay_if_charged' then null
               when not inpot then 0
               else (centre_div_round(s_pot, n_pot::bigint) / n_pot::bigint) + case when rn_pot = 1 then centre_div_round(s_pot, n_pot::bigint) - (centre_div_round(s_pot, n_pot::bigint) / n_pot::bigint) * n_pot::bigint else 0 end end
      end as earn
      from pot
  ), rel as (
    select e.*,
      -- released as of p_to
      case when earn is null or eo > p_to then 0
           when pw = 'taught' then earn
           when noline then case when expects_line then 0 else earn end
           when pp = 'pro_rata' then case when tot > 0 then centre_div_round(earn * least(f_to, tot), tot) else earn end
           else case when tot = 0 or subtotal = 0 or f_to * subtotal >= cumnet * tot then earn else 0 end end as r_to,
      -- released as of the day before the period
      case when earn is null or eo > bef then 0
           when pw = 'taught' then earn
           when noline then case when expects_line then 0 else earn end
           when pp = 'pro_rata' then case when tot > 0 then centre_div_round(earn * least(f_bef, tot), tot) else earn end
           else case when tot = 0 or subtotal = 0 or f_bef * subtotal >= cumnet * tot then earn else 0 end end as r_bef
      from e
  )
  select rel.lid, rel.mid, rel.sid, rel.ld, rel.mins, rel.stt, rel.trial, rel.sk, rel.rm, rel.rsc, rel.earn, rel.eo,
         case when rel.rm = 'percent_of_fee' then rel.pbase end, rel.inv,
         case when rel.rm is null then 'no_rate'
              when rel.rm in ('none', 'inherit') then 'unpaid'
              when rel.rm = 'monthly_fixed' then 'monthly'
              when rel.earn is null then case when rel.charge_pending then 'waiting_charge' else 'waiting_invoice' end
              when rel.earn = 0 then 'zero'
              when rel.r_to >= rel.earn then 'payable'
              when rel.r_to > 0 then 'part'
              else 'held' end,
         rel.r_bef::bigint, rel.r_to::bigint
    from rel;
end $$;

-- ---------------------------------------------------------------------------------------------------
-- 4. RATES: list and set
-- ---------------------------------------------------------------------------------------------------
-- Everything the rates screen needs: the centre's people who teach, each with their full rate history (newest first) and which rows are in force today.
create or replace function public.centre_tutor_rate_list(p_org uuid) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare today date := centre_tutor_pay_gate(p_org, 'rates'); s jsonb := org_settings_on(p_org, today); r jsonb;
begin
  select jsonb_build_object(
    'today', today, 'mode', coalesce(s #>> '{tutor_pay,mode}', 'off'), 'default_method', coalesce(s #>> '{tutor_pay,rate_model}', 'per_hour'),
    'class_type', coalesce(s #>> '{lessons,class_type}', 'both'),
    'tutors', coalesce((select jsonb_agg(jsonb_build_object(
        'membership_id', m.id, 'name', m.display_name, 'role', m.role, 'employment_type', m.employment_type, 'status', m.status,
        'frozen_to', tutor_pay_frozen_to(p_org, m.id),
        'rates', coalesce((select jsonb_agg(jsonb_build_object(
            'id', x.id, 'student_id', x.student_id, 'student_name', st.name, 'level', x.level, 'method', x.method, 'amount_cents', x.amount_cents,
            'percent_bp', x.percent_bp, 'effective_from', x.effective_from, 'reason', x.reason, 'created_at', x.created_at,
            'in_force', x.id = (select y.id from tutor_pay_rates y where y.org_id = p_org and y.membership_id = m.id
                                  and y.student_id is not distinct from x.student_id and lower(coalesce(y.level, '')) = lower(coalesce(x.level, ''))
                                  and y.effective_from <= today order by y.effective_from desc, y.created_at desc, y.id desc limit 1))
            order by x.student_id is not null, x.level is not null, x.effective_from desc, x.created_at desc)
          from tutor_pay_rates x left join students st on st.id = x.student_id and st.org_id = x.org_id
         where x.org_id = p_org and x.membership_id = m.id), '[]'::jsonb))
        order by (m.role = 'tutor') desc, m.display_name)
      from memberships m where m.org_id = p_org and m.status <> 'disabled' and m.role in ('tutor', 'staff', 'owner')
        and (m.role = 'tutor' or exists (select 1 from lessons l where l.org_id = p_org and l.taught_by = m.id)
             or exists (select 1 from tutor_pay_rates x where x.org_id = p_org and x.membership_id = m.id))), '[]'::jsonb),
    'students', coalesce((select jsonb_agg(jsonb_build_object('id', st.id, 'name', st.name) order by st.name) from students st where st.org_id = p_org
                           and (st.end_date is null or st.end_date >= today)), '[]'::jsonb),
    'levels', coalesce((select jsonb_agg(distinct lv order by lv) from (select nullif(trim(l.level), '') lv from lessons l where l.org_id = p_org
                          union select nullif(trim(x.level), '') from tutor_pay_rates x where x.org_id = p_org) q where lv is not null), '[]'::jsonb)
  ) into r;
  return r;
end $$;

-- Add a rate (a new row; nothing is edited). p_student / p_level: leave both null for the tutor's default.
create or replace function public.centre_tutor_rate_set(p_org uuid, p_membership uuid, p_student uuid, p_level text, p_method text,
  p_amount_cents bigint, p_percent_bp int, p_effective_from date, p_reason text) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare today date := centre_tutor_pay_gate(p_org, 'rates'); s jsonb := org_settings_on(p_org, today); m memberships; lv text := nullif(trim(coalesce(p_level, '')), '');
        why text := nullif(trim(coalesce(p_reason, '')), ''); nid uuid := gen_random_uuid();
begin
  select * into m from memberships where id = p_membership and org_id = p_org and status <> 'disabled' and role in ('tutor', 'staff', 'owner');
  if m.id is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  if p_method is null or p_method not in ('per_lesson', 'per_hour', 'per_student_lesson', 'monthly_fixed', 'percent_of_fee', 'none', 'inherit') then
    raise exception 'BAD_RATE: pick how this tutor is paid' using errcode = 'P0001'; end if;
  if p_student is not null and lv is not null then raise exception 'BAD_RATE: a rate is for one student or one level, not both' using errcode = 'P0001'; end if;
  if p_student is not null and not exists (select 1 from students st where st.id = p_student and st.org_id = p_org) then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  if lv is not null and length(lv) > 60 then raise exception 'BAD_RATE: the level name is too long' using errcode = 'P0001'; end if;
  if p_method = 'monthly_fixed' and (p_student is not null or lv is not null) then raise exception 'BAD_RATE: a fixed monthly amount is for the tutor, not one student or level' using errcode = 'P0001'; end if;
  if p_method = 'inherit' and p_student is null and lv is null then raise exception 'BAD_RATE: "back to the tutor''s usual rate" is only for a student or level' using errcode = 'P0001'; end if;
  if p_method = 'per_student_lesson' and coalesce(s #>> '{lessons,class_type}', 'both') = 'one_to_one' then
    raise exception 'BAD_RATE: "per student per lesson" is for centres that run group classes' using errcode = 'P0001'; end if;
  if p_method in ('per_lesson', 'per_hour', 'per_student_lesson', 'monthly_fixed') then
    if p_amount_cents is null or p_amount_cents < 0 or p_amount_cents > 100000000 or p_percent_bp is not null then raise exception 'BAD_RATE: enter the amount as dollars and cents (0 to 1,000,000)' using errcode = 'P0001'; end if;
  elsif p_method = 'percent_of_fee' then
    if p_percent_bp is null or p_percent_bp < 0 or p_percent_bp > 10000 or p_amount_cents is not null then raise exception 'BAD_RATE: the percentage must be between 0%% and 100%%' using errcode = 'P0001'; end if;
  elsif p_amount_cents is not null or p_percent_bp is not null then raise exception 'BAD_RATE: this choice has no amount' using errcode = 'P0001'; end if;
  if p_effective_from is null then raise exception 'BAD_RATE: choose the date the rate starts' using errcode = 'P0001'; end if;
  if p_effective_from < date '2000-01-01' or p_effective_from > today + 366 then raise exception 'BAD_RATE: choose a start date within the next year' using errcode = 'P0001'; end if;
  if why is null then raise exception 'REASON_REQUIRED: say why (for example "Starting rate" or "Annual review")' using errcode = 'P0001'; end if;
  if length(why) > 300 then raise exception 'TOO_LONG: keep the reason under 300 characters' using errcode = 'P0001'; end if;
  insert into tutor_pay_rates(id, org_id, membership_id, student_id, level, method, amount_cents, percent_bp, effective_from, reason)
  values (nid, p_org, p_membership, p_student, lv, p_method, p_amount_cents, p_percent_bp, p_effective_from, why);
  insert into audit_log(org_id, actor, action, table_name, row_id, before, after)
  values (p_org, auth.uid(), 'centre_tutor_rate_set', 'tutor_pay_rates', nid::text, null,
          jsonb_build_object('method', p_method, 'amount_cents', p_amount_cents, 'percent_bp', p_percent_bp, 'effective_from', p_effective_from,
                             'scope', case when p_student is not null then 'student' when lv is not null then 'level' else 'default' end));
  return jsonb_build_object('id', nid, 'effective_from', p_effective_from, 'method', p_method);
end $$;

-- ---------------------------------------------------------------------------------------------------
-- 5. THE PAY LIST
-- ---------------------------------------------------------------------------------------------------
create or replace function public.centre_tutor_pay_list(p_org uuid, p_month date default null) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare today date := centre_tutor_pay_gate(p_org, 'full'); s jsonb := org_settings_on(p_org, today); cut int := coalesce((s #>> '{tutor_pay,cycle,cutoff_day}')::int, 31);
        pf date; pt date; r jsonb; unassigned int;
begin
  select x.p_from, x.p_to into pf, pt from centre_tutor_period(coalesce(p_month, today), cut) x;
  select count(*) into unassigned from lessons l where l.org_id = p_org and l.taught_by is null and l.status = 'done' and l.lesson_date between pf and pt;
  with rows as (select * from centre_tutor_pay_rows(p_org, pf, pt)),
  rg as (
    select x.membership_id as mid, sum(x.released_before) as rel_before, sum(x.released_to - x.released_before) as rel_in,
           coalesce(sum(x.earn_cents - x.released_to) filter (where x.earn_cents is not null and x.earn_on <= pt), 0) as held,
           count(*) filter (where x.earn_on between pf and pt) as lessons,
           coalesce(sum(x.minutes) filter (where x.earn_on between pf and pt and x.lesson_status = 'done'), 0) as mins,
           count(*) filter (where x.state = 'waiting_invoice') as w_inv, count(*) filter (where x.state = 'waiting_charge') as w_chg,
           count(*) filter (where x.state = 'no_rate' and x.earn_on <= pt) as no_rate, count(*) filter (where x.state in ('held', 'part')) as n_held
      from rows x group by x.membership_id
  ), who as (
    select m.id as mid, m.display_name as nm, m.employment_type as et, m.status as st from memberships m
     where m.org_id = p_org and m.role in ('tutor', 'staff', 'owner')
       and (m.status <> 'disabled' or m.id in (select mid from rg) or m.id in (select membership_id from tutor_pay_payments where org_id = p_org))
       and (m.role = 'tutor' or m.id in (select mid from rg) or exists (select 1 from tutor_pay_rates x where x.org_id = p_org and x.membership_id = m.id))
  ), agg as (
    select w.mid, w.nm, w.et, w.st,
      coalesce(g.rel_before, 0) as rel_before, coalesce(g.rel_in, 0) as rel_in, coalesce(g.held, 0) as held, coalesce(g.lessons, 0) as lessons, coalesce(g.mins, 0) as mins,
      coalesce(g.w_inv, 0) as w_inv, coalesce(g.w_chg, 0) as w_chg, coalesce(g.no_rate, 0) as no_rate, coalesce(g.n_held, 0) as n_held,
      mo.before_cents as mo_before, mo.period_cents as mo_in,
      coalesce((select sum(a.amount_cents) from tutor_pay_adjustments a where a.org_id = p_org and a.membership_id = w.mid and a.effective_on < pf), 0) as adj_before,
      coalesce((select sum(a.amount_cents) from tutor_pay_adjustments a where a.org_id = p_org and a.membership_id = w.mid and a.effective_on between pf and pt), 0) as adj_in,
      coalesce((select sum(case when p.kind = 'payment' then p.amount_cents else -p.amount_cents end) from tutor_pay_payments p
                 where p.org_id = p_org and p.membership_id = w.mid and p.period_to < pf), 0) as paid_before,
      coalesce((select sum(case when p.kind = 'payment' then p.amount_cents else -p.amount_cents end) from tutor_pay_payments p
                 where p.org_id = p_org and p.membership_id = w.mid and p.period_to = pt), 0) as paid_now
      from who w left join rg g on g.mid = w.mid cross join lateral centre_tutor_monthly(p_org, w.mid, pf, pt, cut) mo
  ), fin as (
    select agg.*, (rel_before + mo_before + adj_before - paid_before) as carry,
           (rel_before + mo_before + adj_before - paid_before) + rel_in + mo_in + adj_in as due from agg
  )
  select jsonb_build_object(
    'period_from', pf, 'period_to', pt, 'month', date_trunc('month', pt)::date, 'cutoff_day', cut, 'pay_day', coalesce((s #>> '{tutor_pay,cycle,pay_day}')::int, 7),
    'payable_when', coalesce(s #>> '{tutor_pay,payable_when}', 'parent_paid'), 'adjustments_on', coalesce((s #>> '{tutor_pay,adjustments}')::boolean, false),
    'unassigned_lessons', unassigned, 'today', today,
    'tutors', coalesce(jsonb_agg(jsonb_build_object(
        'membership_id', f.mid, 'name', f.nm, 'employment_type', f.et, 'status', f.st, 'lessons', f.lessons, 'minutes', f.mins,
        'carry_cents', f.carry, 'released_cents', f.rel_in, 'monthly_cents', f.mo_in, 'adjustments_cents', f.adj_in, 'due_cents', f.due,
        'paid_cents', f.paid_now, 'outstanding_cents', f.due - f.paid_now, 'held_cents', f.held, 'held_lessons', f.n_held,
        'waiting_invoice', f.w_inv, 'waiting_charge', f.w_chg, 'no_rate', f.no_rate, 'frozen_to', tutor_pay_frozen_to(p_org, f.mid),
        'pay_state', case when f.due - f.paid_now <= 0 and f.paid_now > 0 then 'paid' when f.paid_now > 0 then 'part_paid'
                          when f.due <= 0 then 'nothing_due' else 'unpaid' end) order by f.nm), '[]'::jsonb),
    'totals', jsonb_build_object('due_cents', coalesce(sum(greatest(f.due, 0)), 0), 'paid_cents', coalesce(sum(f.paid_now), 0),
                                 'outstanding_cents', coalesce(sum(greatest(f.due - f.paid_now, 0)), 0), 'held_cents', coalesce(sum(f.held), 0))
  ) into r from fin f;
  return r;
end $$;

-- One tutor's lines for the period: lessons counted in it (by the day they became countable), lessons still held from earlier, adjustments and payments.
create or replace function public.centre_tutor_pay_detail(p_org uuid, p_membership uuid, p_month date default null) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare today date := centre_tutor_pay_gate(p_org, 'full'); s jsonb := org_settings_on(p_org, today); cut int := coalesce((s #>> '{tutor_pay,cycle,cutoff_day}')::int, 31);
        pf date; pt date; r jsonb; m memberships;
begin
  select * into m from memberships where id = p_membership and org_id = p_org and role in ('tutor', 'staff', 'owner');
  if m.id is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  select x.p_from, x.p_to into pf, pt from centre_tutor_period(coalesce(p_month, today), cut) x;
  select jsonb_build_object(
    'membership_id', m.id, 'name', m.display_name, 'period_from', pf, 'period_to', pt,
    'lines', coalesce((select jsonb_agg(jsonb_build_object(
        'lesson_id', x.lesson_id, 'date', x.lesson_date, 'student', st.name, 'minutes', x.minutes, 'lesson_status', x.lesson_status, 'trial', x.is_trial,
        'method', x.method, 'scope', x.rate_scope, 'earn_cents', x.earn_cents, 'base_cents', x.base_cents, 'state', x.state,
        'released_cents', x.released_to - x.released_before, 'held_cents', case when x.earn_cents is null then null else x.earn_cents - x.released_to end,
        'in_period', x.earn_on between pf and pt) order by x.lesson_date, x.lesson_id)
      from centre_tutor_pay_rows(p_org, pf, pt, p_membership) x left join students st on st.id = x.student_id and st.org_id = p_org
     where (x.earn_on between pf and pt or (x.released_to - x.released_before) <> 0
            or (x.earn_on <= pt and x.state in ('held', 'part', 'waiting_invoice', 'waiting_charge', 'no_rate')))), '[]'::jsonb),
    'adjustments', coalesce((select jsonb_agg(jsonb_build_object('id', a.id, 'kind', a.kind, 'amount_cents', a.amount_cents, 'effective_on', a.effective_on, 'reason', a.reason) order by a.effective_on, a.created_at)
        from tutor_pay_adjustments a where a.org_id = p_org and a.membership_id = p_membership and a.effective_on between pf and pt), '[]'::jsonb),
    'payments', coalesce((select jsonb_agg(jsonb_build_object('id', p.id, 'kind', p.kind, 'amount_cents', p.amount_cents, 'paid_on', p.paid_on, 'method', p.method,
                                                              'reference', p.reference, 'reversed', exists (select 1 from tutor_pay_payments v where v.reverses_payment_id = p.id)) order by p.paid_on, p.created_at)
        from tutor_pay_payments p where p.org_id = p_org and p.membership_id = p_membership and p.period_to = pt), '[]'::jsonb)
  ) into r;
  return r;
end $$;

-- ---------------------------------------------------------------------------------------------------
-- 6. ADJUSTMENTS and RECORDING PAYMENTS
-- ---------------------------------------------------------------------------------------------------
create or replace function public.centre_tutor_pay_adjust(p_org uuid, p_membership uuid, p_amount_cents bigint, p_on date, p_reason text) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare today date := centre_tutor_pay_gate(p_org, 'full'); s jsonb := org_settings_on(p_org, today); why text := nullif(trim(coalesce(p_reason, '')), ''); nid uuid := gen_random_uuid(); d date := coalesce(p_on, today);
begin
  if not coalesce((s #>> '{tutor_pay,adjustments}')::boolean, false) then
    raise exception 'ADJUSTMENTS_OFF: bonuses and deductions are switched off in Centre settings' using errcode = 'P0001'; end if;
  if not exists (select 1 from memberships m where m.id = p_membership and m.org_id = p_org and m.role in ('tutor', 'staff', 'owner') and m.status <> 'disabled') then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  if p_amount_cents is null or p_amount_cents = 0 or abs(p_amount_cents) > 100000000 then raise exception 'BAD_AMOUNT: enter an amount (plus for a bonus, minus for a deduction)' using errcode = 'P0001'; end if;
  if why is null then raise exception 'REASON_REQUIRED: say why this bonus or deduction is being made' using errcode = 'P0001'; end if;
  if length(why) > 300 then raise exception 'TOO_LONG: keep the reason under 300 characters' using errcode = 'P0001'; end if;
  if d < today - 400 or d > today + 62 then raise exception 'BAD_DATE: choose a date within the last year or the next two months' using errcode = 'P0001'; end if;
  insert into tutor_pay_adjustments(id, org_id, membership_id, kind, amount_cents, effective_on, reason)
  values (nid, p_org, p_membership, case when p_amount_cents > 0 then 'bonus' else 'deduction' end, p_amount_cents, d, why);
  insert into audit_log(org_id, actor, action, table_name, row_id, before, after)
  values (p_org, auth.uid(), 'centre_tutor_pay_adjust', 'tutor_pay_adjustments', nid::text, null, jsonb_build_object('amount_cents', p_amount_cents, 'effective_on', d));
  return jsonb_build_object('id', nid, 'kind', case when p_amount_cents > 0 then 'bonus' else 'deduction' end, 'amount_cents', p_amount_cents, 'effective_on', d);
end $$;

-- "the centre paid this tutor" for the period of p_month. Never more than what is still outstanding for that period.
create or replace function public.centre_tutor_pay_record(p_org uuid, p_membership uuid, p_month date, p_amount_cents bigint, p_paid_on date,
  p_method text, p_reference text default null, p_note text default null) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare today date := centre_tutor_pay_gate(p_org, 'full'); s jsonb := org_settings_on(p_org, today); cut int := coalesce((s #>> '{tutor_pay,cycle,cutoff_day}')::int, 31);
        pf date; pt date; m memberships; lst jsonb; t jsonb; out_c bigint; nid uuid := gen_random_uuid();
begin
  select * into m from memberships where id = p_membership and org_id = p_org and role in ('tutor', 'staff', 'owner');
  if m.id is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  if p_method is null or p_method not in ('paynow', 'bank', 'cash', 'cheque', 'other') then raise exception 'BAD_METHOD: pick how you paid' using errcode = 'P0001'; end if;
  if p_amount_cents is null or p_amount_cents <= 0 then raise exception 'BAD_AMOUNT: enter the amount paid' using errcode = 'P0001'; end if;
  if p_paid_on is null or p_paid_on > today or p_paid_on < today - 400 then raise exception 'BAD_DATE: choose the day you paid (not in the future)' using errcode = 'P0001'; end if;
  if length(coalesce(p_reference, '')) > 100 or length(coalesce(p_note, '')) > 300 then raise exception 'TOO_LONG: shorten the reference or note' using errcode = 'P0001'; end if;
  if coalesce(p_reference, '') ~ '[0-9]{8,}' or coalesce(p_note, '') ~ '[0-9]{8,}' then
    raise exception 'BAD_REFERENCE: don''t type a whole bank or PayNow number (it is kept in the record); the last 4 digits are enough' using errcode = 'P0001'; end if;
  select x.p_from, x.p_to into pf, pt from centre_tutor_period(coalesce(p_month, today), cut) x;
  perform pg_advisory_xact_lock(hashtextextended(p_membership::text, 21));
  lst := centre_tutor_pay_list(p_org, pt);
  select e into t from jsonb_array_elements(lst->'tutors') e where (e->>'membership_id')::uuid = p_membership;
  out_c := coalesce((t->>'outstanding_cents')::bigint, 0);
  if p_amount_cents > out_c then
    raise exception 'TOO_MUCH: only % is still to pay for this period', centre_fmt_money(greatest(out_c, 0)) using errcode = 'P0001'; end if;
  insert into tutor_pay_payments(id, org_id, membership_id, tutor_name, period_from, period_to, amount_cents, paid_on, method, reference, note)
  values (nid, p_org, p_membership, m.display_name, pf, pt, p_amount_cents, p_paid_on, p_method, nullif(trim(coalesce(p_reference, '')), ''), nullif(trim(coalesce(p_note, '')), ''));
  insert into audit_log(org_id, actor, action, table_name, row_id, before, after)
  values (p_org, auth.uid(), 'centre_tutor_pay_record', 'tutor_pay_payments', nid::text, null,
          jsonb_build_object('amount_cents', p_amount_cents, 'period_to', pt, 'method', p_method, 'paid_on', p_paid_on));
  return jsonb_build_object('id', nid, 'amount_cents', p_amount_cents, 'period_from', pf, 'period_to', pt, 'outstanding_cents', out_c - p_amount_cents);
end $$;

-- a mistake in a recorded payment: a REVERSAL row (the original stays). The period is open again if nothing else is recorded for it.
create or replace function public.centre_tutor_pay_reverse(p_payment uuid, p_reason text) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare org uuid; today date; p tutor_pay_payments; why text := nullif(trim(coalesce(p_reason, '')), ''); nid uuid := gen_random_uuid();
begin
  if auth.uid() is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  select x.org_id into org from tutor_pay_payments x where x.id = p_payment;
  if org is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  today := centre_tutor_pay_gate(org, 'full');
  perform pg_advisory_xact_lock(hashtextextended(p_payment::text, 22));
  select * into p from tutor_pay_payments where id = p_payment and org_id = org;
  if p.kind <> 'payment' then raise exception 'NOT_ALLOWED: that is already a reversal' using errcode = '42501'; end if;
  if exists (select 1 from tutor_pay_payments r where r.reverses_payment_id = p.id) then
    return jsonb_build_object('id', p.id, 'already', true); end if;
  if why is null then raise exception 'REASON_REQUIRED: say why this payment is being reversed' using errcode = 'P0001'; end if;
  if length(why) > 300 then raise exception 'TOO_LONG: keep the reason under 300 characters' using errcode = 'P0001'; end if;
  insert into tutor_pay_payments(id, org_id, kind, reverses_payment_id, membership_id, tutor_name, period_from, period_to, amount_cents, paid_on, method, note)
  values (nid, org, 'reversal', p.id, p.membership_id, p.tutor_name, p.period_from, p.period_to, p.amount_cents, greatest(today, p.paid_on), p.method, why);
  insert into audit_log(org_id, actor, action, table_name, row_id, before, after)
  values (org, auth.uid(), 'centre_tutor_pay_reverse', 'tutor_pay_payments', nid::text, null, jsonb_build_object('amount_cents', p.amount_cents, 'period_to', p.period_to));
  return jsonb_build_object('id', nid, 'already', false, 'amount_cents', p.amount_cents);
end $$;

-- writes the "pay list exported" line of the audit log (counts and totals only, never names or bank details)
create or replace function public.centre_tutor_pay_export_log(p_org uuid, p_month date, p_rows int, p_total_cents bigint) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare today date := centre_tutor_pay_gate(p_org, 'full');
begin
  insert into audit_log(org_id, actor, action, table_name, row_id, before, after)
  values (p_org, auth.uid(), 'centre_tutor_pay_export', 'tutor_pay_payments', coalesce(p_org::text, '') || ':' || coalesce(date_trunc('month', p_month)::date::text, today::text), null,
          jsonb_build_object('month', date_trunc('month', coalesce(p_month, today))::date, 'rows', coalesce(p_rows, 0), 'total_cents', coalesce(p_total_cents, 0)));
  return jsonb_build_object('logged', true);
end $$;

-- ---------------------------------------------------------------------------------------------------
-- 7. THE LESSONS-TAUGHT REPORT (mode report or full): counts and hours per tutor, NO money
-- ---------------------------------------------------------------------------------------------------
create or replace function public.centre_tutor_taught_report(p_org uuid, p_month date default null) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare today date := centre_tutor_pay_gate(p_org, 'report'); m0 date := date_trunc('month', coalesce(p_month, today))::date; m1 date := (date_trunc('month', coalesce(p_month, today)) + interval '1 month - 1 day')::date; r jsonb; unassigned int;
begin
  select count(*) into unassigned from lessons l where l.org_id = p_org and l.taught_by is null and l.status = 'done' and l.lesson_date between m0 and m1;
  select jsonb_build_object('month', m0, 'unassigned_lessons', unassigned, 'tutors', coalesce(jsonb_agg(jsonb_build_object(
      'membership_id', q.mid, 'name', q.nm, 'employment_type', q.et, 'lessons', q.n, 'minutes', q.mins, 'students', q.stu, 'cancelled', q.canc, 'trials', q.trials) order by q.nm), '[]'::jsonb))
    into r
    from (select m.id as mid, m.display_name as nm, m.employment_type as et,
                 count(*) filter (where l.status = 'done') as n,
                 coalesce(sum(greatest((extract(epoch from (l.end_time - l.start_time)) / 60)::int, 0)) filter (where l.status = 'done'), 0) as mins,
                 count(distinct l.student_id) filter (where l.status = 'done') as stu,
                 count(*) filter (where l.status = 'cancelled') as canc,
                 count(*) filter (where l.status = 'done' and l.trial) as trials
            from memberships m join lessons l on l.taught_by = m.id and l.org_id = m.org_id and l.lesson_date between m0 and m1 and l.status in ('done', 'cancelled')
           where m.org_id = p_org group by m.id, m.display_name, m.employment_type) q;
  return r;
end $$;

-- ---------------------------------------------------------------------------------------------------
-- 8. who may call what: browsers get only the screen functions; the helpers and the calculation are internal
-- ---------------------------------------------------------------------------------------------------
revoke all on function public.tutor_pay_appendonly() from public, anon, authenticated;
revoke all on function public.tutor_pay_frozen_to(uuid, uuid) from public, anon, authenticated;
revoke all on function public.tutor_pay_freeze_guard() from public, anon, authenticated;
revoke all on function public.tutor_pay_payment_guard() from public, anon, authenticated;
revoke all on function public.centre_tutor_pay_gate(uuid, text) from public, anon, authenticated;
revoke all on function public.centre_tutor_period(date, int) from public, anon, authenticated;
revoke all on function public.centre_tutor_rate_for(uuid, uuid, uuid, text, date) from public, anon, authenticated;
revoke all on function public.centre_tutor_monthly(uuid, uuid, date, date, int) from public, anon, authenticated;
revoke all on function public.centre_tutor_pay_rows(uuid, date, date, uuid) from public, anon, authenticated;
revoke all on function public.centre_tutor_rate_list(uuid) from public, anon;
revoke all on function public.centre_tutor_rate_set(uuid, uuid, uuid, text, text, bigint, int, date, text) from public, anon;
revoke all on function public.centre_tutor_pay_list(uuid, date) from public, anon;
revoke all on function public.centre_tutor_pay_detail(uuid, uuid, date) from public, anon;
revoke all on function public.centre_tutor_pay_adjust(uuid, uuid, bigint, date, text) from public, anon;
revoke all on function public.centre_tutor_pay_record(uuid, uuid, date, bigint, date, text, text, text) from public, anon;
revoke all on function public.centre_tutor_pay_reverse(uuid, text) from public, anon;
revoke all on function public.centre_tutor_pay_export_log(uuid, date, int, bigint) from public, anon;
revoke all on function public.centre_tutor_taught_report(uuid, date) from public, anon;
grant execute on function public.centre_tutor_rate_list(uuid), public.centre_tutor_rate_set(uuid, uuid, uuid, text, text, bigint, int, date, text),
  public.centre_tutor_pay_list(uuid, date), public.centre_tutor_pay_detail(uuid, uuid, date), public.centre_tutor_pay_adjust(uuid, uuid, bigint, date, text),
  public.centre_tutor_pay_record(uuid, uuid, date, bigint, date, text, text, text), public.centre_tutor_pay_reverse(uuid, text),
  public.centre_tutor_pay_export_log(uuid, date, int, bigint), public.centre_tutor_taught_report(uuid, date) to authenticated, service_role;

-- #####################################################################################################
-- ### PART 4 of 7 — bank statement matching: upload, rules, review queue, confirm, undo
-- ### source branch: claude/t34-m0-matching   file: db/migration_statement_matching.sql   undo: db/migration_statement_matching_down.sql
-- ### (if an error appears, search this file for the nearest "### PART" line above the error line: that is the part that failed)
-- #####################################################################################################
-- =====================================================================================================
-- T34 M0-M2 — bank statement matching for centres (engine + custom column mapping)       undo: migration_statement_matching_down.sql
-- =====================================================================================================
-- Run order everywhere: org_foundation → billing → attendance → tutor_access → org_delete → function_lockdown → org_separation →
--   staff_home → staff_students → staff_attendance → staff_charges → staff_trials → staff_timetable → money_settings → centre_money →
--   centre_invoice_run → centre_payments → centre_deposits → centre_refunds → centre_late_fees → centre_credit_undo → statement_matching.
-- Needs migration_centre_payments.sql (centre_record_payment / centre_reverse_payment: the ONLY way money is written here) and
-- migration_centre_credit_undo.sql (the organisation-aware settings check, which this file extends).
-- Run on the DEV project first. LIVE only when the owner says ship (six new tables, new functions, one re-created function; it reads and changes no
-- existing row). Safe to run twice. Plan: docs/orchestrator/T34-plan.md (branch claude/t34-plan).
--
-- WHAT IT DOES
--   An owner (or staff with record_payments) uploads a bank statement. The BROWSER parses the file with a saved column mapping and sends only the
--   mapped fields (date, signed cents, reference text, payer text, the bank's own reference), account numbers cut to their last 4 digits. The database
--   stores the lines, drops the ones it has seen before (a fingerprint per line), runs the matching rules, and puts what it cannot settle in a
--   REVIEW QUEUE. Nothing is edited: a wrong match is UNDONE through the same reversal as any payment.
--
-- RULES (credit lines only; "open" = an issued, non-credit-note invoice with a balance; the date window applies to every rule)
--   A  the centre's own invoice number is found in the reference (case, spacing and punctuation ignored) AND the amount equals that invoice's balance
--      → EXACT.  A number found with another amount, an invoice already paid, or two numbers → review, with the reason in plain words.
--   B  a remembered payer (normalised name → household) AND exactly one open invoice of that household has exactly this balance → EXACT.
--   C  amount only: exactly one open invoice in the whole centre has this balance → SUGGESTION ONLY (never automatic).
--   D  the line equals everything one family owes (or, for a known payer, exactly one combination of at most 10 open invoices) → SUGGESTION ONLY.
--   Exact cents only: S$0.01 off goes to review, showing the difference. Money out (debits) is never matched; a person marks it "not ours".
--   Auto-confirm is the centre's choice (payments.statement.auto_confirm): exact_only (rules A and B pay by themselves) or never (every line waits).
--
-- SETTINGS (org_validate_settings; the labels and defaults are in assets/js/org-settings.js, tests/org-settings.test.js compares the values)
--   payments.modes ∋ statement_matching     every function below refuses a centre that has not switched it on
--   payments.statement.auto_confirm         exact_only (default) | never
--   payments.statement.window_before_days   0-30 (default 7)   payment date may be this many days BEFORE the invoice was issued
--   payments.statement.window_after_days    0-365 (default 90) ... and this many days AFTER it was due
--   payments.statement_bank                 DBS | OCBC | UOB | custom. The three banks are UNVERIFIED (no real sample file yet): only "custom" works.
--   Process rules are read as of TODAY (CLAUDE.md); the money rules (partial payments, overpayments) are those of centre_record_payment.
--
-- WHO MAY CALL  an active owner or staff with record_payments (and the mode switched on). Tutors, parents, solo organisations, other centres,
--   switched-off staff and strangers all get NOT_FOUND / NOT_ALLOWED. The tables have NO write policy: only these SECURITY DEFINER functions write.
-- MONEY PATH    a confirmed match calls centre_record_payment (method 'bank'); an undo calls centre_reverse_payment. No second way to write money.
--   The payment gets the bank's own reference only: never the payer's name, never the statement text.
-- RETENTION     a raw line is DELETED the moment it is resolved; an unresolved one 60 days after it was imported (purged inside import / confirm /
--   undo, no cron). Kept: the fingerprint (a hash, no text), a name-free match record (date, cents, rule, payment, who, when), and payer links
--   (normalised names, listed and forgettable on the screen).
-- AUDIT         match / link / mapping / batch rows are copied to the audit log with every text field replaced by "[redacted]"; the raw lines are
--   never copied (each function writes one summary line with counts only).
-- IDEMPOTENT    the same file twice adds nothing: a line is its fingerprint (centre + account label + date + signed cents + normalised reference +
--   bank reference) PLUS an occurrence number, so two real identical payments in one file are both kept but the second upload adds none.
-- =====================================================================================================

-- ---------------------------------------------------------------------------------------------------
-- 1. small pure helpers (the JS twin is assets/js/statement-core.js; tests/statement-vectors.csv holds the shared examples)
-- ---------------------------------------------------------------------------------------------------
-- a run of 9 or more digits keeps only its last 4 (account numbers must never be stored in full)
create or replace function public.stmt_mask_digits(t text) returns text language sql immutable set search_path = public as $$
  select regexp_replace(t, '[0-9]{5,}([0-9]{4})', '****\1', 'g') $$;
-- "Mr  TAN, Ah-Kow" → "mr tan ah kow"  (the key of a payer link)
create or replace function public.stmt_norm_payer(t text) returns text language sql immutable set search_path = public as $$
  select trim(regexp_replace(regexp_replace(lower(coalesce(t, '')), '[^a-z0-9]+', ' ', 'g'), '\s+', ' ', 'g')) $$;
-- the reference text as it goes into a fingerprint: same rule as a payer
create or replace function public.stmt_norm_ref(t text) returns text language sql immutable set search_path = public as $$
  select public.stmt_norm_payer(public.stmt_mask_digits(t)) $$;
-- the regular expression that finds an invoice number in lower-cased reference text: INV-12 matches "inv 12", "INV-12", "inv12" but NOT "inv123" or "inv-1"
create or replace function public.stmt_number_pattern(n text) returns text language sql immutable set search_path = public as $$
  select '(^|[^a-z0-9])' || (select string_agg(m[1], '[^a-z0-9]*') from regexp_matches(lower(n), '([a-z]+|[0-9]+)', 'g') m) || '([^a-z0-9]|$)' $$;
create or replace function public.stmt_fp(p_org uuid, p_account text, p_date date, p_cents bigint, p_ref_norm text, p_bank_ref text) returns text
language sql immutable set search_path = public as $$
  select encode(sha256(convert_to(concat_ws('|', p_org::text, lower(trim(coalesce(p_account, ''))), p_date::text, p_cents::text, coalesce(p_ref_norm, ''),
                                            lower(trim(coalesce(p_bank_ref, '')))), 'UTF8')), 'hex') $$;
-- how many of p_bals' combinations add up to p_target, and which one if there is exactly one (at most 10 invoices; the whole set counts as one combination)
create or replace function public.stmt_subsets(p_ids uuid[], p_bals bigint[], p_target bigint) returns jsonb
language plpgsql immutable set search_path = public as $$
declare n int := coalesce(cardinality(p_ids), 0); mask int; i int; tot bigint; cnt int := 0; hit int := 0;
begin
  if n < 1 or n > 10 then return jsonb_build_object('count', 0, 'ids', '[]'::jsonb); end if;
  for mask in 1 .. (1 << n) - 1 loop
    tot := 0;
    for i in 0 .. n - 1 loop if (mask & (1 << i)) <> 0 then tot := tot + p_bals[i + 1]; end if; end loop;
    if tot = p_target then cnt := cnt + 1; hit := mask; end if;
  end loop;
  return jsonb_build_object('count', cnt, 'ids', case when cnt = 1 then (select coalesce(jsonb_agg(p_ids[g.k + 1]), '[]'::jsonb) from generate_series(0, n - 1) g(k) where (hit & (1 << g.k)) <> 0) else '[]'::jsonb end);
end $$;

-- ---------------------------------------------------------------------------------------------------
-- 2. tables (centres only; read by record_payments; NO write policy)
-- ---------------------------------------------------------------------------------------------------
create table if not exists public.statement_mappings (
  id          uuid primary key default gen_random_uuid(),
  org_id      uuid not null references public.organisations(id) on delete cascade,
  name        text not null check (length(trim(name)) between 1 and 60),
  version     int not null default 1 check (version >= 1),
  mapping     jsonb not null,
  created_by  uuid default auth.uid(),
  created_at  timestamptz not null default now(),
  unique (org_id, name, version),
  unique (id, org_id)
);
create table if not exists public.statement_batches (       -- no file name: names can sit in file names
  id          uuid primary key default gen_random_uuid(),
  org_id      uuid not null references public.organisations(id) on delete cascade,
  account_label text not null check (length(trim(account_label)) between 1 and 40),
  mapping_id  uuid,
  date_from   date, date_to date,
  n_lines int not null default 0, n_new int not null default 0, n_duplicate int not null default 0, n_skipped int not null default 0,
  n_auto int not null default 0, n_review int not null default 0,
  imported_by uuid default auth.uid(),
  imported_at timestamptz not null default now(),
  unique (id, org_id),
  foreign key (mapping_id, org_id) references public.statement_mappings(id, org_id)
);
create table if not exists public.statement_fingerprints (  -- kept: a hash, no text
  org_id      uuid not null references public.organisations(id) on delete cascade,
  fp          text not null,
  occ         int not null check (occ >= 1),
  batch_id    uuid,
  first_seen  date not null default current_date,
  primary key (org_id, fp, occ)
);
create table if not exists public.statement_lines (          -- DELETED when resolved (or 60 days after import)
  id          uuid primary key default gen_random_uuid(),
  org_id      uuid not null references public.organisations(id) on delete cascade,
  batch_id    uuid,
  row_no      int not null default 0,
  line_date   date not null,
  cents       bigint not null check (cents <> 0 and abs(cents) <= 100000000000),
  ref_text    text,
  payer_text  text,
  bank_ref    text,
  fp          text not null,
  occ         int not null check (occ >= 1),
  stub        boolean not null default false,                 -- put back after an undo: date and amount only
  sugg_rule   text check (sugg_rule in ('invoice_no', 'payer_link', 'amount_only', 'household_total')),
  sugg_exact  boolean not null default false,                 -- the amount equals what is owed on the suggested invoice(s)
  sugg_invoice_ids uuid[] not null default '{}',
  sugg_household uuid,
  reason      text,                                           -- plain words, shown on the screen
  purge_after date not null,
  created_at  timestamptz not null default now(),
  unique (id, org_id),
  unique (org_id, fp, occ),
  foreign key (batch_id, org_id) references public.statement_batches(id, org_id) on delete cascade
);
create index if not exists statement_lines_org on public.statement_lines(org_id, line_date, row_no);
create table if not exists public.statement_matches (        -- kept, NO names
  id          uuid primary key default gen_random_uuid(),
  org_id      uuid not null references public.organisations(id) on delete cascade,
  batch_id    uuid,
  fp          text not null,
  occ         int not null,
  line_date   date not null,
  cents       bigint not null,
  kind        text not null check (kind in ('invoice', 'ignored')),
  rule        text not null check (rule in ('invoice_no', 'payer_link', 'amount_only', 'household_total', 'manual')),
  household_id uuid,
  payment_id  uuid,
  auto        boolean not null default false,
  confirmed_by uuid,
  confirmed_at timestamptz not null default now(),
  reversed_at timestamptz, reversed_by uuid, reverse_reason text,
  unique (id, org_id),
  foreign key (payment_id, org_id) references public.centre_payments(id, org_id),
  check ((kind = 'invoice') = (payment_id is not null)),
  check ((reversed_at is null) = (reversed_by is null))
);
create unique index if not exists statement_matches_live on public.statement_matches(org_id, fp, occ) where reversed_at is null;
create unique index if not exists statement_matches_payment on public.statement_matches(payment_id) where payment_id is not null;
create index if not exists statement_matches_org on public.statement_matches(org_id, confirmed_at desc);
create table if not exists public.statement_payer_links (    -- a normalised NAME: listed on the screen, forgettable
  id          uuid primary key default gen_random_uuid(),
  org_id      uuid not null references public.organisations(id) on delete cascade,
  payer_key   text not null check (length(payer_key) between 1 and 120),
  household_id uuid not null,
  times_used  int not null default 1,
  last_used   date not null default current_date,
  created_at  timestamptz not null default now(),
  unique (org_id, payer_key),
  unique (id, org_id),
  foreign key (household_id, org_id) references public.households(id, org_id) on delete cascade
);

-- audit: match / link / mapping / batch rows only, text fields redacted. The raw lines and fingerprints are never copied.
create or replace function public.stmt_audit() returns trigger
language plpgsql security definer set search_path = public as $$
declare b jsonb; a jsonb; k text; redact text[] := array['payer_key', 'reverse_reason', 'reason', 'ref_text', 'payer_text', 'bank_ref', 'name'];
begin
  if coalesce(current_setting('td.skip_audit', true), '') = '1' then return null; end if;
  b := case when tg_op in ('UPDATE', 'DELETE') then to_jsonb(old) end;
  a := case when tg_op in ('INSERT', 'UPDATE') then to_jsonb(new) end;
  foreach k in array redact loop
    if b ? k and b->>k is not null then b := jsonb_set(b, array[k], '"[redacted]"'); end if;
    if a ? k and a->>k is not null then a := jsonb_set(a, array[k], '"[redacted]"'); end if;
  end loop;
  insert into audit_log(org_id, actor, action, table_name, row_id, before, after)
  values (coalesce((a->>'org_id')::uuid, (b->>'org_id')::uuid), auth.uid(), lower(tg_op), tg_table_name, coalesce(a->>'id', b->>'id'), b, a);
  return null;
end $$;
do $$
declare t text;
begin
  foreach t in array array['statement_mappings', 'statement_batches', 'statement_matches', 'statement_payer_links'] loop
    execute format('drop trigger if exists audit_row on public.%I', t);
    execute format('create trigger audit_row after insert or update or delete on public.%I for each row execute function public.stmt_audit()', t);
  end loop;
end $$;

alter table public.statement_mappings enable row level security;
alter table public.statement_batches enable row level security;
alter table public.statement_fingerprints enable row level security;
alter table public.statement_lines enable row level security;
alter table public.statement_matches enable row level security;
alter table public.statement_payer_links enable row level security;
do $$
declare t text;
begin
  foreach t in array array['statement_mappings', 'statement_batches', 'statement_lines', 'statement_matches', 'statement_payer_links'] loop
    execute format('drop policy if exists money_read on public.%I', t);
    execute format('create policy money_read on public.%I for select using (org_can(org_id, ''record_payments'') and not org_is_solo(org_id))', t);
  end loop;
end $$;
revoke all on public.statement_mappings, public.statement_batches, public.statement_fingerprints, public.statement_lines, public.statement_matches, public.statement_payer_links from anon, authenticated;
grant select on public.statement_mappings, public.statement_batches, public.statement_lines, public.statement_matches, public.statement_payer_links to authenticated;

-- ---------------------------------------------------------------------------------------------------
-- 3. the gate, the settings, the mapping
-- ---------------------------------------------------------------------------------------------------
create or replace function public.stmt_gate(p_org uuid) returns date
language plpgsql stable security definer set search_path = public as $$
declare today date := centre_money_gate(p_org, 'record_payments'); s jsonb;
begin
  s := org_settings_on(p_org, today);
  if s is null or not ((coalesce(s#>'{payments,modes}', '[]'::jsonb)) ? 'statement_matching') then
    raise exception 'NOT_ALLOWED: bank statement matching isn''t switched on in this centre''s payment settings' using errcode = '42501'; end if;
  return today;
end $$;

-- a mapping is a small document; the browser checks it too (statement-core.js validateMapping)
create or replace function public.stmt_save_mapping(p_org uuid, p_name text, p_mapping jsonb) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare today date := stmt_gate(p_org); nm text := nullif(trim(coalesce(p_name, '')), ''); m jsonb := p_mapping; v int; mid uuid := gen_random_uuid(); k text; c jsonb;
begin
  if nm is null or length(nm) > 60 then raise exception 'BAD_VALUE: give the mapping a name (up to 60 characters)' using errcode = 'P0001'; end if;
  if jsonb_typeof(m) is distinct from 'object' then raise exception 'BAD_VALUE: the mapping is missing' using errcode = 'P0001'; end if;
  if m->>'delimiter' is null or m->>'delimiter' not in (',', ';', E'\t', '|') then raise exception 'BAD_VALUE: pick the column separator' using errcode = 'P0001'; end if;
  if m->>'header_rows' is null or m->>'header_rows' !~ '^[0-9]{1,2}$' then raise exception 'BAD_VALUE: say how many rows to skip above the table (0-99)' using errcode = 'P0001'; end if;
  if m->>'date_format' is null or m->>'date_format' not in ('dmy_slash', 'dmy_dash', 'dmy_text', 'iso', 'mdy_slash') then raise exception 'BAD_VALUE: pick the date format' using errcode = 'P0001'; end if;
  if m->>'amount_mode' is null or m->>'amount_mode' not in ('signed', 'debit_credit', 'amount_drcr') then raise exception 'BAD_VALUE: pick how amounts are laid out' using errcode = 'P0001'; end if;
  foreach k in array array['date_col'] || case m->>'amount_mode' when 'signed' then array['amount_col'] when 'debit_credit' then array['debit_col', 'credit_col'] else array['amount_col', 'drcr_col'] end loop
    if m->>k is null or m->>k !~ '^[0-9]{1,3}$' then raise exception 'BAD_VALUE: pick the % column', k using errcode = 'P0001'; end if;
  end loop;
  if jsonb_typeof(m->'ref_cols') is distinct from 'array' or jsonb_array_length(m->'ref_cols') > 6 then raise exception 'BAD_VALUE: pick the reference column(s), at most 6' using errcode = 'P0001'; end if;
  for c in select * from jsonb_array_elements(m->'ref_cols') loop
    if c#>>'{}' !~ '^[0-9]{1,3}$' then raise exception 'BAD_VALUE: a reference column is not a number' using errcode = 'P0001'; end if;
  end loop;
  foreach k in array array['payer_col', 'bank_ref_col'] loop
    if m->>k is not null and m->>k !~ '^[0-9]{1,3}$' then raise exception 'BAD_VALUE: % must be a column number or empty', k using errcode = 'P0001'; end if;
  end loop;
  if length(m::text) > 2000 then raise exception 'TOO_LONG: that mapping is too big' using errcode = 'P0001'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_org::text || nm, 7));
  select coalesce(max(version), 0) + 1 into v from statement_mappings where org_id = p_org and name = nm;
  insert into statement_mappings(id, org_id, name, version, mapping) values (mid, p_org, nm, v, m);
  return jsonb_build_object('mapping_id', mid, 'name', nm, 'version', v);
end $$;

-- the lines as they will be stored (masked, fingerprinted, numbered), computed once for check and import
create or replace function public.stmt_fp_rows(p_org uuid, p_account text, p_lines jsonb)
returns table(row_no int, line_date date, cents bigint, ref_text text, payer_text text, bank_ref text, fp text, occ int)
language plpgsql security definer set search_path = public, pg_temp as $$
declare x jsonb; i int := 0;
begin
  if jsonb_typeof(p_lines) is distinct from 'array' then raise exception 'BAD_VALUE: no lines to import' using errcode = 'P0001'; end if;
  if jsonb_array_length(p_lines) > 20000 then raise exception 'TOO_LONG: up to 20,000 lines at a time' using errcode = 'P0001'; end if;
  create temp table if not exists _stmt_raw(row_no int, line_date date, cents bigint, ref_text text, payer_text text, bank_ref text) on commit drop;
  delete from _stmt_raw where true;
  for x in select * from jsonb_array_elements(p_lines) loop
    i := i + 1;
    if x->>'date' is null or x->>'date' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then raise exception 'BAD_VALUE: line % has no valid date (the browser sends yyyy-mm-dd)', i using errcode = 'P0001'; end if;
    if x->>'cents' is null or x->>'cents' !~ '^-?[0-9]{1,12}$' then raise exception 'BAD_VALUE: line % has no valid amount (whole cents)', i using errcode = 'P0001'; end if;
    insert into _stmt_raw values (coalesce(nullif(x->>'row', '')::int, i), (x->>'date')::date, (x->>'cents')::bigint,
      nullif(left(public.stmt_mask_digits(trim(coalesce(x->>'ref', ''))), 400), ''), nullif(left(public.stmt_mask_digits(trim(coalesce(x->>'payer', ''))), 120), ''),
      nullif(left(public.stmt_mask_digits(trim(coalesce(x->>'bank_ref', ''))), 120), ''));
  end loop;
  return query
    select r.row_no, r.line_date, r.cents, r.ref_text, r.payer_text, r.bank_ref, f.fp, (row_number() over (partition by f.fp order by r.row_no))::int
      from _stmt_raw r, lateral (select public.stmt_fp(p_org, p_account, r.line_date, r.cents, public.stmt_norm_ref(r.ref_text), r.bank_ref) as fp) f
     where r.cents <> 0;
end $$;

-- "will this file add anything?": counts only, writes nothing (the upload screen shows it before the person presses Import)
create or replace function public.stmt_check(p_org uuid, p_account text, p_lines jsonb) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare today date := stmt_gate(p_org); r jsonb;
begin
  if nullif(trim(coalesce(p_account, '')), '') is null then raise exception 'BAD_VALUE: give the account a label' using errcode = 'P0001'; end if;
  select jsonb_build_object('lines', count(*), 'known', count(*) filter (where exists (select 1 from statement_fingerprints f where f.org_id = p_org and f.fp = x.fp and f.occ = x.occ)),
         'new', count(*) filter (where not exists (select 1 from statement_fingerprints f where f.org_id = p_org and f.fp = x.fp and f.occ = x.occ)),
         'from', min(x.line_date), 'to', max(x.line_date),
         'credits_cents', coalesce(sum(x.cents) filter (where x.cents > 0), 0), 'debits_cents', coalesce(-sum(x.cents) filter (where x.cents < 0), 0))
    into r from stmt_fp_rows(p_org, p_account, p_lines) x;
  return r;
end $$;

-- ---------------------------------------------------------------------------------------------------
-- 4. one confirmed match: the payment, the match record, the payer link, the line removed
-- ---------------------------------------------------------------------------------------------------
create or replace function public.stmt_apply_match(p_org uuid, p_line uuid, p_ids uuid[], p_rule text, p_auto boolean, p_remember boolean, p_today date) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare ln statement_lines; res jsonb; hh uuid; pk text; mid uuid := gen_random_uuid();
begin
  select * into ln from statement_lines where id = p_line and org_id = p_org for update;
  if not found then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  if ln.cents <= 0 then raise exception 'NOT_ALLOWED: only money received can be matched to an invoice' using errcode = '42501'; end if;
  if coalesce(cardinality(p_ids), 0) = 0 then raise exception 'BAD_VALUE: choose the invoice this payment is for' using errcode = 'P0001'; end if;
  res := centre_record_payment(p_org, null, 'bank', ln.cents, ln.line_date, ln.bank_ref, p_ids, null, 'Matched from a bank statement');
  hh := (res->>'household_id')::uuid;
  pk := stmt_norm_payer(ln.payer_text);
  insert into statement_matches(id, org_id, batch_id, fp, occ, line_date, cents, kind, rule, household_id, payment_id, auto, confirmed_by)
  values (mid, p_org, ln.batch_id, ln.fp, ln.occ, ln.line_date, ln.cents, 'invoice', p_rule, hh, (res->>'payment_id')::uuid, p_auto, auth.uid());
  if pk <> '' and (p_remember or (p_auto and p_rule = 'payer_link')) then
    insert into statement_payer_links(org_id, payer_key, household_id, times_used, last_used) values (p_org, left(pk, 120), hh, 1, p_today)
    on conflict (org_id, payer_key) do update set household_id = excluded.household_id, times_used = statement_payer_links.times_used + 1, last_used = excluded.last_used;
  end if;
  delete from statement_lines where id = ln.id and org_id = p_org;
  return res || jsonb_build_object('match_id', mid, 'rule', p_rule, 'auto', p_auto);
end $$;

-- ---------------------------------------------------------------------------------------------------
-- 5. THE RULES. Runs over a batch (or every line waiting in the queue) and settles what it can.
-- ---------------------------------------------------------------------------------------------------
create or replace function public.stmt_run_rules(p_org uuid, p_today date, p_batch uuid default null) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare s jsonb := org_settings_on(p_org, p_today); auto text := coalesce(s#>>'{payments,statement,auto_confirm}', 'exact_only');
  wb int := coalesce((s#>>'{payments,statement,window_before_days}')::int, 7); wa int := coalesce((s#>>'{payments,statement,window_after_days}')::int, 90);
  ln statement_lines; o record; lk statement_payer_links; pk text; rn text; ids uuid[]; bals bigint[]; cnt int; tot bigint; list text; sub jsonb; hhs uuid[];
  r_rule text; r_exact boolean; r_ids uuid[]; r_hh uuid; r_reason text; res jsonb; a jsonb; n_auto int := 0; n_review int := 0; amt text;
begin
  create temp table if not exists _stmt_open(invoice_id uuid, number_text text, pat text, hid uuid, issue_date date, due_date date, bal bigint) on commit drop;
  delete from _stmt_open where true;
  insert into _stmt_open
    select b.invoice_id, i.number_text, stmt_number_pattern(i.number_text), centre_invoice_household(i.id), i.issue_date, i.due_date, b.balance_cents
      from centre_balance_rows(p_org, array(select id from centre_invoices where org_id = p_org and status = 'issued' and kind <> 'credit_note')) b
      join centre_invoices i on i.id = b.invoice_id and i.org_id = p_org;
  for ln in select * from statement_lines where org_id = p_org and (p_batch is null or batch_id = p_batch) order by line_date, row_no, id loop
    r_rule := null; r_exact := false; r_ids := '{}'; r_hh := null; r_reason := null; lk := null;
    pk := stmt_norm_payer(ln.payer_text); rn := lower(coalesce(ln.ref_text, '')); amt := centre_fmt_money(abs(ln.cents));
    <<d>> begin
      if ln.cents < 0 then r_reason := 'Money out, so it is never matched automatically. Mark it "not ours" unless it is a refund.'; exit d; end if;
      if ln.line_date > p_today then r_reason := 'Dated in the future: wait until that day.'; exit d; end if;
      if ln.line_date < p_today - 1825 then r_reason := 'Too old to record (over 5 years).'; exit d; end if;
      -- A: the invoice number is in the reference
      select array_agg(x.invoice_id order by x.number_text), count(*) into ids, cnt from _stmt_open x where rn ~ x.pat;
      if cnt >= 2 then
        select string_agg(x.number_text, ', ' order by x.number_text), coalesce(sum(x.bal), 0) into list, tot from _stmt_open x where x.invoice_id = any(ids);
        r_rule := 'household_total'; r_ids := ids; r_exact := (tot = ln.cents);      -- two numbers: a suggestion, never automatic
        r_reason := 'More than one invoice number found (' || list || ')' || case when tot = ln.cents then ', and together they come to exactly ' || amt || '. Check and confirm.' else '. Choose which one this is for.' end; exit d;
      elsif cnt = 1 then
        select * into o from _stmt_open x where x.invoice_id = ids[1];
        r_rule := 'invoice_no'; r_ids := ids; r_hh := o.hid;
        if o.bal = 0 then r_reason := o.number_text || ' found, but it is already paid.';
        elsif ln.line_date < o.issue_date - wb or ln.line_date > coalesce(o.due_date, o.issue_date) + wa then
          r_reason := o.number_text || ' found, but the date is outside the allowed window (' || wb || ' days before it was issued to ' || wa || ' days after it was due).';
        elsif ln.cents = o.bal then r_exact := true; r_reason := o.number_text || ' found, exact amount.';
        elsif ln.cents < o.bal then r_reason := o.number_text || ' found, but ' || centre_fmt_money(o.bal - ln.cents) || ' short.';
        else r_reason := o.number_text || ' found, but ' || centre_fmt_money(ln.cents - o.bal) || ' over.'; end if;
        exit d;
      end if;
      -- B: a remembered payer
      if pk <> '' then select * into lk from statement_payer_links where org_id = p_org and payer_key = left(pk, 120); end if;
      if lk.id is not null then
        r_hh := lk.household_id;
        select array_agg(x.invoice_id order by x.issue_date, x.number_text), count(*) into ids, cnt from _stmt_open x
          where x.hid = lk.household_id and x.bal = ln.cents and ln.line_date between x.issue_date - wb and coalesce(x.due_date, x.issue_date) + wa;
        if cnt = 1 then r_rule := 'payer_link'; r_exact := true; r_ids := ids; r_reason := 'Known payer, exact amount.'; exit d;
        elsif cnt >= 2 then r_rule := 'payer_link'; r_ids := ids; r_reason := 'Known payer, but ' || cnt || ' invoices of this family are exactly ' || amt || '. Choose one.'; exit d; end if;
        select array_agg(x.invoice_id order by x.issue_date, x.number_text), array_agg(x.bal order by x.issue_date, x.number_text), count(*) into ids, bals, cnt from _stmt_open x
          where x.hid = lk.household_id and x.bal > 0 and ln.line_date between x.issue_date - wb and coalesce(x.due_date, x.issue_date) + wa;
        if cnt = 1 then
          r_rule := 'payer_link'; r_ids := ids;
          r_reason := 'Known payer. Their open invoice is ' || centre_fmt_money(bals[1]) || ', this is ' || case when ln.cents < bals[1] then centre_fmt_money(bals[1] - ln.cents) || ' short.' else centre_fmt_money(ln.cents - bals[1]) || ' over.' end; exit d;
        elsif cnt > 10 then r_reason := 'Known payer, but the family has more than 10 open invoices. Choose by hand.'; exit d;
        elsif cnt >= 2 then
          sub := stmt_subsets(ids, bals, ln.cents);
          if (sub->>'count')::int = 1 then
            r_rule := 'household_total'; r_exact := true; r_ids := array(select (e#>>'{}')::uuid from jsonb_array_elements(sub->'ids') e);
            r_reason := 'Known payer. This equals ' || cardinality(r_ids) || ' of the family''s open invoices. Check and confirm.'; exit d;
          elsif (sub->>'count')::int > 1 then r_reason := 'Known payer, but several combinations of the family''s invoices come to ' || amt || '. Choose by hand.'; exit d; end if;
        end if;
        r_reason := 'Known payer, but no open invoice of exactly ' || amt || '.'; exit d;
      end if;
      -- C: amount only (suggestion, never automatic)
      select array_agg(x.invoice_id order by x.issue_date, x.number_text), count(*) into ids, cnt from _stmt_open x
        where x.bal = ln.cents and ln.line_date between x.issue_date - wb and coalesce(x.due_date, x.issue_date) + wa;
      if cnt = 1 then
        select x.hid into r_hh from _stmt_open x where x.invoice_id = ids[1];
        r_rule := 'amount_only'; r_exact := true; r_ids := ids;
        r_reason := 'Only one invoice is owed for exactly ' || amt || ', but there is no invoice number or known payer. Check and confirm.'; exit d;
      elsif cnt >= 2 then r_rule := 'amount_only'; r_ids := ids[1:10]; r_reason := cnt || ' invoices are owed for exactly ' || amt || '. Choose which family this is.'; exit d; end if;
      -- D: everything one family owes
      select array_agg(g.hid), count(*) into hhs, cnt from (
        select x.hid from _stmt_open x where x.bal > 0 and x.hid is not null and ln.line_date between x.issue_date - wb and coalesce(x.due_date, x.issue_date) + wa
         group by x.hid having count(*) between 2 and 10 and sum(x.bal) = ln.cents) g;
      if cnt = 1 then
        r_rule := 'household_total'; r_exact := true; r_hh := hhs[1];
        select array_agg(x.invoice_id order by x.issue_date, x.number_text) into r_ids from _stmt_open x where x.hid = hhs[1] and x.bal > 0 and ln.line_date between x.issue_date - wb and coalesce(x.due_date, x.issue_date) + wa;
        r_reason := 'This equals everything one family owes (' || cardinality(r_ids) || ' invoices). Check and confirm.'; exit d;
      elsif cnt >= 2 then r_reason := 'More than one family owes a total of exactly ' || amt || '. Choose which.'; exit d; end if;
      select count(*) into cnt from _stmt_open x where x.bal > 0;
      r_reason := case when cnt = 0 then 'No open invoice yet.' else 'No invoice matches ' || amt || '. Add the invoice number to the reference, or choose the invoice.' end;
    end d;
    if r_exact and r_rule in ('invoice_no', 'payer_link') and auto = 'exact_only' then
      begin
        res := stmt_apply_match(p_org, ln.id, r_ids, r_rule, true, false, p_today);
        for a in select * from jsonb_array_elements(res->'allocated') loop
          update _stmt_open set bal = (a->>'balance_after_cents')::bigint where invoice_id = (a->>'invoice_id')::uuid;
        end loop;
        n_auto := n_auto + 1;
        continue;
      exception when others then
        r_reason := 'Could not be recorded automatically: ' || regexp_replace(sqlerrm, '^[A-Z_]+: ', '');
        r_exact := false;
      end;
    elsif r_exact and r_rule in ('invoice_no', 'payer_link') then
      r_reason := r_reason || ' Auto-confirm is off, so a person confirms.';
    end if;
    update statement_lines set sugg_rule = r_rule, sugg_exact = r_exact, sugg_invoice_ids = coalesce(r_ids, '{}'), sugg_household = r_hh, reason = r_reason
     where id = ln.id and org_id = p_org;
    n_review := n_review + 1;
  end loop;
  return jsonb_build_object('auto', n_auto, 'review', n_review);
end $$;

-- ---------------------------------------------------------------------------------------------------
-- 6. IMPORT (the browser sends the parsed lines) and RE-RUN the rules on what is waiting
-- ---------------------------------------------------------------------------------------------------
create or replace function public.stmt_purge(p_org uuid, p_today date) returns int
language plpgsql security definer set search_path = public as $$
declare n int;
begin delete from statement_lines where org_id = p_org and purge_after < p_today; get diagnostics n = row_count; return n; end $$;

create or replace function public.stmt_import(p_org uuid, p_account text, p_mapping uuid, p_lines jsonb) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare today date := stmt_gate(p_org); acct text := nullif(trim(coalesce(p_account, '')), ''); bid uuid := gen_random_uuid(); v_all int; v_new int; v_skip int; run jsonb;
  d1 date; d2 date; purged int;
begin
  if acct is null or length(acct) > 40 then raise exception 'BAD_VALUE: give the account a label (up to 40 characters, for example "Main account")' using errcode = 'P0001'; end if;
  if p_mapping is not null and not exists (select 1 from statement_mappings where id = p_mapping and org_id = p_org) then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_org::text, 9));
  purged := stmt_purge(p_org, today);
  create temp table if not exists _stmt_in(row_no int, line_date date, cents bigint, ref_text text, payer_text text, bank_ref text, fp text, occ int) on commit drop;
  delete from _stmt_in where true;
  insert into _stmt_in select * from stmt_fp_rows(p_org, acct, p_lines);
  select count(*), min(line_date), max(line_date) into v_all, d1, d2 from _stmt_in;
  v_skip := jsonb_array_length(p_lines) - v_all;
  insert into statement_batches(id, org_id, account_label, mapping_id, date_from, date_to, n_lines) values (bid, p_org, acct, p_mapping, d1, d2, jsonb_array_length(p_lines));
  with ins as (insert into statement_fingerprints(org_id, fp, occ, batch_id, first_seen) select p_org, i.fp, i.occ, bid, today from _stmt_in i on conflict do nothing returning fp, occ)
  insert into statement_lines(org_id, batch_id, row_no, line_date, cents, ref_text, payer_text, bank_ref, fp, occ, purge_after)
  select p_org, bid, i.row_no, i.line_date, i.cents, i.ref_text, i.payer_text, i.bank_ref, i.fp, i.occ, today + 60 from _stmt_in i join ins using (fp, occ);
  get diagnostics v_new = row_count;
  run := stmt_run_rules(p_org, today, bid);
  update statement_batches set n_new = v_new, n_duplicate = v_all - v_new, n_skipped = v_skip, n_auto = (run->>'auto')::int, n_review = (run->>'review')::int where id = bid;
  insert into audit_log(org_id, actor, action, table_name, row_id, before, after)
  values (p_org, auth.uid(), 'statement_import', 'statement_batches', bid::text, null,
          jsonb_build_object('lines', v_all, 'new', v_new, 'duplicates', v_all - v_new, 'skipped_zero', v_skip, 'auto_matched', (run->>'auto')::int, 'to_review', (run->>'review')::int, 'purged', purged));
  return jsonb_build_object('batch_id', bid, 'lines', v_all, 'new', v_new, 'duplicates', v_all - v_new, 'skipped', v_skip, 'auto_matched', (run->>'auto')::int, 'to_review', (run->>'review')::int);
end $$;

create or replace function public.stmt_rematch(p_org uuid) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare today date := stmt_gate(p_org); run jsonb;
begin
  perform pg_advisory_xact_lock(hashtextextended(p_org::text, 9));
  perform stmt_purge(p_org, today);
  run := stmt_run_rules(p_org, today, null);
  insert into audit_log(org_id, actor, action, table_name, row_id, before, after)
  values (p_org, auth.uid(), 'statement_rematch', 'statement_lines', p_org::text, null, jsonb_build_object('auto_matched', (run->>'auto')::int, 'to_review', (run->>'review')::int));
  return jsonb_build_object('auto_matched', (run->>'auto')::int, 'to_review', (run->>'review')::int);
end $$;

-- ---------------------------------------------------------------------------------------------------
-- 7. WHAT A PERSON DOES: confirm, "not ours", undo, forget a payer
-- ---------------------------------------------------------------------------------------------------
create or replace function public.stmt_confirm(p_line uuid, p_invoice_ids uuid[] default null, p_remember boolean default true) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare org uuid; today date; ln statement_lines; ids uuid[]; rule text; res jsonb;
begin
  if auth.uid() is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  select org_id into org from statement_lines where id = p_line;
  if org is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  today := stmt_gate(org);
  perform pg_advisory_xact_lock(hashtextextended(p_line::text, 11));
  select * into ln from statement_lines where id = p_line and org_id = org for update;
  if not found then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;      -- already handled (a second press)
  ids := coalesce(nullif(p_invoice_ids, '{}'), ln.sugg_invoice_ids);
  if coalesce(cardinality(ids), 0) = 0 then raise exception 'BAD_VALUE: choose the invoice this payment is for' using errcode = 'P0001'; end if;
  rule := case when ln.sugg_rule is not null and (select array(select unnest(ids) order by 1)) = (select array(select unnest(ln.sugg_invoice_ids) order by 1)) then ln.sugg_rule else 'manual' end;
  res := stmt_apply_match(org, ln.id, ids, rule, false, coalesce(p_remember, false), today);
  perform stmt_purge(org, today);
  insert into audit_log(org_id, actor, action, table_name, row_id, before, after)
  values (org, auth.uid(), 'statement_confirm', 'statement_matches', res->>'match_id', null, jsonb_build_object('rule', rule, 'amount_cents', ln.cents, 'payment_id', res->>'payment_id'));
  return res;
end $$;

create or replace function public.stmt_ignore(p_line uuid) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare org uuid; today date; ln statement_lines; mid uuid := gen_random_uuid();
begin
  if auth.uid() is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  select org_id into org from statement_lines where id = p_line;
  if org is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  today := stmt_gate(org);
  select * into ln from statement_lines where id = p_line and org_id = org for update;
  if not found then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  insert into statement_matches(id, org_id, batch_id, fp, occ, line_date, cents, kind, rule, auto, confirmed_by) values (mid, org, ln.batch_id, ln.fp, ln.occ, ln.line_date, ln.cents, 'ignored', 'manual', false, auth.uid());
  delete from statement_lines where id = ln.id and org_id = org;
  return jsonb_build_object('match_id', mid);
end $$;

-- every line of money OUT that is still waiting becomes "not ours" at once
create or replace function public.stmt_ignore_out(p_org uuid) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare today date := stmt_gate(p_org); n int;
begin
  with gone as (delete from statement_lines where org_id = p_org and cents < 0 returning *)
  insert into statement_matches(org_id, batch_id, fp, occ, line_date, cents, kind, rule, auto, confirmed_by)
  select p_org, batch_id, fp, occ, line_date, cents, 'ignored', 'manual', false, auth.uid() from gone;
  get diagnostics n = row_count;
  insert into audit_log(org_id, actor, action, table_name, row_id, before, after) values (p_org, auth.uid(), 'statement_ignore_out', 'statement_matches', p_org::text, null, jsonb_build_object('lines', n));
  return jsonb_build_object('ignored', n);
end $$;

create or replace function public.stmt_undo(p_match uuid, p_reason text) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare org uuid; today date; m statement_matches; why text := nullif(trim(coalesce(p_reason, '')), ''); rev jsonb; already boolean := false;
begin
  if auth.uid() is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  select org_id into org from statement_matches where id = p_match;
  if org is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  today := stmt_gate(org);
  select * into m from statement_matches where id = p_match and org_id = org for update;
  if m.reversed_at is not null then return jsonb_build_object('already', true); end if;
  if why is null then raise exception 'REASON_REQUIRED: say why you are undoing this match' using errcode = 'P0001'; end if;
  if length(why) > 300 then raise exception 'TOO_LONG: keep the reason under 300 characters' using errcode = 'P0001'; end if;
  if m.kind = 'invoice' then
    if exists (select 1 from centre_payments where reverses_payment_id = m.payment_id and org_id = org) then already := true;          -- reversed on the Invoices screen already
    else rev := centre_reverse_payment(m.payment_id, why); end if;
  end if;
  update statement_matches set reversed_at = now(), reversed_by = auth.uid(), reverse_reason = why where id = m.id and org_id = org;
  insert into statement_lines(org_id, batch_id, row_no, line_date, cents, fp, occ, stub, reason, purge_after)
  values (org, m.batch_id, 0, m.line_date, m.cents, m.fp, m.occ, true, 'Put back after an undo: only the date and amount are kept.', today + 60);
  perform stmt_purge(org, today);
  insert into audit_log(org_id, actor, action, table_name, row_id, before, after)
  values (org, auth.uid(), 'statement_undo', 'statement_matches', m.id::text, null, jsonb_build_object('kind', m.kind, 'amount_cents', m.cents, 'payment_already_reversed', already));
  return jsonb_build_object('match_id', m.id, 'payment_already_reversed', already, 'reversal', rev);
end $$;

create or replace function public.stmt_forget_payer(p_link uuid) returns jsonb
language plpgsql security definer set search_path = public, pg_temp as $$
declare org uuid;
begin
  if auth.uid() is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  select org_id into org from statement_payer_links where id = p_link;
  if org is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  perform stmt_gate(org);
  delete from statement_payer_links where id = p_link and org_id = org;
  return jsonb_build_object('forgotten', true);
end $$;

-- ---------------------------------------------------------------------------------------------------
-- 8. WHAT THE SCREEN READS (one call)
-- ---------------------------------------------------------------------------------------------------
create or replace function public.stmt_queue(p_org uuid) returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare today date := stmt_gate(p_org); s jsonb := org_settings_on(p_org, today);
begin
  return jsonb_build_object(
    'settings', jsonb_build_object('auto_confirm', coalesce(s#>>'{payments,statement,auto_confirm}', 'exact_only'),
      'window_before_days', coalesce((s#>>'{payments,statement,window_before_days}')::int, 7), 'window_after_days', coalesce((s#>>'{payments,statement,window_after_days}')::int, 90),
      'partial_payments', coalesce((s#>>'{payments,partial_payments}')::boolean, true), 'overpayments', centre_overpay_mode(s)),
    'review_total', (select count(*) from statement_lines where org_id = p_org),
    'review', coalesce((select jsonb_agg(r order by r->>'line_date', (r->>'row_no')::int) from (
        select jsonb_build_object('id', l.id, 'line_date', l.line_date, 'row_no', l.row_no, 'cents', l.cents, 'ref_text', l.ref_text, 'payer_text', l.payer_text, 'bank_ref', l.bank_ref, 'stub', l.stub,
          'rule', l.sugg_rule, 'exact', l.sugg_exact, 'reason', l.reason, 'purge_after', l.purge_after,
          'household', (select h.name from households h where h.id = l.sugg_household and h.org_id = p_org),
          'invoices', coalesce((select jsonb_agg(jsonb_build_object('id', i.id, 'number', i.number_text, 'balance_cents', b.balance_cents, 'due_date', i.due_date) order by i.issue_date, i.number_seq)
                                 from centre_invoices i, lateral centre_balance_rows(p_org, array[i.id]) b where i.org_id = p_org and i.id = any(l.sugg_invoice_ids)), '[]'::jsonb)) r
          from statement_lines l where l.org_id = p_org order by l.line_date, l.row_no limit 500) q), '[]'::jsonb),
    'matched', coalesce((select jsonb_agg(jsonb_build_object('id', m.id, 'line_date', m.line_date, 'cents', m.cents, 'kind', m.kind, 'rule', m.rule, 'auto', m.auto, 'confirmed_at', m.confirmed_at,
          'payment_id', m.payment_id, 'reversed', m.reversed_at is not null,
          'payment_reversed', m.payment_id is not null and exists (select 1 from centre_payments x where x.reverses_payment_id = m.payment_id and x.org_id = p_org),
          'household', (select h.name from households h where h.id = m.household_id and h.org_id = p_org),
          'invoices', coalesce((select jsonb_agg(i.number_text order by i.issue_date, i.number_seq) from centre_payment_allocations a join centre_invoices i on i.id = a.invoice_id and i.org_id = p_org
                                 where a.payment_id = m.payment_id and a.org_id = p_org and a.cents > 0), '[]'::jsonb)) order by m.confirmed_at desc)
        from (select * from statement_matches where org_id = p_org order by confirmed_at desc limit 200) m), '[]'::jsonb),
    'batches', coalesce((select jsonb_agg(jsonb_build_object('id', b.id, 'account', b.account_label, 'date_from', b.date_from, 'date_to', b.date_to, 'lines', b.n_lines, 'new', b.n_new,
          'duplicates', b.n_duplicate, 'skipped', b.n_skipped, 'auto', b.n_auto, 'review', b.n_review, 'imported_at', b.imported_at) order by b.imported_at desc)
        from (select * from statement_batches where org_id = p_org order by imported_at desc limit 50) b), '[]'::jsonb),
    'payers', coalesce((select jsonb_agg(jsonb_build_object('id', p.id, 'payer', p.payer_key, 'household', h.name, 'times_used', p.times_used, 'last_used', p.last_used) order by p.last_used desc)
        from statement_payer_links p join households h on h.id = p.household_id and h.org_id = p_org where p.org_id = p_org), '[]'::jsonb),
    'mappings', coalesce((select jsonb_agg(jsonb_build_object('id', x.id, 'name', x.name, 'version', x.version, 'mapping', x.mapping) order by x.name)
        from (select distinct on (name) * from statement_mappings where org_id = p_org order by name, version desc) x), '[]'::jsonb),
    'open_invoices', coalesce((select jsonb_agg(jsonb_build_object('id', i.id, 'number', i.number_text, 'household', h.name, 'balance_cents', b.balance_cents, 'due_date', i.due_date) order by i.issue_date, i.number_seq)
        from centre_invoices i left join households h on h.id = centre_invoice_household(i.id) and h.org_id = p_org,
             lateral centre_balance_rows(p_org, array[i.id]) b
        where i.org_id = p_org and i.status = 'issued' and i.kind <> 'credit_note' and b.balance_cents > 0), '[]'::jsonb));
end $$;

-- ---------------------------------------------------------------------------------------------------
-- 9. the settings check learns the three statement options (the 1-argument base check from money_settings stays as it is)
-- ---------------------------------------------------------------------------------------------------
create or replace function public.org_validate_settings(p_org uuid, s jsonb) returns void language plpgsql stable security definer set search_path = public as $$
declare st jsonb; v jsonb;
begin
  perform public.org_validate_settings(s);
  if s #>> '{billing,deposit,refund_approved_by}' = 'four_eyes' then
    st := case when p_org is null then jsonb_build_object('owner', true, 'deposit', false, 'credit', false) else public.org_four_eyes_status(p_org) end;
    if not (coalesce((st->>'owner')::boolean, false) and coalesce((st->>'deposit')::boolean, false) and coalesce((st->>'credit')::boolean, false)) then
      raise exception 'FOUR_EYES_UNAVAILABLE: "someone other than the person who asked" needs a second approver: the owner, a staff member who issues invoices (for deposit refunds) and a staff member who records payments (for credit refunds), all active. Add them first, or pick another approver.' using errcode = '42501';
    end if;
  end if;
  -- T34: bank statement matching. Every key is optional (settings saved before this stay valid); a key that is present must be right.
  if s#>>'{payments,statement,auto_confirm}' is not null and s#>>'{payments,statement,auto_confirm}' not in ('exact_only','never') then raise exception 'Unknown statement auto-confirm setting'; end if;
  if s#>>'{payments,statement_bank}' is not null and s#>>'{payments,statement_bank}' not in ('DBS','OCBC','UOB','custom') then raise exception 'Unknown bank for statement matching'; end if;
  v := s #> '{payments,statement,window_before_days}';
  if v is not null and jsonb_typeof(v) <> 'null' and not (case when jsonb_typeof(v) = 'number' and v::text ~ '^[0-9]{1,3}$' then (v#>>'{}')::int between 0 and 30 else false end) then
    raise exception 'Statement matching window before the invoice date must be 0-30 days'; end if;
  v := s #> '{payments,statement,window_after_days}';
  if v is not null and jsonb_typeof(v) <> 'null' and not (case when jsonb_typeof(v) = 'number' and v::text ~ '^[0-9]{1,3}$' then (v#>>'{}')::int between 0 and 365 else false end) then
    raise exception 'Statement matching window after the due date must be 0-365 days'; end if;
end $$;

-- ---------------------------------------------------------------------------------------------------
-- 10. who can call what (the SQL helpers and rule functions are internal: server only)
-- ---------------------------------------------------------------------------------------------------
revoke all on function public.stmt_audit() from public, anon, authenticated;
revoke all on function public.stmt_mask_digits(text), public.stmt_norm_payer(text), public.stmt_norm_ref(text), public.stmt_number_pattern(text),
  public.stmt_fp(uuid, text, date, bigint, text, text), public.stmt_subsets(uuid[], bigint[], bigint),
  public.stmt_fp_rows(uuid, text, jsonb), public.stmt_apply_match(uuid, uuid, uuid[], text, boolean, boolean, date), public.stmt_run_rules(uuid, date, uuid),
  public.stmt_purge(uuid, date), public.stmt_gate(uuid) from public, anon, authenticated;
grant execute on function public.stmt_mask_digits(text), public.stmt_norm_payer(text), public.stmt_norm_ref(text), public.stmt_number_pattern(text),
  public.stmt_fp(uuid, text, date, bigint, text, text), public.stmt_subsets(uuid[], bigint[], bigint) to service_role;
revoke all on function public.stmt_save_mapping(uuid, text, jsonb), public.stmt_check(uuid, text, jsonb), public.stmt_import(uuid, text, uuid, jsonb), public.stmt_rematch(uuid),
  public.stmt_confirm(uuid, uuid[], boolean), public.stmt_ignore(uuid), public.stmt_ignore_out(uuid), public.stmt_undo(uuid, text), public.stmt_forget_payer(uuid), public.stmt_queue(uuid) from public, anon;
grant execute on function public.stmt_save_mapping(uuid, text, jsonb), public.stmt_check(uuid, text, jsonb), public.stmt_import(uuid, text, uuid, jsonb), public.stmt_rematch(uuid),
  public.stmt_confirm(uuid, uuid[], boolean), public.stmt_ignore(uuid), public.stmt_ignore_out(uuid), public.stmt_undo(uuid, text), public.stmt_forget_payer(uuid), public.stmt_queue(uuid) to authenticated, service_role;

-- #####################################################################################################
-- ### PART 5 of 7 — invoice / receipt / reminder emails: queue, send log, caps, bounces
-- ### source branch: claude/t7-3-invoice-email   file: db/migration_invoice_email.sql   undo: db/migration_invoice_email_down.sql
-- ### (if an error appears, search this file for the nearest "### PART" line above the error line: that is the part that failed)
-- #####################################################################################################
-- =====================================================================================================
-- T7.3 — emailing invoices, receipts and overdue reminders to families (centre option)          undo: migration_invoice_email_down.sql
-- =====================================================================================================
-- Run order everywhere: org_foundation → billing → attendance → tutor_access → org_delete → function_lockdown → org_separation → staff_home → staff_students →
--   staff_attendance → staff_charges → staff_trials → staff_timetable → staff_slots → staff_reassign → reassign_link → tutor_schedule → money_settings →
--   centre_money → centre_invoice_run → centre_payments → payment_fix → invites → fee_050 → centre_billing_method → centre_billing_start → tutor_profile →
--   tutor_payout → payout_permission → centre_deposits → centre_refunds → centre_late_fees → centre_credit_undo → slot_changes → tutor_moves → invoice_email.
-- Needs migration_centre_payments.sql (share links, pay status), migration_centre_late_fees.sql (late-fee invoices), migration_staff_students.sql (guardians' emails)
-- and migration_tutor_moves.sql (the settings validator this file replaces). Run on the DEV project first. LIVE only when the owner says ship. Safe to run twice.
--
-- THE OWNER'S RULES (2026-11-27), all built:
--   * Email is a CENTRE OPTION. Default = OFF: invoices are shared by hand (WhatsApp / link) exactly as today. Nothing here changes a centre until it switches it on.
--   * email.mode  off | staff_send (a person with "Issue invoices" presses Send) | auto_on_issue (queued the moment the invoice is issued).
--   * What is sent: the invoice (a secure share link, no PDF), a receipt when a payment is recorded (email.receipts), an overdue reminder (email.reminders:
--     first reminder N days after the due date, repeat every R days, at most M), a notice when a late-fee invoice is issued (email.late_fee_notice).
--     Receipts, reminders and late-fee notices are automatic once their switch is on (that is what they are); the invoice itself follows email.mode.
--   * Who gets it: the family's guardians flagged billing_contact; if none is flagged, the family's FIRST guardian. Never a tutor.
--   * The wording: plain text from the centre's own template (email.templates.<kind>.subject / body) using a limited set of {fields}; blank = our default.
--   * Limits: Brevo's free plan allows 300 a day for the whole platform, so every centre has a daily cap and an hourly cap (email.daily_cap, email.per_hour) and
--     everything goes through a QUEUE ("12 queued, sends over 2 days"). The server (api/email-send.js, api/email-cron.js) also keeps to a platform-wide cap.
--   * A send log, append-only: who, when, the address MASKED (j***@g***.com), which template, the result. Retries: at most 3 attempts (15 min, 1 h, 6 h), then
--     the row is failed and stays failed. A bounce marks the guardian's address 'bad' (staff see it; nothing more is sent to it until the address is fixed).
--   * Tutors and parents have NO access to any of this. Solo organisations are refused. A voided, fully-credited or fully-paid invoice is never mailed, and a reminder
--     that is still queued when the invoice gets paid is cancelled before it goes (the check runs again at send time).
--   * PDPA: the queue and the log hold no address (the address is read from the guardian only at the moment of sending); the log keeps the masked form only.
--
-- WHAT IT ADDS
--   guardians.billing_contact / email_status ('ok' | 'bad') / email_bad_at         (editing a guardian's address clears 'bad')
--   email_queue         one row per message per recipient (state machine)          email_send_log   append-only history
--   triggers: invoice issued → queue the invoice / late-fee notice; payment recorded → queue the receipt (both only if the centre's settings say so)
--   staff functions (issue_invoices; reading also record_payments): email_enqueue, email_enqueue_unsent, email_queue_status, email_queue_list, email_queue_cancel,
--     email_log_list, email_household_contacts, email_set_billing_contacts, email_clear_bad, email_bad_list, email_reminder_preview
--   server-only functions (service role): email_claim, email_complete, email_mark_bounce, email_plan_reminders, email_platform_sent_24h
-- =====================================================================================================

-- ---------------------------------------------------------------------------------------------------
-- 1. billing contacts and bad addresses (on the guardians table)
-- ---------------------------------------------------------------------------------------------------
alter table public.guardians add column if not exists billing_contact boolean not null default false;
alter table public.guardians add column if not exists email_status text not null default 'ok';
alter table public.guardians add column if not exists email_bad_at timestamptz;
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'guardians_email_status_check') then
    alter table public.guardians add constraint guardians_email_status_check check (email_status in ('ok', 'bad'));
  end if;
end $$;

-- a new address starts clean: a bounce belongs to the old one
create or replace function public.guardians_email_reset() returns trigger
language plpgsql set search_path = public as $$
begin
  if new.email is distinct from old.email and new.email_status = 'bad' and old.email_status = 'bad' then
    new.email_status := 'ok'; new.email_bad_at := null;
  end if;
  return new;
end $$;
drop trigger if exists guardians_email_reset on public.guardians;
create trigger guardians_email_reset before update of email on public.guardians for each row execute function public.guardians_email_reset();

-- ---------------------------------------------------------------------------------------------------
-- 2. the queue and the send log (server-side tables: nobody reads or writes them from a browser; the screens use the functions below)
-- ---------------------------------------------------------------------------------------------------
create table if not exists public.email_queue (
  id            uuid primary key default gen_random_uuid(),
  org_id        uuid not null references public.organisations(id) on delete cascade,
  kind          text not null check (kind in ('invoice', 'receipt', 'reminder', 'late_fee')),
  invoice_id    uuid,
  payment_id    uuid,
  household_id  uuid not null,
  guardian_id   uuid references public.guardians(id) on delete set null,
  reminder_no   int check (reminder_no >= 1),
  status        text not null default 'queued' check (status in ('queued', 'sending', 'sent', 'failed', 'cancelled', 'skipped')),
  reason        text,                                                  -- a short code: why it was skipped / cancelled / failed (never an address)
  attempts      int not null default 0 check (attempts >= 0),
  not_before    timestamptz not null default now(),
  requested_by  uuid,                                                  -- the person who pressed Send; null = the system (automatic)
  requested_at  timestamptz not null default clock_timestamp(),     -- (not now(): messages queued in one call keep the order they were asked in)
  updated_at    timestamptz not null default now(),
  dedupe_key    text,
  unique (id, org_id),
  foreign key (invoice_id, org_id) references public.centre_invoices(id, org_id) on delete cascade,
  foreign key (payment_id, org_id) references public.centre_payments(id, org_id) on delete cascade,
  check ((kind = 'receipt') = (payment_id is not null)),
  check ((kind = 'receipt') = (invoice_id is null)),
  check ((kind = 'reminder') = (reminder_no is not null))
);
create index if not exists email_queue_due on public.email_queue(org_id, status, not_before);
create index if not exists email_queue_invoice on public.email_queue(invoice_id) where invoice_id is not null;
create index if not exists email_queue_guardian on public.email_queue(guardian_id) where guardian_id is not null;
-- the same message to the same person is queued once while it is waiting, being sent or sent (a failed / cancelled / skipped one may be tried again)
create unique index if not exists email_queue_dedupe on public.email_queue(dedupe_key) where dedupe_key is not null and status in ('queued', 'sending', 'sent');

create table if not exists public.email_send_log (
  id               bigint generated always as identity primary key,
  org_id           uuid not null references public.organisations(id) on delete cascade,
  queue_id         uuid,
  kind             text not null,
  invoice_id       uuid,
  guardian_id      uuid,
  to_masked        text,                                               -- j***@g***.com — the only form of the address that is ever kept
  template         text,                                               -- 'invoice' | 'receipt' | 'reminder' | 'late_fee', + ':custom' when the centre's own wording was used
  result           text not null check (result in ('sent', 'retry', 'failed', 'bounced', 'blocked_preview', 'skipped', 'cancelled')),
  detail           text,                                               -- a short code ('http_500', 'invalid_recipient', 'paid', 'no_email' ...)
  attempt          int,
  by_user          uuid,                                               -- who asked; null = automatic
  brevo_message_id text,
  at               timestamptz not null default now()
);
create index if not exists email_send_log_org on public.email_send_log(org_id, id desc);
create index if not exists email_send_log_message on public.email_send_log(brevo_message_id) where brevo_message_id is not null;
create index if not exists email_send_log_sent on public.email_send_log(org_id, at) where result = 'sent';

create or replace function public.email_log_guard() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'DELETE' and public.centre_money_deleting(old.org_id) then return old; end if;
  raise exception 'The email send log is append-only' using errcode = '42501';
end $$;
drop trigger if exists email_log_guard on public.email_send_log;
create trigger email_log_guard before update or delete on public.email_send_log for each row execute function public.email_log_guard();

create or replace function public.email_queue_guard() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if not exists (select 1 from organisations o where o.id = new.org_id and o.kind = 'centre') then
    raise exception 'Family emails are for centres only' using errcode = '42501';
  end if;
  return new;
end $$;
drop trigger if exists email_queue_guard on public.email_queue;
create trigger email_queue_guard before insert on public.email_queue for each row execute function public.email_queue_guard();

alter table public.email_queue enable row level security;
alter table public.email_send_log enable row level security;
revoke all on public.email_queue, public.email_send_log from anon, authenticated;       -- no policies on purpose: functions only
revoke all on function public.email_log_guard() from public, anon, authenticated;
revoke all on function public.email_queue_guard() from public, anon, authenticated;
revoke all on function public.guardians_email_reset() from public, anon, authenticated;

-- ---------------------------------------------------------------------------------------------------
-- 3. the settings validator (the tutor_moves one, plus the email options)
-- ---------------------------------------------------------------------------------------------------
create or replace function public.org_validate_settings(s jsonb) returns void language plpgsql immutable set search_path = public as $$
declare k text; v jsonb; r record; bs text; tp text;
begin
  if coalesce((s->>'schema_version')::int, 0) <> 1 then raise exception 'Unknown settings schema_version'; end if;
  foreach k in array array['profile','calendar','billing','invoicing','payments','lessons','tutor_pay','data'] loop
    if jsonb_typeof(s->k) is distinct from 'object' then raise exception 'Settings section "%" is missing', k; end if;
  end loop;
  if (s#>>'{profile,gst_registered}')::boolean and not ((s#>>'{profile,gst_rate_bp}')::int between 0 and 5000) then
    raise exception 'GST rate must be between 0%% and 50%%'; end if;
  if s#>>'{billing,model}' not in ('prepaid_packages','fixed_in_advance','postpaid_lessons','pay_per_lesson') then
    raise exception 'Unknown billing model'; end if;
  if s#>>'{tutor_pay,mode}' not in ('off','report','full') then raise exception 'Unknown tutor pay mode'; end if;
  if s#>>'{tutor_pay,payable_when}' not in ('taught','parent_paid') then raise exception 'Unknown payable rule'; end if;
  if s#>>'{invoicing,grouping}' not in ('family','student') then raise exception 'Unknown invoice grouping'; end if;
  if s#>>'{lessons,attendance_by}' not in ('tutor','admin') then raise exception 'Unknown attendance setting'; end if;
  if s#>>'{lessons,cancellations_marked_by}' not in ('admin','tutor') then raise exception 'Unknown cancellation setting'; end if;
  if s#>>'{lessons,compensation_entered_by}' not in ('admin','tutor') then raise exception 'Unknown compensation setting'; end if;
  if s#>>'{lessons,trials_flagged_by}' not in ('admin','tutor') then raise exception 'Unknown trial setting'; end if;
  if s#>>'{lessons,attendance_window_days}' is not null and (s#>>'{lessons,attendance_window_days}' !~ '^[0-9]{1,3}$'
     or (s#>>'{lessons,attendance_window_days}')::int not between 1 and 60) then raise exception 'Attendance window must be 1-60 days'; end if;
  if not (s#>'{payments,modes}' ?| array['manual_paynow','statement_matching','hitpay','stripe']) then
    raise exception 'Pick at least one way for parents to pay'; end if;
  -- T4 S0 (centre money options). Every new key is optional, so settings saved before this migration stay valid;
  -- a key that is present must be right. assets/js/org-settings.js holds the labels and defaults (tests/org-settings.test.js compares the enums).
  if s#>>'{tutor_pay,rate_model}' is not null and s#>>'{tutor_pay,rate_model}' not in ('per_lesson','per_hour','per_student_lesson','monthly_fixed','percent_of_fee') then raise exception 'Unknown tutor pay rate'; end if;
  if s#>>'{tutor_pay,percent_base}' is not null and s#>>'{tutor_pay,percent_base}' not in ('billed_after_discounts','list_price') then raise exception 'Unknown percentage pay base'; end if;
  if s#>>'{tutor_pay,part_payments}' is not null and s#>>'{tutor_pay,part_payments}' not in ('after_full','pro_rata') then raise exception 'Unknown part-payment pay rule'; end if;
  if s#>>'{tutor_pay,cancelled_lessons}' is not null and s#>>'{tutor_pay,cancelled_lessons}' not in ('pay_if_charged','pay_rate','pay_nothing') then raise exception 'Unknown cancelled-lesson pay rule'; end if;
  if s#>>'{tutor_pay,group_count}' is not null and s#>>'{tutor_pay,group_count}' not in ('attended','enrolled') then raise exception 'Unknown group pay count'; end if;
  if s#>>'{billing,deposit,mode}' is not null and s#>>'{billing,deposit,mode}' not in ('none','fixed','percent_first_month') then raise exception 'Unknown deposit mode'; end if;
  if s#>>'{billing,deposit,due}' is not null and s#>>'{billing,deposit,due}' not in ('with_first_invoice','before_first_lesson') then raise exception 'Unknown deposit due rule'; end if;
  if s#>>'{billing,deposit,waived_by}' is not null and s#>>'{billing,deposit,waived_by}' not in ('owner','issue_invoices','nobody') then raise exception 'Unknown deposit waiver rule'; end if;
  if s#>>'{billing,deposit,release}' is not null and s#>>'{billing,deposit,release}' not in ('refund_full','refund_less_unpaid','admin_decides') then raise exception 'Unknown deposit release rule'; end if;
  if s#>>'{billing,deposit,refund_approved_by}' is not null and s#>>'{billing,deposit,refund_approved_by}' not in ('owner','staff','four_eyes') then raise exception 'Unknown deposit refund approver'; end if;
  if s#>>'{billing,late_fee,repeat}' is not null and s#>>'{billing,late_fee,repeat}' not in ('none','once','monthly') then raise exception 'Unknown late fee repeat'; end if;
  if s#>>'{billing,late_fee,type}' is not null and s#>>'{billing,late_fee,type}' not in ('fixed','percent') then raise exception 'Unknown late fee type'; end if;
  if s#>>'{billing,late_fee,show_as}' is not null and s#>>'{billing,late_fee,show_as}' not in ('next_invoice_line','own_invoice') then raise exception 'Unknown late fee placement'; end if;
  if s#>>'{billing,late_fee,waived_by}' is not null and s#>>'{billing,late_fee,waived_by}' not in ('owner','issue_invoices') then raise exception 'Unknown late fee waiver rule'; end if;
  if s#>>'{lessons,class_type}' is not null and s#>>'{lessons,class_type}' not in ('one_to_one','group','both') then raise exception 'Unknown class type'; end if;
  foreach k in array array['{billing,deposit,taxable}','{billing,deposit,top_up}','{billing,deposit,set_off_unpaid}','{billing,deposit,final_month}','{billing,trials,charged}'] loop
    v := s #> k::text[];
    if v is not null and jsonb_typeof(v) not in ('boolean','null') then raise exception 'Setting % must be yes or no', k; end if;
  end loop;
  for r in select * from (values
    ('{billing,deposit,percent_bp}', 0, 10000, 'Deposit percentage must be between 0% and 100%'),
    ('{billing,deposit,forfeit_notice_days}', 0, 90, 'Deposit notice must be 0-90 days'),
    ('{billing,late_fee,percent_bp}', 0, 10000, 'Late fee percentage must be between 0% and 100%'),
    ('{billing,late_fee,after_days}', 0, 365, 'Late fee grace period must be 0-365 days'),
    ('{billing,late_fee,cap_cents}', 0, 100000000, 'Late fee limit must be a whole number of cents, 0 to 100000000'),
    ('{billing,late_fee,amount_cents}', 0, 100000000, 'Late fee amount must be a whole number of cents, 0 to 100000000'),
    ('{billing,one_off_fees,deposit_cents}', 0, 100000000, 'Deposit amount must be a whole number of cents, 0 to 100000000'),
    ('{profile,next_invoice_number}', 1, 999999999, 'Next invoice number must be a whole number, 1 or more')
  ) as c(p, lo, hi, msg) loop
    v := s #> r.p::text[];
    if v is not null and jsonb_typeof(v) <> 'null' and not (case when jsonb_typeof(v) = 'number' and v::text ~ '^[0-9]{1,12}$'
         then (v#>>'{}')::bigint between r.lo and r.hi else false end) then
      raise exception '%', r.msg; end if;
  end loop;
  -- a percentage mode needs a real percentage (1 = 0.01%)
  if s#>>'{billing,deposit,mode}' = 'percent_first_month' and coalesce((s#>>'{billing,deposit,percent_bp}')::int, 0) < 1 then
    raise exception 'Deposit percentage must be between 0.01%% and 100%%'; end if;
  if s#>>'{billing,late_fee,type}' = 'percent' and coalesce((s#>>'{billing,late_fee,percent_bp}')::int, 0) < 1 then
    raise exception 'Late fee percentage must be between 0.01%% and 100%%'; end if;
  -- T6 step 2 (tutors change their own lessons). Every key is optional; a key that is present must be right. assets/js/org-settings.js has the labels and defaults.
  if s#>>'{lessons,timetable_editing}' is not null and s#>>'{lessons,timetable_editing}' not in ('admin_only','tutors_direct','tutors_propose') then raise exception 'Unknown timetable editing setting'; end if;
  if s#>>'{lessons,notify_family}' is not null and s#>>'{lessons,notify_family}' not in ('off','list_for_admin') then raise exception 'Unknown family notice setting'; end if;
  if s#>'{lessons,tutors_edit}' is not null and jsonb_typeof(s#>'{lessons,tutors_edit}') not in ('object','null') then raise exception 'Tutor editing switches are malformed'; end if;
  foreach k in array array['{lessons,tutors_edit,postpone}','{lessons,tutors_edit,cancel}','{lessons,tutors_edit,weekly_slots}','{lessons,tutors_edit,generate}','{lessons,tutors_edit,one_off}','{lessons,tutors_edit,link}'] loop
    v := s #> k::text[];
    if v is not null and jsonb_typeof(v) not in ('boolean','null') then raise exception 'Setting % must be yes or no', k; end if;
  end loop;
  for r in select * from (values
    ('{lessons,min_notice_hours}', 0, 168, 'Notice before a change must be 0-168 hours'),
    ('{lessons,max_changes_per_month}', 0, 500, 'Changes per tutor per month must be 0-500 (0 = no limit)')
  ) as c(p, lo, hi, msg) loop
    v := s #> r.p::text[];
    if v is not null and jsonb_typeof(v) <> 'null' and not (case when jsonb_typeof(v) = 'number' and v::text ~ '^[0-9]{1,4}$'
         then (v#>>'{}')::bigint between r.lo and r.hi else false end) then
      raise exception '%', r.msg; end if;
  end loop;
  -- billing starts from: empty, or a real date between 2020-01-01 and 2100-01-01
  if s#>'{billing,starts_from}' is not null and jsonb_typeof(s#>'{billing,starts_from}') <> 'null' then
    if jsonb_typeof(s#>'{billing,starts_from}') <> 'string' then raise exception 'Billing start must be a date'; end if;
    bs := s#>>'{billing,starts_from}';
    if bs <> '' then
      if bs !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then raise exception 'Billing start must be a date (YYYY-MM-DD)'; end if;
      begin perform make_date(substr(bs,1,4)::int, substr(bs,6,2)::int, substr(bs,9,2)::int);
      exception when others then raise exception 'Billing start must be a real date'; end;
      if bs < '2020-01-01' or bs > '2100-01-01' then raise exception 'Billing start must be between 2020 and 2100'; end if;
    end if;
  end if;
  -- T7.3 (invoice, receipt and reminder emails to families). Every key is optional; a key that is present must be right. assets/js/org-settings.js has the labels and
  -- defaults and assets/js/invoice-email-core.js the placeholder list (tests/org-settings.test.js and tests/invoice-email-core.test.js compare them with this).
  if s#>'{email}' is not null and jsonb_typeof(s#>'{email}') not in ('object','null') then raise exception 'Email settings are malformed'; end if;
  if s#>>'{email,mode}' is not null and s#>>'{email,mode}' not in ('off','staff_send','auto_on_issue') then raise exception 'Unknown email sending setting'; end if;
  foreach k in array array['{email,receipts}','{email,late_fee_notice}','{email,reminders,enabled}'] loop
    v := s #> k::text[];
    if v is not null and jsonb_typeof(v) not in ('boolean','null') then raise exception 'Setting % must be yes or no', k; end if;
  end loop;
  for r in select * from (values
    ('{email,reminders,first_after_days}', 1, 90, 'Send the first reminder 1-90 days after the due date'),
    ('{email,reminders,repeat_days}', 0, 90, 'Repeat reminders every 0-90 days (0 = only one reminder)'),
    ('{email,reminders,max_count}', 1, 10, 'Send 1-10 reminders at most'),
    ('{email,daily_cap}', 1, 300, 'Emails per day must be 1-300'),
    ('{email,per_hour}', 1, 300, 'Emails per hour must be 1-300')
  ) as c(p, lo, hi, msg) loop
    v := s #> r.p::text[];
    if v is not null and jsonb_typeof(v) <> 'null' and not (case when jsonb_typeof(v) = 'number' and v::text ~ '^[0-9]{1,4}$'
         then (v#>>'{}')::bigint between r.lo and r.hi else false end) then
      raise exception '%', r.msg; end if;
  end loop;
  -- the wording: plain text, a limited set of fields in {braces}
  if s#>'{email,templates}' is not null and jsonb_typeof(s#>'{email,templates}') not in ('object','null') then raise exception 'Email wording is malformed'; end if;
  foreach k in array array['invoice','receipt','reminder','late_fee'] loop
    foreach tp in array array['subject','body'] loop
      v := s #> array['email','templates',k,tp];
      if v is not null and jsonb_typeof(v) <> 'null' then
        if jsonb_typeof(v) <> 'string' then raise exception 'Email wording must be text'; end if;
        if length(v#>>'{}') > (case tp when 'subject' then 120 else 1000 end) then raise exception 'Email wording is too long (subject 120, message 1000 characters)'; end if;
        if regexp_replace(v#>>'{}', '\{(name|centre|number|amount|due_date|link|contact|paid_on|days_overdue)\}', '', 'g') ~ '[{}]' then
          raise exception 'Email wording can only use {name} {centre} {number} {amount} {due_date} {link} {contact} {paid_on} {days_overdue}'; end if;
      end if;
    end loop;
  end loop;
  if s#>>'{email,mode}' is not null and s#>>'{email,mode}' <> 'off' and coalesce((s#>>'{invoicing,delivery,share_link}')::boolean, true) = false then
    raise exception 'Emailing invoices needs the shareable invoice link switched on'; end if;
  if nullif(trim(coalesce(s#>>'{profile,reply_to_email}', '')), '') is not null and trim(s#>>'{profile,reply_to_email}') !~ '^[^@\s<>,;]+@[^@\s<>,;]+\.[^@\s<>,;]+$' then
    raise exception 'The reply-to email address doesn''t look right'; end if;
end $$;


-- ---------------------------------------------------------------------------------------------------
-- 4. small helpers (internal)
-- ---------------------------------------------------------------------------------------------------
create or replace function public.email_valid(p text) returns boolean
language sql immutable set search_path = public as $$
  select p is not null and length(p) <= 254 and p ~ '^[^@\s<>,;]+@[^@\s<>,;]+\.[^@\s<>,;]{2,}$'
$$;

-- "j***@g***.com": all that is ever written to the log
create or replace function public.email_mask(p text) returns text
language sql immutable set search_path = public as $$
  select case when public.email_valid(trim(p))
    then left(split_part(trim(p), '@', 1), 1) || '***@' || left(split_part(trim(p), '@', 2), 1) || '***.' || regexp_replace(split_part(trim(p), '@', 2), '^.*\.', '')
    else '***' end
$$;

-- the email options with every default filled in (the same defaults as assets/js/org-settings.js)
create or replace function public.email_cfg(s jsonb) returns jsonb
language sql immutable set search_path = public as $$
  select jsonb_build_object(
    'mode',            coalesce(s#>>'{email,mode}', 'off'),
    'receipts',        coalesce((s#>>'{email,receipts}')::boolean, false),
    'late_fee_notice', coalesce((s#>>'{email,late_fee_notice}')::boolean, false),
    'reminders',       jsonb_build_object('enabled', coalesce((s#>>'{email,reminders,enabled}')::boolean, false),
                         'first_after_days', coalesce((s#>>'{email,reminders,first_after_days}')::int, 3),
                         'repeat_days', coalesce((s#>>'{email,reminders,repeat_days}')::int, 7),
                         'max_count', coalesce((s#>>'{email,reminders,max_count}')::int, 3)),
    'daily_cap',       coalesce((s#>>'{email,daily_cap}')::int, 200),
    'per_hour',        coalesce((s#>>'{email,per_hour}')::int, 60),
    'share_link',      coalesce((s#>>'{invoicing,delivery,share_link}')::boolean, true),
    'reply_to',        nullif(trim(coalesce(s#>>'{profile,reply_to_email}', '')), ''),
    'centre_name',     nullif(trim(coalesce(s#>>'{profile,trading_name}', '')), ''),
    'templates',       case when jsonb_typeof(s#>'{email,templates}') = 'object' then s#>'{email,templates}' else '{}'::jsonb end)
$$;

-- a centre's email options as of a day (no caller needed: used by triggers and the server)
create or replace function public.email_org_cfg(p_org uuid, p_day date) returns jsonb
language sql stable security definer set search_path = public as $$
  select public.email_cfg(coalesce((select x.settings from org_settings x where x.org_id = p_org and x.effective_from <= p_day
                                    order by x.effective_from desc, x.version desc limit 1), '{}'::jsonb))
$$;

create or replace function public.email_today(p_org uuid) returns date
language sql stable security definer set search_path = public as $$
  select (now() at time zone o.timezone)::date from organisations o where o.id = p_org and o.kind = 'centre'
$$;

-- Can this invoice be emailed (as an invoice, a reminder or a late-fee notice) right now?  { ok, reason?, ... what the message needs }
create or replace function public.email_invoice_state(p_org uuid, p_invoice uuid, p_today date) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare i centre_invoices; b record; hh uuid; ps text;
begin
  select * into i from centre_invoices where id = p_invoice and org_id = p_org;
  if i.id is null then return jsonb_build_object('ok', false, 'reason', 'not_found'); end if;
  if i.kind not in ('lesson', 'deposit', 'late_fee') then return jsonb_build_object('ok', false, 'reason', 'not_billable'); end if;
  if i.status = 'void' then return jsonb_build_object('ok', false, 'reason', 'void'); end if;
  if i.status <> 'issued' then return jsonb_build_object('ok', false, 'reason', 'not_issued'); end if;
  select * into b from centre_balance_rows(p_org, array[p_invoice]);
  ps := centre_pay_status('issued', i.kind, b.total_cents, b.credited_cents, b.paid_cents, i.due_date, p_today);
  if ps = 'void' then return jsonb_build_object('ok', false, 'reason', 'void'); end if;            -- fully credited
  if ps = 'paid' then return jsonb_build_object('ok', false, 'reason', 'paid'); end if;
  hh := centre_invoice_household(p_invoice);
  if hh is null then return jsonb_build_object('ok', false, 'reason', 'no_household'); end if;
  return jsonb_build_object('ok', true, 'kind', i.kind, 'number', i.number_text, 'household_id', hh, 'due_date', i.due_date, 'issue_date', i.issue_date,
    'total_cents', i.total_cents, 'balance_cents', b.balance_cents, 'pay_status', ps);
end $$;

-- the secret link of an invoice (made if it doesn't exist; renewed if it expired). The same row centre_invoice_share_link() keeps, without needing a browser login.
create or replace function public.email_share_token(p_org uuid, p_invoice uuid, p_today date) returns uuid
language plpgsql security definer set search_path = public, pg_temp as $$
declare sh centre_invoice_share;
begin
  select * into sh from centre_invoice_share where invoice_id = p_invoice and org_id = p_org;
  if sh.id is null then
    insert into centre_invoice_share(org_id, invoice_id) values (p_org, p_invoice) returning * into sh;
  elsif sh.expires_on is not null and sh.expires_on < p_today then
    update centre_invoice_share set token = gen_random_uuid(), expires_on = null, rotated_at = now() where id = sh.id returning * into sh;
  end if;
  return sh.token;
end $$;

-- Queue a message for a family's billing contacts. Returns { queued, skipped: [reason, ...] }.
--   p_by null = automatic (a trigger or the reminder planner): problems are recorded as 'skipped' rows so staff can see them.
--   p_by set  = a person pressed Send: problems come back to them in the answer and nothing is written for them.
--   p_resend  = a deliberate second send of the same message (no dedupe key; the caller has already checked the gap and the daily limit).
create or replace function public.email_enqueue_rows(p_org uuid, p_kind text, p_invoice uuid, p_payment uuid, p_household uuid, p_by uuid, p_resend boolean, p_reminder_no int)
returns jsonb language plpgsql security definer set search_path = public as $$
declare g record; flagged boolean; any_g boolean := false; why text; key text; n_q int := 0; skipped jsonb := '[]'::jsonb; rows int;
begin
  select exists (select 1 from guardians x where x.org_id = p_org and x.household_id = p_household and x.billing_contact) into flagged;
  for g in select x.id, x.email, x.email_status from guardians x where x.org_id = p_org and x.household_id = p_household and (not flagged or x.billing_contact)
           order by x.created_at, x.id limit (case when flagged then 6 else 1 end) loop
    any_g := true;
    why := case when not email_valid(g.email) then 'no_email' when g.email_status = 'bad' then 'bad_address' end;
    key := case when p_resend then null else p_kind || ':' || coalesce(p_invoice::text, p_payment::text) || ':' || coalesce(p_reminder_no::text, '0') || ':' || g.id::text end;
    if why is not null then
      if p_by is null then
        insert into email_queue(org_id, kind, invoice_id, payment_id, household_id, guardian_id, reminder_no, status, reason, requested_by)
        values (p_org, p_kind, p_invoice, p_payment, p_household, g.id, p_reminder_no, 'skipped', why, null);
        insert into email_send_log(org_id, kind, invoice_id, guardian_id, template, result, detail) values (p_org, p_kind, p_invoice, g.id, p_kind, 'skipped', why);
      end if;
      skipped := skipped || to_jsonb(why);
      continue;
    end if;
    insert into email_queue(org_id, kind, invoice_id, payment_id, household_id, guardian_id, reminder_no, requested_by, dedupe_key)
    values (p_org, p_kind, p_invoice, p_payment, p_household, g.id, p_reminder_no, p_by, key)
    on conflict (dedupe_key) where dedupe_key is not null and status in ('queued', 'sending', 'sent') do nothing;
    get diagnostics rows = row_count;
    if rows = 1 then n_q := n_q + 1; else skipped := skipped || to_jsonb('already_sent'::text); end if;
  end loop;
  if not any_g then
    if p_by is null then
      insert into email_queue(org_id, kind, invoice_id, payment_id, household_id, guardian_id, reminder_no, status, reason, requested_by)
      values (p_org, p_kind, p_invoice, p_payment, p_household, null, p_reminder_no, 'skipped', 'no_contact', null);
      insert into email_send_log(org_id, kind, invoice_id, template, result, detail) values (p_org, p_kind, p_invoice, p_kind, 'skipped', 'no_contact');
    end if;
    skipped := skipped || to_jsonb('no_contact'::text);
  end if;
  return jsonb_build_object('queued', n_q, 'skipped', skipped);
end $$;

-- ---------------------------------------------------------------------------------------------------
-- 5. automatic queuing: invoice issued, payment recorded (only when the centre's settings ask for it; never able to stop the invoice or the payment)
-- ---------------------------------------------------------------------------------------------------
create or replace function public.email_on_invoice_issued() returns trigger
language plpgsql security definer set search_path = public as $$
declare cfg jsonb; today date; hh uuid;
begin
  begin
    if new.kind not in ('lesson', 'deposit', 'late_fee') or new.imported_number is not null then return null; end if;
    today := email_today(new.org_id);
    cfg := email_org_cfg(new.org_id, today);
    if cfg->>'mode' = 'off' or not (cfg->>'share_link')::boolean then return null; end if;
    if new.kind = 'late_fee' then
      if not (cfg->>'late_fee_notice')::boolean then return null; end if;
    elsif cfg->>'mode' <> 'auto_on_issue' then return null;
    end if;
    hh := centre_invoice_household(new.id);
    if hh is null then return null; end if;
    perform email_enqueue_rows(new.org_id, case when new.kind = 'late_fee' then 'late_fee' else 'invoice' end, new.id, null, hh, null, false, null);
  exception when others then
    null;                                   -- email trouble must never block an invoice being issued
  end;
  return null;
end $$;
drop trigger if exists email_on_invoice_issued on public.centre_invoices;
create trigger email_on_invoice_issued after update of status on public.centre_invoices for each row
  when (old.status = 'draft' and new.status = 'issued') execute function public.email_on_invoice_issued();

create or replace function public.email_on_payment() returns trigger
language plpgsql security definer set search_path = public as $$
declare cfg jsonb;
begin
  begin
    cfg := email_org_cfg(new.org_id, email_today(new.org_id));
    if cfg->>'mode' = 'off' or not (cfg->>'receipts')::boolean then return null; end if;
    perform email_enqueue_rows(new.org_id, 'receipt', null, new.id, new.household_id, null, false, null);
  exception when others then
    null;                                   -- email trouble must never block a payment being recorded
  end;
  return null;
end $$;
drop trigger if exists email_on_payment on public.centre_payments;
create trigger email_on_payment after insert on public.centre_payments for each row
  when (new.kind = 'payment') execute function public.email_on_payment();

-- ---------------------------------------------------------------------------------------------------
-- 6. the reminder planner (server: daily cron and every drain) — which overdue invoices are due their next reminder
-- ---------------------------------------------------------------------------------------------------
-- Reminder n is due on  due date + first_after_days + (n-1) × repeat_days,  never sooner than repeat_days after the previous one (so a day the job missed
-- doesn't send two at once). Only invoices issued in the last 120 days, so switching reminders on never mails a centre's ancient history.
-- p_dry = count only. Returns how many invoices got (or would get) a reminder now.
create or replace function public.email_plan_reminders(p_org uuid, p_dry boolean default false) returns int
language plpgsql security definer set search_path = public as $$
declare today date; cfg jsonb; inv record; st jsonb; n_prev int; last_day date; n_next int; due_on date; made int := 0; mx int; rep int; first_d int; tz text;
begin
  select timezone into tz from organisations where id = p_org and kind = 'centre';
  if tz is null then return 0; end if;
  today := (now() at time zone tz)::date;
  cfg := email_org_cfg(p_org, today);
  if cfg->>'mode' = 'off' or not (cfg#>>'{reminders,enabled}')::boolean or not (cfg->>'share_link')::boolean then return 0; end if;
  mx := (cfg#>>'{reminders,max_count}')::int; rep := (cfg#>>'{reminders,repeat_days}')::int; first_d := (cfg#>>'{reminders,first_after_days}')::int;
  for inv in select i.id, i.due_date from centre_invoices i
              where i.org_id = p_org and i.status = 'issued' and i.kind in ('lesson', 'deposit', 'late_fee') and i.due_date is not null
                and i.due_date < today and i.issue_date >= today - 120 order by i.due_date, i.id limit 3000 loop
    st := email_invoice_state(p_org, inv.id, today);
    if not (st->>'ok')::boolean then continue; end if;
    select count(distinct q.reminder_no), max((q.requested_at at time zone tz)::date) into n_prev, last_day from email_queue q where q.invoice_id = inv.id and q.kind = 'reminder';
    n_next := n_prev + 1;
    if n_next > mx or (rep = 0 and n_next > 1) then continue; end if;
    due_on := inv.due_date + first_d + (n_next - 1) * rep;
    if last_day is not null then due_on := greatest(due_on, last_day + rep); end if;
    if today < due_on then continue; end if;
    if not p_dry then perform email_enqueue_rows(p_org, 'reminder', inv.id, null, (st->>'household_id')::uuid, null, false, n_next); end if;
    made := made + 1;
  end loop;
  return made;
end $$;

-- ---------------------------------------------------------------------------------------------------
-- 7. staff functions (signed in; each starts with the gate: a centre's owner or staff with the permission; everyone else gets NOT_FOUND)
-- ---------------------------------------------------------------------------------------------------
create or replace function public.email_queue_status(p_org uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare today date := centre_money_gate(p_org, 'either'); tz text; cfg jsonb; q int; sending int; sent_today int; failed_24h int; cap int; rem int; days int; bad int; last_at timestamptz; skipped_24h int;
begin
  select timezone into tz from organisations where id = p_org;
  cfg := email_org_cfg(p_org, today);
  cap := (cfg->>'daily_cap')::int;
  select count(*) filter (where status = 'queued'), count(*) filter (where status = 'sending') into q, sending from email_queue where org_id = p_org and status in ('queued', 'sending');
  select count(*) filter (where result = 'sent' and (at at time zone tz)::date = today), count(*) filter (where result = 'failed' and at > now() - interval '24 hours'),
         count(*) filter (where result in ('skipped', 'cancelled') and at > now() - interval '24 hours'), max(at) filter (where result = 'sent')
    into sent_today, failed_24h, skipped_24h, last_at from email_send_log where org_id = p_org and at > now() - interval '2 days';
  select count(*) into bad from guardians where org_id = p_org and email_status = 'bad';
  rem := greatest(cap - sent_today, 0);
  days := case when q = 0 then 0 when q <= rem then 1 else 1 + ceil((q - rem)::numeric / cap)::int end;
  return jsonb_build_object('mode', cfg->>'mode', 'queued', q, 'sending', sending, 'sent_today', sent_today, 'failed_24h', failed_24h, 'skipped_24h', skipped_24h,
    'daily_cap', cap, 'per_hour', (cfg->>'per_hour')::int, 'remaining_today', rem, 'sends_over_days', days, 'bad_addresses', bad, 'last_sent_at', last_at,
    'reminders_on', (cfg#>>'{reminders,enabled}')::boolean, 'receipts_on', (cfg->>'receipts')::boolean, 'late_fee_notice_on', (cfg->>'late_fee_notice')::boolean,
    'share_link', (cfg->>'share_link')::boolean, 'today', today);
end $$;

-- Press Send: queue these invoices for their billing contacts. p_resend = send it again on purpose.
create or replace function public.email_enqueue(p_org uuid, p_invoices uuid[], p_resend boolean default false) returns jsonb
language plpgsql security definer set search_path = public as $$
declare today date := centre_money_gate(p_org, 'issue_invoices'); cfg jsonb; inv_id uuid; st jsonb; r jsonb; res jsonb := '[]'::jsonb; n_q int := 0; n_s int := 0; mkind text; last_at timestamptz; n_day int; why text;
begin
  if p_invoices is null or coalesce(array_length(p_invoices, 1), 0) = 0 then raise exception 'BAD_VALUE: choose at least one invoice' using errcode = 'P0001'; end if;
  if array_length(p_invoices, 1) > 500 then raise exception 'BAD_VALUE: at most 500 invoices at a time' using errcode = 'P0001'; end if;
  cfg := email_org_cfg(p_org, today);
  if cfg->>'mode' = 'off' then raise exception 'NOT_ALLOWED: emailing invoices is switched off in this centre''s settings (Invoicing > Email)' using errcode = '42501'; end if;
  if not (cfg->>'share_link')::boolean then raise exception 'NOT_ALLOWED: emailing needs the shareable invoice link switched on' using errcode = '42501'; end if;
  foreach inv_id in array p_invoices loop
    st := email_invoice_state(p_org, inv_id, today);
    if not (st->>'ok')::boolean then n_s := n_s + 1; res := res || jsonb_build_object('invoice_id', inv_id, 'reason', st->>'reason'); continue; end if;
    mkind := case when st->>'kind' = 'late_fee' then 'late_fee' else 'invoice' end;
    if p_resend then
      select max(requested_at) into last_at from email_queue where invoice_id = inv_id and kind in ('invoice', 'late_fee') and status in ('queued', 'sending', 'sent');
      select count(*) into n_day from email_queue where invoice_id = inv_id and kind in ('invoice', 'late_fee') and requested_at > now() - interval '24 hours' and status in ('queued', 'sending', 'sent');
      why := case when last_at is not null and last_at > now() - interval '10 minutes' then 'too_soon' when n_day >= 3 then 'daily_limit' end;
      if why is not null then n_s := n_s + 1; res := res || jsonb_build_object('invoice_id', inv_id, 'number', st->>'number', 'reason', why); continue; end if;
    end if;
    r := email_enqueue_rows(p_org, mkind, inv_id, null, (st->>'household_id')::uuid, auth.uid(), p_resend, null);
    n_q := n_q + (r->>'queued')::int;
    if jsonb_array_length(r->'skipped') > 0 then
      n_s := n_s + 1; res := res || jsonb_build_object('invoice_id', inv_id, 'number', st->>'number', 'reason', r#>>'{skipped,0}');
    end if;
  end loop;
  insert into audit_log(org_id, actor, action, table_name, row_id, before, after)
  values (p_org, auth.uid(), 'email_enqueue', 'email_queue', null, null, jsonb_build_object('invoices', array_length(p_invoices, 1), 'queued', n_q, 'resend', coalesce(p_resend, false)));
  return jsonb_build_object('queued', n_q, 'skipped', n_s, 'problems', res, 'status', email_queue_status(p_org));
end $$;

-- "Send all unsent": every issued invoice of a month (or of the last 45 days when no month is given) that has not been emailed or queued yet
create or replace function public.email_enqueue_unsent(p_org uuid, p_period date default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare today date := centre_money_gate(p_org, 'issue_invoices'); ids uuid[]; a date; b date;
begin
  if p_period is null then a := today - 45; b := today; else a := date_trunc('month', p_period)::date; b := (a + interval '1 month - 1 day')::date; end if;
  select coalesce(array_agg(i.id order by i.issue_date, i.id), '{}') into ids from (
    select x.id, x.issue_date from centre_invoices x
     where x.org_id = p_org and x.status = 'issued' and x.kind in ('lesson', 'deposit', 'late_fee') and x.imported_number is null and x.issue_date between a and b
       and not exists (select 1 from email_queue q where q.invoice_id = x.id and q.kind in ('invoice', 'late_fee') and q.status in ('queued', 'sending', 'sent'))
     order by x.issue_date, x.id limit 500) i;
  if coalesce(array_length(ids, 1), 0) = 0 then
    return jsonb_build_object('queued', 0, 'skipped', 0, 'problems', '[]'::jsonb, 'status', email_queue_status(p_org));
  end if;
  return email_enqueue(p_org, ids, false);
end $$;

create or replace function public.email_queue_list(p_org uuid, p_status text default null, p_limit int default 100, p_offset int default 0) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare today date := centre_money_gate(p_org, 'either');
begin
  return coalesce((select jsonb_agg(jsonb_build_object('id', q.id, 'kind', q.kind, 'status', q.status, 'reason', q.reason, 'attempts', q.attempts, 'not_before', q.not_before,
      'requested_at', q.requested_at, 'reminder_no', q.reminder_no, 'invoice_number', i.number_text, 'family', h.name, 'to_masked', email_mask(g.email),
      'by', (select m.display_name from memberships m where m.org_id = p_org and m.user_id = q.requested_by and m.status = 'active' limit 1), 'automatic', q.requested_by is null)
      order by q.requested_at desc, q.id)
    from (select * from email_queue x where x.org_id = p_org and (p_status is null or x.status = p_status) order by x.requested_at desc, x.id
          limit least(greatest(coalesce(p_limit, 100), 1), 300) offset greatest(coalesce(p_offset, 0), 0)) q
    left join centre_invoices i on i.id = q.invoice_id and i.org_id = p_org
    left join households h on h.id = q.household_id and h.org_id = p_org
    left join guardians g on g.id = q.guardian_id and g.org_id = p_org), '[]'::jsonb);
end $$;

create or replace function public.email_queue_cancel(p_org uuid, p_ids uuid[]) returns jsonb
language plpgsql security definer set search_path = public as $$
declare today date := centre_money_gate(p_org, 'issue_invoices'); q record; n int := 0;
begin
  if p_ids is null or coalesce(array_length(p_ids, 1), 0) = 0 then raise exception 'BAD_VALUE: choose at least one message' using errcode = 'P0001'; end if;
  if array_length(p_ids, 1) > 500 then raise exception 'BAD_VALUE: at most 500 at a time' using errcode = 'P0001'; end if;
  for q in select * from email_queue where org_id = p_org and id = any(p_ids) and status = 'queued' order by id for update loop
    update email_queue set status = 'cancelled', reason = 'cancelled_by_staff', updated_at = now() where id = q.id;
    insert into email_send_log(org_id, queue_id, kind, invoice_id, guardian_id, template, result, detail, by_user) values (p_org, q.id, q.kind, q.invoice_id, q.guardian_id, q.kind, 'cancelled', 'cancelled_by_staff', auth.uid());
    n := n + 1;
  end loop;
  if n > 0 then
    insert into audit_log(org_id, actor, action, table_name, row_id, before, after) values (p_org, auth.uid(), 'email_queue_cancel', 'email_queue', null, null, jsonb_build_object('cancelled', n));
  end if;
  return jsonb_build_object('cancelled', n, 'status', email_queue_status(p_org));
end $$;

create or replace function public.email_log_list(p_org uuid, p_limit int default 100, p_before bigint default null) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare today date := centre_money_gate(p_org, 'either');
begin
  return coalesce((select jsonb_agg(jsonb_build_object('id', l.id, 'at', l.at, 'kind', l.kind, 'template', l.template, 'result', l.result, 'detail', l.detail, 'attempt', l.attempt,
      'to_masked', l.to_masked, 'invoice_number', i.number_text,
      'by', case when l.by_user is null then null else (select m.display_name from memberships m where m.org_id = p_org and m.user_id = l.by_user and m.status = 'active' limit 1) end,
      'automatic', l.by_user is null) order by l.id desc)
    from (select * from email_send_log x where x.org_id = p_org and (p_before is null or x.id < p_before) order by x.id desc limit least(greatest(coalesce(p_limit, 100), 1), 300)) l
    left join centre_invoices i on i.id = l.invoice_id and i.org_id = p_org), '[]'::jsonb);
end $$;

-- who would get a family's emails, with addresses masked
create or replace function public.email_household_contacts(p_org uuid, p_household uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare today date := centre_money_gate(p_org, 'either'); flagged boolean;
begin
  if not exists (select 1 from households h where h.id = p_household and h.org_id = p_org) then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  select exists (select 1 from guardians x where x.org_id = p_org and x.household_id = p_household and x.billing_contact) into flagged;
  return jsonb_build_object('flagged', flagged, 'guardians', coalesce((select jsonb_agg(jsonb_build_object('id', g.id, 'name', g.name, 'relation', g.relation, 'has_email', email_valid(g.email),
      'to_masked', case when email_valid(g.email) then email_mask(g.email) else null end, 'billing_contact', g.billing_contact, 'bad', g.email_status = 'bad',
      'receives', (case when flagged then g.billing_contact else g.id = (select y.id from guardians y where y.org_id = p_org and y.household_id = p_household order by y.created_at, y.id limit 1) end)
                  and email_valid(g.email) and g.email_status = 'ok') order by g.created_at, g.id)
    from guardians g where g.org_id = p_org and g.household_id = p_household), '[]'::jsonb));
end $$;

-- choose a family's billing contacts (an empty list = back to "the first guardian")
create or replace function public.email_set_billing_contacts(p_org uuid, p_household uuid, p_guardians uuid[]) returns jsonb
language plpgsql security definer set search_path = public as $$
declare today date := centre_money_gate(p_org, 'issue_invoices'); gid uuid; n int;
begin
  if not exists (select 1 from households h where h.id = p_household and h.org_id = p_org) then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  p_guardians := coalesce(p_guardians, '{}');
  if array_length(p_guardians, 1) > 6 then raise exception 'BAD_VALUE: at most 6 billing contacts' using errcode = 'P0001'; end if;
  foreach gid in array p_guardians loop
    if not exists (select 1 from guardians g where g.id = gid and g.org_id = p_org and g.household_id = p_household) then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  end loop;
  update guardians set billing_contact = (id = any(p_guardians)) where org_id = p_org and household_id = p_household and billing_contact is distinct from (id = any(p_guardians));
  get diagnostics n = row_count;
  return email_household_contacts(p_org, p_household);
end $$;

-- "I fixed it": staff trust the address again (editing the address in the student sheet does this by itself)
create or replace function public.email_clear_bad(p_org uuid, p_guardian uuid) returns jsonb
language plpgsql security definer set search_path = public as $$
declare today date := centre_money_gate(p_org, 'issue_invoices');
begin
  if not exists (select 1 from guardians g where g.id = p_guardian and g.org_id = p_org) then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  update guardians set email_status = 'ok', email_bad_at = null where id = p_guardian and org_id = p_org;
  return jsonb_build_object('ok', true, 'bad_addresses', (select count(*) from guardians where org_id = p_org and email_status = 'bad'));
end $$;

create or replace function public.email_bad_list(p_org uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare today date := centre_money_gate(p_org, 'either');
begin
  return coalesce((select jsonb_agg(jsonb_build_object('guardian_id', g.id, 'name', g.name, 'family', h.name, 'household_id', g.household_id, 'to_masked', email_mask(g.email), 'since', g.email_bad_at)
      order by g.email_bad_at desc nulls last, g.id)
    from guardians g left join households h on h.id = g.household_id and h.org_id = p_org where g.org_id = p_org and g.email_status = 'bad'), '[]'::jsonb);
end $$;

-- the reminders screen: what the schedule is and how many invoices would be reminded today
create or replace function public.email_reminder_preview(p_org uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare today date := centre_money_gate(p_org, 'either'); cfg jsonb; overdue int; due_now int;
begin
  cfg := email_org_cfg(p_org, today);
  select count(*) into overdue from centre_invoices i where i.org_id = p_org and i.status = 'issued' and i.kind in ('lesson', 'deposit', 'late_fee') and i.due_date is not null and i.due_date < today
     and i.issue_date >= today - 120 and (email_invoice_state(p_org, i.id, today)->>'ok')::boolean;
  due_now := email_plan_reminders(p_org, true);
  return jsonb_build_object('enabled', (cfg#>>'{reminders,enabled}')::boolean and cfg->>'mode' <> 'off', 'mode', cfg->>'mode', 'first_after_days', (cfg#>>'{reminders,first_after_days}')::int,
    'repeat_days', (cfg#>>'{reminders,repeat_days}')::int, 'max_count', (cfg#>>'{reminders,max_count}')::int, 'overdue_invoices', overdue, 'due_now', due_now);
end $$;

-- ---------------------------------------------------------------------------------------------------
-- 8. server functions (service role only: they return real addresses to the sender, so no browser can ever call them)
-- ---------------------------------------------------------------------------------------------------
-- Take up to p_max due messages to send now. Keeps to every limit: the centre's daily cap and per-hour cap (counting what is already being sent), p_platform_left (the
-- platform-wide room the server worked out), and checks everything AGAIN at this moment (paid since? voided? switched off? address fixed or bad?).
-- Returns the messages to send (with the address and the wording); the ones that can no longer go are closed here with a reason.
create or replace function public.email_claim(p_org uuid default null, p_max int default 20, p_platform_left int default 1000) returns jsonb
language plpgsql security definer set search_path = public as $$
declare o record; tz text; today date; cfg jsonb; used_day int; used_hr int; busy int; room int; claimed int; total int := 0; q record; st jsonb; g guardians; why text; pay centre_payments;
  res_list jsonb := '[]'::jsonb; payload jsonb; tok uuid; nums text; centre text; cname text; hname text; vars jsonb; tpl jsonb; n_inv int;
begin
  p_max := least(greatest(coalesce(p_max, 1), 1), 100);
  p_platform_left := coalesce(p_platform_left, 0);
  -- a worker that died mid-send: try again later, or give up after three attempts
  update email_queue set status = case when attempts >= 3 then 'failed' else 'queued' end, reason = case when attempts >= 3 then 'stuck' else reason end,
         not_before = now(), updated_at = now()
   where status = 'sending' and updated_at < now() - interval '15 minutes' and (p_org is null or org_id = p_org);
  for o in select distinct x.org_id from email_queue x where x.status = 'queued' and x.not_before <= now() and (p_org is null or x.org_id = p_org) order by x.org_id loop
    exit when total >= p_max or p_platform_left - total <= 0;
    select timezone, trading_name into tz, centre from organisations where id = o.org_id and kind = 'centre';
    if tz is null then continue; end if;
    today := (now() at time zone tz)::date;
    cfg := email_org_cfg(o.org_id, today);
    select count(*) filter (where result = 'sent' and (at at time zone tz)::date = today), count(*) filter (where result = 'sent' and at > now() - interval '1 hour')
      into used_day, used_hr from email_send_log where org_id = o.org_id and at > now() - interval '2 days';
    select count(*) into busy from email_queue where org_id = o.org_id and status = 'sending';
    room := least((cfg->>'daily_cap')::int - used_day - busy, (cfg->>'per_hour')::int - used_hr - busy, p_max - total, p_platform_left - total);
    continue when room <= 0;
    claimed := 0;
    for q in select * from email_queue where org_id = o.org_id and status = 'queued' and not_before <= now() order by requested_at, id limit 500 for update skip locked loop
      exit when claimed >= room;
      why := null; st := null; g := null; tok := null; nums := null; vars := null;
      if cfg->>'mode' = 'off' then why := 'email_off';
      elsif q.kind = 'receipt' and not (cfg->>'receipts')::boolean then why := 'receipts_off';
      elsif q.kind = 'reminder' and not (cfg#>>'{reminders,enabled}')::boolean then why := 'reminders_off';
      end if;
      if why is null and q.kind in ('invoice', 'late_fee', 'reminder') then
        st := email_invoice_state(q.org_id, q.invoice_id, today);
        if not (st->>'ok')::boolean then why := st->>'reason';
        elsif not (cfg->>'share_link')::boolean then why := 'no_link';
        end if;
      elsif why is null and q.kind = 'receipt' then
        select * into pay from centre_payments where id = q.payment_id and org_id = q.org_id;
        if pay.id is null then why := 'not_found';
        elsif exists (select 1 from centre_payments r where r.reverses_payment_id = pay.id and r.org_id = q.org_id) then why := 'reversed';
        end if;
      end if;
      if why is null then
        select * into g from guardians x where x.id = q.guardian_id and x.org_id = q.org_id;
        why := case when g.id is null then 'no_recipient' when not email_valid(g.email) then 'no_email' when g.email_status = 'bad' then 'bad_address' end;
      end if;
      if why is not null then
        update email_queue set status = case when why in ('no_recipient', 'no_email', 'bad_address') then 'skipped' else 'cancelled' end, reason = why, updated_at = now() where id = q.id;
        insert into email_send_log(org_id, queue_id, kind, invoice_id, guardian_id, to_masked, template, result, detail)
        values (q.org_id, q.id, q.kind, q.invoice_id, q.guardian_id, case when g.id is not null then email_mask(g.email) end, q.kind,
                case when why in ('no_recipient', 'no_email', 'bad_address') then 'skipped' else 'cancelled' end, why);
        continue;
      end if;
      select name into hname from households where id = q.household_id and org_id = q.org_id;
      cname := coalesce(cfg->>'centre_name', centre);
      if q.kind = 'receipt' then
        select string_agg(num, ', ' order by num), count(*) into nums, n_inv from (select distinct i.number_text num from centre_payment_allocations a
          join centre_invoices i on i.id = a.invoice_id and i.org_id = a.org_id where a.payment_id = pay.id and a.org_id = q.org_id limit 3) z;
        vars := jsonb_build_object('number', nums, 'amount_cents', pay.amount_cents, 'paid_on', pay.received_on);
      else
        tok := email_share_token(q.org_id, q.invoice_id, today);
        vars := jsonb_build_object('number', st->>'number', 'amount_cents', (st->>'balance_cents')::bigint, 'total_cents', (st->>'total_cents')::bigint, 'due_date', st->>'due_date',
                  'days_overdue', greatest(today - (st->>'due_date')::date, 0), 'token', tok);
      end if;
      tpl := cfg#>array['templates', q.kind];
      payload := jsonb_build_object('queue_id', q.id, 'org_id', q.org_id, 'kind', q.kind, 'attempt', q.attempts + 1, 'to', trim(g.email), 'name', coalesce(nullif(trim(g.name), ''), hname),
        'centre', cname, 'reply_to', cfg->>'reply_to', 'templates', case when jsonb_typeof(tpl) = 'object' then tpl else '{}'::jsonb end, 'vars', vars);
      update email_queue set status = 'sending', attempts = attempts + 1, updated_at = now() where id = q.id;
      res_list := res_list || payload; claimed := claimed + 1; total := total + 1;
    end loop;
  end loop;
  return res_list;
end $$;

-- The server reports what happened. outcome: sent | retry | failed | invalid | blocked_preview.   Only a message that is 'sending' can be completed (a second report does nothing).
create or replace function public.email_complete(p_queue uuid, p_outcome text, p_detail text default null, p_message_id text default null, p_to text default null, p_delay_minutes int default null)
returns boolean language plpgsql security definer set search_path = public as $$
declare q email_queue; res text; st text; delay int; tpl text; custom boolean := false; cfg jsonb;
begin
  if p_outcome not in ('sent', 'retry', 'failed', 'invalid', 'blocked_preview') then raise exception 'BAD_VALUE: unknown outcome' using errcode = 'P0001'; end if;
  select * into q from email_queue where id = p_queue and status = 'sending' for update;
  if q.id is null then return false; end if;
  cfg := email_org_cfg(q.org_id, coalesce(email_today(q.org_id), current_date));
  custom := coalesce(nullif(trim(cfg#>>array['templates', q.kind, 'subject']), ''), nullif(trim(cfg#>>array['templates', q.kind, 'body']), '')) is not null;
  tpl := q.kind || case when custom then ':custom' else '' end;
  if p_outcome = 'retry' and q.attempts >= 3 then p_outcome := 'failed'; p_detail := coalesce(left(p_detail, 60), 'error'); end if;
  if p_outcome = 'sent' then st := 'sent'; res := 'sent';
  elsif p_outcome = 'blocked_preview' then st := 'skipped'; res := 'blocked_preview'; p_detail := 'preview';
  elsif p_outcome = 'retry' then
    st := 'queued'; res := 'retry';
    delay := coalesce(p_delay_minutes, case q.attempts when 1 then 15 when 2 then 60 else 360 end);
  else
    st := 'failed'; res := 'failed';
    if p_outcome = 'invalid' then
      p_detail := 'invalid_recipient';
      update guardians set email_status = 'bad', email_bad_at = now() where id = q.guardian_id and org_id = q.org_id;
    end if;
  end if;
  update email_queue set status = st, reason = case when st = 'queued' then q.reason else left(coalesce(p_detail, q.reason), 60) end, updated_at = now(),
         not_before = case when st = 'queued' then now() + make_interval(mins => delay) else not_before end where id = q.id;
  insert into email_send_log(org_id, queue_id, kind, invoice_id, guardian_id, to_masked, template, result, detail, attempt, by_user, brevo_message_id)
  values (q.org_id, q.id, q.kind, q.invoice_id, q.guardian_id, email_mask(p_to), tpl, res, left(p_detail, 60), q.attempts, q.requested_by, left(p_message_id, 200));
  return true;
end $$;

-- Brevo tells us an address bounced / was blocked / was reported. Matches the message id; marks the guardian's address bad; adds a 'bounced' line to the log.
-- soft bounces and deferrals are only noted. Unknown ids do nothing.
create or replace function public.email_mark_bounce(p_message_id text, p_kind text) returns boolean
language plpgsql security definer set search_path = public as $$
declare l email_send_log; mid text := regexp_replace(coalesce(p_message_id, ''), '[<>\s]', '', 'g'); bad boolean;
begin
  if length(mid) < 6 then return false; end if;
  select * into l from email_send_log x where x.result = 'sent' and regexp_replace(coalesce(x.brevo_message_id, ''), '[<>\s]', '', 'g') = mid order by x.id desc limit 1;
  if l.id is null then return false; end if;
  bad := p_kind in ('hard_bounce', 'invalid', 'blocked', 'error', 'spam', 'complaint', 'unsubscribed');
  if bad and l.guardian_id is not null then
    update guardians set email_status = 'bad', email_bad_at = now() where id = l.guardian_id and org_id = l.org_id;
  end if;
  insert into email_send_log(org_id, queue_id, kind, invoice_id, guardian_id, to_masked, template, result, detail, brevo_message_id)
  values (l.org_id, l.queue_id, l.kind, l.invoice_id, l.guardian_id, l.to_masked, l.template, 'bounced', left(coalesce(p_kind, 'bounce'), 40), left(p_message_id, 200));
  return true;
end $$;

-- how many emails the platform sent in the last 24 hours (every centre, plus tutor invites): the server keeps this under Brevo's daily limit
create or replace function public.email_platform_sent_24h() returns int
language sql stable security definer set search_path = public as $$
  select ((select count(*) from email_send_log where result = 'sent' and at > now() - interval '24 hours')
        + (select count(*) from org_invite_mail_log where status = 'sent' and sent_at > now() - interval '24 hours'))::int
$$;

-- the centres the daily job has to look at: email switched on, or something still waiting in the queue
create or replace function public.email_active_orgs() returns table(org_id uuid)
language sql stable security definer set search_path = public as $$
  select o.id from organisations o
   where o.kind = 'centre' and o.status = 'active'
     and (email_org_cfg(o.id, (now() at time zone o.timezone)::date)->>'mode' <> 'off' or exists (select 1 from email_queue q where q.org_id = o.id and q.status = 'queued'))
   order by o.id
$$;

-- ---------------------------------------------------------------------------------------------------
-- 9. who may call what
-- ---------------------------------------------------------------------------------------------------
do $$
declare f text;
begin
  -- internal helpers and trigger functions: nobody from a browser
  foreach f in array array['email_valid(text)', 'email_mask(text)', 'email_cfg(jsonb)'] loop
    execute format('revoke all on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated, service_role', f);
  end loop;
  foreach f in array array['email_org_cfg(uuid,date)', 'email_today(uuid)', 'email_invoice_state(uuid,uuid,date)', 'email_share_token(uuid,uuid,date)',
    'email_enqueue_rows(uuid,text,uuid,uuid,uuid,uuid,boolean,int)', 'email_on_invoice_issued()', 'email_on_payment()'] loop
    execute format('revoke all on function public.%s from public, anon, authenticated', f);
  end loop;
  -- staff screens (each function starts with the gate)
  foreach f in array array['email_queue_status(uuid)', 'email_enqueue(uuid,uuid[],boolean)', 'email_enqueue_unsent(uuid,date)', 'email_queue_list(uuid,text,int,int)',
    'email_queue_cancel(uuid,uuid[])', 'email_log_list(uuid,int,bigint)', 'email_household_contacts(uuid,uuid)', 'email_set_billing_contacts(uuid,uuid,uuid[])',
    'email_clear_bad(uuid,uuid)', 'email_bad_list(uuid)', 'email_reminder_preview(uuid)'] loop
    execute format('revoke all on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated, service_role', f);
  end loop;
  -- the server only
  foreach f in array array['email_plan_reminders(uuid,boolean)', 'email_claim(uuid,int,int)', 'email_complete(uuid,text,text,text,text,int)', 'email_mark_bounce(text,text)',
    'email_platform_sent_24h()', 'email_active_orgs()'] loop
    execute format('revoke all on function public.%s from public, anon, authenticated', f);
    execute format('grant execute on function public.%s to service_role', f);
  end loop;
end $$;

-- #####################################################################################################
-- ### PART 6 of 7 — make-up credits: owed list, booking, expiry, invoice skip
-- ### source branch: claude/t18-4-makeup-credits   file: db/migration_makeup_credits.sql   undo: db/migration_makeup_credits_down.sql
-- ### (if an error appears, search this file for the nearest "### PART" line above the error line: that is the part that failed)
-- #####################################################################################################
-- =====================================================================================================
-- T18 step 4 — MAKE-UP CREDITS for centres                                              undo: migration_makeup_credits_down.sql
-- =====================================================================================================
-- Needs everything before it, in this order: ... slot_changes (lesson_change_blocker, holidays, staff_holiday_cancel), tutor_moves (the settings
-- validator this file replaces, tutor_cancel_lesson). Run it LAST of the current migrations. Safe to run twice. DEV first; LIVE only when the code ships.
--
-- THE RULE (owner decisions, T18, 2026-11-24..27): ONE MISSED LESSON = ONE CREDIT, and a make-up lesson is NEVER charged twice.
--   A credit is earned when a centre lesson is missed in a way the centre has chosen to credit. It is spent by BOOKING a make-up lesson (an ordinary
--   one-off lesson linked to the credit) and used up when somebody MARKS ATTENDANCE on that make-up. Taking the make-up away (unbook) gives the credit back.
--   Solo tutors are untouched: every function below refuses a solo organisation, and the triggers do nothing for one.
--
-- THE CENTRE'S CHOICES (saved under settings.billing; read as of the centre's TODAY, they are process rules; the price rule is frozen on the lesson):
--   billing.credits.rule              none (default when the key is missing: nothing changes for a centre that saved settings before) | one_per_missed
--   billing.credits.earn_absences     notice_only (default: marked "cancelled in time") | notice_and_late (+ late cancelled) | all_missed (+ absent) | none
--   billing.credits.earn_tutor_cancel staff_decide (default: a tutor's own cancel earns NOTHING, staff grant one if they decide) | automatic
--   billing.credits.earn_holiday      false (default) | true: a lesson cancelled for a whole-centre holiday (staff_holiday_cancel) earns a credit
--   billing.credit_expiry_days        0 = never (default) .. 3650. Fixed on the credit the day it is earned: expires_on = earned_on + days, usable THROUGH that day
--   billing.credits.grant_by          manage_timetable (default) | owner: who may grant and revoke a credit by hand
--   billing.credits.book_by           manage_timetable (default) | owner: who may book and unbook the make-up lesson
--   billing.credits.makeup_price      free (default) | if_missed_not_charged
--        free                         the make-up is never billed (the missed lesson was billed or waived already)
--        if_missed_not_charged        the make-up is billed at its normal price ONLY when the missed lesson was NOT charged (compensation 0); when the
--                                     missed lesson was charged, the make-up is free: the family never pays twice. A credit with no missed lesson (a
--                                     manual grant) books at the normal price. Booking is refused (CHARGE_PENDING) while the missed lesson's charge is still untyped.
--   Tutors never see credits or money: no tutor function is added or changed and tutors have no table access.
--
-- WHAT IS KEPT (tables are read ONLY through the functions below: row-level security is on with no policy, and browsers have no table privileges)
--   makeup_credits         one row per credit: who, why (source: absence | tutor_cancel | holiday | manual), the missed lesson, earned_on, expires_on,
--                          status open | booked | used | expired | revoked. Only `status` ever changes, only by the functions here; never deleted
--                          (except while a whole organisation is removed). ONE credit per missed lesson, ever (unique index): marking twice earns once.
--   makeup_credit_events   append-only history: earned, booked, returned, used, expired, revoked (who, when, which lesson, why). A superset of the owner's
--                          five (earned, used, returned, expired, revoked): `booked` records the link, `used` the attendance mark. Simple columns, ready to export.
--   lessons.makeup_credit_id / makeup_billing   the make-up lesson's link to its credit (one credit, one lesson: unique) and how it is billed (free | normal).
--                          Written only by the functions here (a trigger refuses anyone else), so nobody can mark a normal lesson "free" to dodge billing.
--   audit_log              one row per grant, revoke, book, unbook, earn, use and expiry.
--
-- INVOICING: centre_invoice_run_rows is replaced (the same function, one added line): a lesson with makeup_billing = 'free' is never put on an invoice.
--   (lesson_price_cents treats amount 0 as "not set" and falls back to rate x hours, so a free make-up can't rely on a zero amount: it is skipped by flag.)
--
-- WHO MAY CALL (same words as the other staff screens): an active OWNER or STAFF member of this centre may LOOK; GRANT / REVOKE and BOOK / UNBOOK need
--   manage_timetable (owners always) or the owner only, per the two settings above. A tutor / parent / switched-off staff / stranger / solo organisation /
--   unknown id all get the same NOT_FOUND, so ids can't be probed. The Supabase API refuses a DELETE or UPDATE with no WHERE: every statement here has one.
-- =====================================================================================================

-- ---------------------------------------------------------------- 1. the two tables
create table if not exists public.makeup_credits (
  id               uuid primary key default gen_random_uuid(),
  org_id           uuid not null references public.organisations(id) on delete cascade,
  student_id       uuid not null,
  source           text not null check (source in ('absence', 'tutor_cancel', 'holiday', 'manual')),
  source_lesson_id uuid,
  reason           text check (reason is null or char_length(reason) between 3 and 300),
  earned_on        date not null,
  expires_on       date,
  status           text not null default 'open' check (status in ('open', 'booked', 'used', 'expired', 'revoked')),
  created_by       uuid,
  created_at       timestamptz not null default now(),
  constraint makeup_credits_student_same_org foreign key (student_id, org_id) references public.students(id, org_id),
  constraint makeup_credits_lesson_same_org  foreign key (source_lesson_id, org_id) references public.lessons(id, org_id) on delete set null (source_lesson_id),
  constraint makeup_credits_manual_has_reason check (source <> 'manual' or reason is not null),
  constraint makeup_credits_expiry_after_earned check (expires_on is null or expires_on >= earned_on)
);
create unique index if not exists makeup_credits_one_per_lesson on public.makeup_credits(source_lesson_id) where source_lesson_id is not null;
create index if not exists makeup_credits_org_status on public.makeup_credits(org_id, status, earned_on);
create index if not exists makeup_credits_student on public.makeup_credits(org_id, student_id, status);
create index if not exists makeup_credits_expiry on public.makeup_credits(expires_on) where status = 'open' and expires_on is not null;
create unique index if not exists makeup_credits_id_org on public.makeup_credits(id, org_id);

create table if not exists public.makeup_credit_events (
  id        bigint generated always as identity primary key,
  org_id    uuid not null references public.organisations(id) on delete cascade,
  credit_id uuid not null references public.makeup_credits(id) on delete cascade,
  kind      text not null check (kind in ('earned', 'booked', 'returned', 'used', 'expired', 'revoked')),
  lesson_id uuid,                                  -- the make-up lesson for booked / returned / used (no foreign key: the lesson may be deleted later)
  actor     uuid,                                  -- null = the system (expiry job)
  reason    text,
  at        timestamptz not null default now()
);
create index if not exists makeup_credit_events_credit on public.makeup_credit_events(credit_id, at);
create index if not exists makeup_credit_events_org on public.makeup_credit_events(org_id, at desc);

-- nobody reaches the tables from a browser: row-level security on with no policy, and no table privileges for the browser roles
alter table public.makeup_credits enable row level security;
alter table public.makeup_credit_events enable row level security;
revoke all on public.makeup_credits from public, anon, authenticated;
revoke all on public.makeup_credit_events from public, anon, authenticated;

-- append-only. A credit's ONLY change is `status`, and only while a function of this file holds the flag td.credit_write; the other allowed change is the
-- foreign key emptying source_lesson_id when the missed lesson itself is deleted. Deletes only while a whole organisation is being removed (td.deleting_org).
create or replace function public.makeup_credits_guard() returns trigger language plpgsql set search_path = public as $$
declare gate text := coalesce(current_setting('td.deleting_org', true), '');
begin
  if tg_op = 'DELETE' then
    if gate <> '' and gate = old.org_id::text and current_user not in ('anon', 'authenticated', 'service_role') then return old; end if;
    raise exception 'makeup_credits is append-only';
  end if;
  if coalesce(current_setting('td.credit_write', true), '') = 'on'
     and (to_jsonb(new) - 'status') = (to_jsonb(old) - 'status') then return new; end if;
  if old.source_lesson_id is not null and new.source_lesson_id is null
     and (to_jsonb(new) - 'source_lesson_id') = (to_jsonb(old) - 'source_lesson_id') then return new; end if;
  raise exception 'makeup_credits is append-only';
end $$;
drop trigger if exists makeup_credits_immutable on public.makeup_credits;
create trigger makeup_credits_immutable before update or delete on public.makeup_credits for each row execute function public.makeup_credits_guard();

create or replace function public.makeup_credit_events_guard() returns trigger language plpgsql set search_path = public as $$
declare gate text := coalesce(current_setting('td.deleting_org', true), '');
begin
  if tg_op = 'DELETE' and gate <> '' and gate = old.org_id::text and current_user not in ('anon', 'authenticated', 'service_role') then return old; end if;
  raise exception 'makeup_credit_events is append-only';
end $$;
drop trigger if exists makeup_credit_events_immutable on public.makeup_credit_events;
create trigger makeup_credit_events_immutable before update or delete on public.makeup_credit_events for each row execute function public.makeup_credit_events_guard();

-- ---------------------------------------------------------------- 2. the make-up lesson's link (on lessons)
alter table public.lessons add column if not exists makeup_credit_id uuid;
alter table public.lessons add column if not exists makeup_billing   text;
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'lessons_makeup_billing_ok') then
    alter table public.lessons add constraint lessons_makeup_billing_ok check (makeup_billing is null or makeup_billing in ('free', 'normal'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'lessons_makeup_credit_same_org') then
    alter table public.lessons add constraint lessons_makeup_credit_same_org
      foreign key (makeup_credit_id, org_id) references public.makeup_credits(id, org_id) on delete set null (makeup_credit_id);
  end if;
end $$;
create unique index if not exists lessons_one_per_credit on public.lessons(makeup_credit_id) where makeup_credit_id is not null;

-- only the functions of this file may set, change or clear the link or the billing flag (a person with table access could otherwise tag a normal lesson
-- "free" to dodge billing, or untag a make-up to bill it twice, or point it at somebody else's credit)
create or replace function public.lessons_makeup_guard() returns trigger language plpgsql set search_path = public as $$
declare gate text := coalesce(current_setting('td.deleting_org', true), '');
begin
  if coalesce(current_setting('td.credit_write', true), '') = 'on' then return new; end if;
  if gate <> '' and gate = new.org_id::text and current_user not in ('anon', 'authenticated', 'service_role') then return new; end if;
  if tg_op = 'INSERT' then
    if new.makeup_credit_id is not null or new.makeup_billing is not null then
      raise exception 'LOCKED: a make-up lesson is made by booking a credit' using errcode = 'P0001'; end if;
    return new;
  end if;
  if new.makeup_credit_id is distinct from old.makeup_credit_id or new.makeup_billing is distinct from old.makeup_billing then
    raise exception 'LOCKED: a make-up lesson''s credit link can''t be edited by hand' using errcode = 'P0001'; end if;
  return new;
end $$;
drop trigger if exists lessons_makeup_guard on public.lessons;
create trigger lessons_makeup_guard before insert or update of makeup_credit_id, makeup_billing on public.lessons for each row execute function public.lessons_makeup_guard();

-- ---------------------------------------------------------------- 3. the settings validator (tutor_moves' version, plus the new keys at the end)
-- Every earlier check is kept word for word. Settings saved before this still pass (every new key is optional).
create or replace function public.org_validate_settings(s jsonb) returns void language plpgsql immutable set search_path = public as $$
declare k text; v jsonb; r record; bs text; tp text;
begin
  if coalesce((s->>'schema_version')::int, 0) <> 1 then raise exception 'Unknown settings schema_version'; end if;
  foreach k in array array['profile','calendar','billing','invoicing','payments','lessons','tutor_pay','data'] loop
    if jsonb_typeof(s->k) is distinct from 'object' then raise exception 'Settings section "%" is missing', k; end if;
  end loop;
  if (s#>>'{profile,gst_registered}')::boolean and not ((s#>>'{profile,gst_rate_bp}')::int between 0 and 5000) then
    raise exception 'GST rate must be between 0%% and 50%%'; end if;
  if s#>>'{billing,model}' not in ('prepaid_packages','fixed_in_advance','postpaid_lessons','pay_per_lesson') then
    raise exception 'Unknown billing model'; end if;
  if s#>>'{tutor_pay,mode}' not in ('off','report','full') then raise exception 'Unknown tutor pay mode'; end if;
  if s#>>'{tutor_pay,payable_when}' not in ('taught','parent_paid') then raise exception 'Unknown payable rule'; end if;
  if s#>>'{invoicing,grouping}' not in ('family','student') then raise exception 'Unknown invoice grouping'; end if;
  if s#>>'{lessons,attendance_by}' not in ('tutor','admin') then raise exception 'Unknown attendance setting'; end if;
  if s#>>'{lessons,cancellations_marked_by}' not in ('admin','tutor') then raise exception 'Unknown cancellation setting'; end if;
  if s#>>'{lessons,compensation_entered_by}' not in ('admin','tutor') then raise exception 'Unknown compensation setting'; end if;
  if s#>>'{lessons,trials_flagged_by}' not in ('admin','tutor') then raise exception 'Unknown trial setting'; end if;
  if s#>>'{lessons,attendance_window_days}' is not null and (s#>>'{lessons,attendance_window_days}' !~ '^[0-9]{1,3}$'
     or (s#>>'{lessons,attendance_window_days}')::int not between 1 and 60) then raise exception 'Attendance window must be 1-60 days'; end if;
  if not (s#>'{payments,modes}' ?| array['manual_paynow','statement_matching','hitpay','stripe']) then
    raise exception 'Pick at least one way for parents to pay'; end if;
  -- T4 S0 (centre money options). Every new key is optional, so settings saved before this migration stay valid;
  -- a key that is present must be right. assets/js/org-settings.js holds the labels and defaults (tests/org-settings.test.js compares the enums).
  if s#>>'{tutor_pay,rate_model}' is not null and s#>>'{tutor_pay,rate_model}' not in ('per_lesson','per_hour','per_student_lesson','monthly_fixed','percent_of_fee') then raise exception 'Unknown tutor pay rate'; end if;
  if s#>>'{tutor_pay,percent_base}' is not null and s#>>'{tutor_pay,percent_base}' not in ('billed_after_discounts','list_price') then raise exception 'Unknown percentage pay base'; end if;
  if s#>>'{tutor_pay,part_payments}' is not null and s#>>'{tutor_pay,part_payments}' not in ('after_full','pro_rata') then raise exception 'Unknown part-payment pay rule'; end if;
  if s#>>'{tutor_pay,cancelled_lessons}' is not null and s#>>'{tutor_pay,cancelled_lessons}' not in ('pay_if_charged','pay_rate','pay_nothing') then raise exception 'Unknown cancelled-lesson pay rule'; end if;
  if s#>>'{tutor_pay,group_count}' is not null and s#>>'{tutor_pay,group_count}' not in ('attended','enrolled') then raise exception 'Unknown group pay count'; end if;
  if s#>>'{billing,deposit,mode}' is not null and s#>>'{billing,deposit,mode}' not in ('none','fixed','percent_first_month') then raise exception 'Unknown deposit mode'; end if;
  if s#>>'{billing,deposit,due}' is not null and s#>>'{billing,deposit,due}' not in ('with_first_invoice','before_first_lesson') then raise exception 'Unknown deposit due rule'; end if;
  if s#>>'{billing,deposit,waived_by}' is not null and s#>>'{billing,deposit,waived_by}' not in ('owner','issue_invoices','nobody') then raise exception 'Unknown deposit waiver rule'; end if;
  if s#>>'{billing,deposit,release}' is not null and s#>>'{billing,deposit,release}' not in ('refund_full','refund_less_unpaid','admin_decides') then raise exception 'Unknown deposit release rule'; end if;
  if s#>>'{billing,deposit,refund_approved_by}' is not null and s#>>'{billing,deposit,refund_approved_by}' not in ('owner','staff','four_eyes') then raise exception 'Unknown deposit refund approver'; end if;
  if s#>>'{billing,late_fee,repeat}' is not null and s#>>'{billing,late_fee,repeat}' not in ('none','once','monthly') then raise exception 'Unknown late fee repeat'; end if;
  if s#>>'{billing,late_fee,type}' is not null and s#>>'{billing,late_fee,type}' not in ('fixed','percent') then raise exception 'Unknown late fee type'; end if;
  if s#>>'{billing,late_fee,show_as}' is not null and s#>>'{billing,late_fee,show_as}' not in ('next_invoice_line','own_invoice') then raise exception 'Unknown late fee placement'; end if;
  if s#>>'{billing,late_fee,waived_by}' is not null and s#>>'{billing,late_fee,waived_by}' not in ('owner','issue_invoices') then raise exception 'Unknown late fee waiver rule'; end if;
  if s#>>'{lessons,class_type}' is not null and s#>>'{lessons,class_type}' not in ('one_to_one','group','both') then raise exception 'Unknown class type'; end if;
  foreach k in array array['{billing,deposit,taxable}','{billing,deposit,top_up}','{billing,deposit,set_off_unpaid}','{billing,deposit,final_month}','{billing,trials,charged}'] loop
    v := s #> k::text[];
    if v is not null and jsonb_typeof(v) not in ('boolean','null') then raise exception 'Setting % must be yes or no', k; end if;
  end loop;
  for r in select * from (values
    ('{billing,deposit,percent_bp}', 0, 10000, 'Deposit percentage must be between 0% and 100%'),
    ('{billing,deposit,forfeit_notice_days}', 0, 90, 'Deposit notice must be 0-90 days'),
    ('{billing,late_fee,percent_bp}', 0, 10000, 'Late fee percentage must be between 0% and 100%'),
    ('{billing,late_fee,after_days}', 0, 365, 'Late fee grace period must be 0-365 days'),
    ('{billing,late_fee,cap_cents}', 0, 100000000, 'Late fee limit must be a whole number of cents, 0 to 100000000'),
    ('{billing,late_fee,amount_cents}', 0, 100000000, 'Late fee amount must be a whole number of cents, 0 to 100000000'),
    ('{billing,one_off_fees,deposit_cents}', 0, 100000000, 'Deposit amount must be a whole number of cents, 0 to 100000000'),
    ('{profile,next_invoice_number}', 1, 999999999, 'Next invoice number must be a whole number, 1 or more')
  ) as c(p, lo, hi, msg) loop
    v := s #> r.p::text[];
    if v is not null and jsonb_typeof(v) <> 'null' and not (case when jsonb_typeof(v) = 'number' and v::text ~ '^[0-9]{1,12}$'
         then (v#>>'{}')::bigint between r.lo and r.hi else false end) then
      raise exception '%', r.msg; end if;
  end loop;
  -- a percentage mode needs a real percentage (1 = 0.01%)
  if s#>>'{billing,deposit,mode}' = 'percent_first_month' and coalesce((s#>>'{billing,deposit,percent_bp}')::int, 0) < 1 then
    raise exception 'Deposit percentage must be between 0.01%% and 100%%'; end if;
  if s#>>'{billing,late_fee,type}' = 'percent' and coalesce((s#>>'{billing,late_fee,percent_bp}')::int, 0) < 1 then
    raise exception 'Late fee percentage must be between 0.01%% and 100%%'; end if;
  -- T6 step 2 (tutors change their own lessons). Every key is optional; a key that is present must be right. assets/js/org-settings.js has the labels and defaults.
  if s#>>'{lessons,timetable_editing}' is not null and s#>>'{lessons,timetable_editing}' not in ('admin_only','tutors_direct','tutors_propose') then raise exception 'Unknown timetable editing setting'; end if;
  if s#>>'{lessons,notify_family}' is not null and s#>>'{lessons,notify_family}' not in ('off','list_for_admin') then raise exception 'Unknown family notice setting'; end if;
  if s#>'{lessons,tutors_edit}' is not null and jsonb_typeof(s#>'{lessons,tutors_edit}') not in ('object','null') then raise exception 'Tutor editing switches are malformed'; end if;
  foreach k in array array['{lessons,tutors_edit,postpone}','{lessons,tutors_edit,cancel}','{lessons,tutors_edit,weekly_slots}','{lessons,tutors_edit,generate}','{lessons,tutors_edit,one_off}','{lessons,tutors_edit,link}'] loop
    v := s #> k::text[];
    if v is not null and jsonb_typeof(v) not in ('boolean','null') then raise exception 'Setting % must be yes or no', k; end if;
  end loop;
  for r in select * from (values
    ('{lessons,min_notice_hours}', 0, 168, 'Notice before a change must be 0-168 hours'),
    ('{lessons,max_changes_per_month}', 0, 500, 'Changes per tutor per month must be 0-500 (0 = no limit)')
  ) as c(p, lo, hi, msg) loop
    v := s #> r.p::text[];
    if v is not null and jsonb_typeof(v) <> 'null' and not (case when jsonb_typeof(v) = 'number' and v::text ~ '^[0-9]{1,4}$'
         then (v#>>'{}')::bigint between r.lo and r.hi else false end) then
      raise exception '%', r.msg; end if;
  end loop;
  -- billing starts from: empty, or a real date between 2020-01-01 and 2100-01-01
  if s#>'{billing,starts_from}' is not null and jsonb_typeof(s#>'{billing,starts_from}') <> 'null' then
    if jsonb_typeof(s#>'{billing,starts_from}') <> 'string' then raise exception 'Billing start must be a date'; end if;
    bs := s#>>'{billing,starts_from}';
    if bs <> '' then
      if bs !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then raise exception 'Billing start must be a date (YYYY-MM-DD)'; end if;
      begin perform make_date(substr(bs,1,4)::int, substr(bs,6,2)::int, substr(bs,9,2)::int);
      exception when others then raise exception 'Billing start must be a real date'; end;
      if bs < '2020-01-01' or bs > '2100-01-01' then raise exception 'Billing start must be between 2020 and 2100'; end if;
    end if;
  end if;
  -- T7.3 (invoice, receipt and reminder emails to families). Every key is optional; a key that is present must be right. assets/js/org-settings.js has the labels and
  -- defaults and assets/js/invoice-email-core.js the placeholder list (tests/org-settings.test.js and tests/invoice-email-core.test.js compare them with this).
  if s#>'{email}' is not null and jsonb_typeof(s#>'{email}') not in ('object','null') then raise exception 'Email settings are malformed'; end if;
  if s#>>'{email,mode}' is not null and s#>>'{email,mode}' not in ('off','staff_send','auto_on_issue') then raise exception 'Unknown email sending setting'; end if;
  foreach k in array array['{email,receipts}','{email,late_fee_notice}','{email,reminders,enabled}'] loop
    v := s #> k::text[];
    if v is not null and jsonb_typeof(v) not in ('boolean','null') then raise exception 'Setting % must be yes or no', k; end if;
  end loop;
  for r in select * from (values
    ('{email,reminders,first_after_days}', 1, 90, 'Send the first reminder 1-90 days after the due date'),
    ('{email,reminders,repeat_days}', 0, 90, 'Repeat reminders every 0-90 days (0 = only one reminder)'),
    ('{email,reminders,max_count}', 1, 10, 'Send 1-10 reminders at most'),
    ('{email,daily_cap}', 1, 300, 'Emails per day must be 1-300'),
    ('{email,per_hour}', 1, 300, 'Emails per hour must be 1-300')
  ) as c(p, lo, hi, msg) loop
    v := s #> r.p::text[];
    if v is not null and jsonb_typeof(v) <> 'null' and not (case when jsonb_typeof(v) = 'number' and v::text ~ '^[0-9]{1,4}$'
         then (v#>>'{}')::bigint between r.lo and r.hi else false end) then
      raise exception '%', r.msg; end if;
  end loop;
  -- the wording: plain text, a limited set of fields in {braces}
  if s#>'{email,templates}' is not null and jsonb_typeof(s#>'{email,templates}') not in ('object','null') then raise exception 'Email wording is malformed'; end if;
  foreach k in array array['invoice','receipt','reminder','late_fee'] loop
    foreach tp in array array['subject','body'] loop
      v := s #> array['email','templates',k,tp];
      if v is not null and jsonb_typeof(v) <> 'null' then
        if jsonb_typeof(v) <> 'string' then raise exception 'Email wording must be text'; end if;
        if length(v#>>'{}') > (case tp when 'subject' then 120 else 1000 end) then raise exception 'Email wording is too long (subject 120, message 1000 characters)'; end if;
        if regexp_replace(v#>>'{}', '\{(name|centre|number|amount|due_date|link|contact|paid_on|days_overdue)\}', '', 'g') ~ '[{}]' then
          raise exception 'Email wording can only use {name} {centre} {number} {amount} {due_date} {link} {contact} {paid_on} {days_overdue}'; end if;
      end if;
    end loop;
  end loop;
  if s#>>'{email,mode}' is not null and s#>>'{email,mode}' <> 'off' and coalesce((s#>>'{invoicing,delivery,share_link}')::boolean, true) = false then
    raise exception 'Emailing invoices needs the shareable invoice link switched on'; end if;
  if nullif(trim(coalesce(s#>>'{profile,reply_to_email}', '')), '') is not null and trim(s#>>'{profile,reply_to_email}') !~ '^[^@\s<>,;]+@[^@\s<>,;]+\.[^@\s<>,;]+$' then
    raise exception 'The reply-to email address doesn''t look right'; end if;
  -- T18 step 4 (make-up credits). Every key is optional; a key that is present must be right. assets/js/org-settings.js has the labels and defaults.
  if s#>>'{billing,credits,rule}' is not null and s#>>'{billing,credits,rule}' not in ('none','one_per_missed') then raise exception 'Unknown make-up credit rule'; end if;
  if s#>>'{billing,credits,earn_absences}' is not null and s#>>'{billing,credits,earn_absences}' not in ('none','notice_only','notice_and_late','all_missed') then raise exception 'Unknown rule for credits from absences'; end if;
  if s#>>'{billing,credits,earn_tutor_cancel}' is not null and s#>>'{billing,credits,earn_tutor_cancel}' not in ('staff_decide','automatic') then raise exception 'Unknown rule for credits from tutor cancellations'; end if;
  if s#>>'{billing,credits,grant_by}' is not null and s#>>'{billing,credits,grant_by}' not in ('manage_timetable','owner') then raise exception 'Unknown rule for who grants credits'; end if;
  if s#>>'{billing,credits,book_by}' is not null and s#>>'{billing,credits,book_by}' not in ('manage_timetable','owner') then raise exception 'Unknown rule for who books make-ups'; end if;
  if s#>>'{billing,credits,makeup_price}' is not null and s#>>'{billing,credits,makeup_price}' not in ('free','if_missed_not_charged') then raise exception 'Unknown make-up price rule'; end if;
  v := s #> '{billing,credits,earn_holiday}';
  if v is not null and jsonb_typeof(v) not in ('boolean','null') then raise exception 'Setting {billing,credits,earn_holiday} must be yes or no'; end if;
  v := s #> '{billing,credit_expiry_days}';
  if v is not null and jsonb_typeof(v) <> 'null' and not (case when jsonb_typeof(v) = 'number' and v::text ~ '^[0-9]{1,4}$' then (v#>>'{}')::bigint between 0 and 3650 else false end) then
    raise exception 'Credits must expire after 0-3650 days (0 = never)'; end if;
end $$;

-- ---------------------------------------------------------------- 3b. the invoice run (centre_invoice_run_rows, one added line: a free make-up is never billed)
create or replace function public.centre_invoice_run_rows(p_org uuid, p_month date, p_today date)
returns table(unit_key text, household_id uuid, unit_student uuid, unit_name text, student_id uuid, student_name text,
              state text, line_kind text, ord int, lesson_id uuid, lesson_date date, start_time time,
              description text, qty int, unit_cents bigint, ref_id uuid)
language plpgsql stable security definer set search_path = public as $$
#variable_conflict use_column
declare ms date := date_trunc('month', p_month)::date; me date := (date_trunc('month', p_month) + interval '1 month - 1 day')::date;
  s jsonb; v_post boolean; v_stu boolean; v_trials boolean; v_sib text; v_sib_bp bigint; v_sib_fix bigint; v_reg bigint; v_mat bigint; v_pct text;
begin
  s := coalesce(org_settings_on(p_org, ms), org_settings_on(p_org, p_today));
  if s is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  v_post   := coalesce(s#>>'{billing,model}', 'postpaid_lessons') = 'postpaid_lessons';
  v_stu    := coalesce(s#>>'{invoicing,grouping}', 'family') = 'student';
  v_trials := coalesce((s#>>'{billing,trials,charged}')::boolean, false);
  v_sib    := coalesce(s#>>'{billing,sibling_discount,type}', 'none');
  v_sib_bp := coalesce((s#>>'{billing,sibling_discount,percent_bp}')::bigint, 0);
  v_sib_fix:= coalesce((s#>>'{billing,sibling_discount,fixed_cents}')::bigint, 0);
  v_reg    := coalesce((s#>>'{billing,one_off_fees,registration_cents}')::bigint, 0);
  v_mat    := coalesce((s#>>'{billing,one_off_fees,materials_cents}')::bigint, 0);
  v_pct    := regexp_replace(to_char(v_sib_bp / 100.0, 'FM990.00'), '\.?0+$', '');

  return query
  with base as (                                   -- the month's lessons that are not already on a draft or issued document
    select l.id as lid, l.student_id as sid, l.lesson_date as ldate, l.start_time as stime, l.subject as subj,
           l.status as lstatus, l.attendance as att, l.trial as is_trial, l.compensation_cents as comp, l.price_pending as ppend,
           lesson_price_cents(l.amount, l.rate, l.start_time, l.end_time) as price
      from lessons l
     where l.org_id = p_org and l.lesson_date between ms and me
       and l.makeup_billing is distinct from 'free'            -- T18-4: a make-up booked free is never billed (its missed lesson was already billed, or waived by the centre's choice)
       and not exists (select 1 from centre_invoice_lines cl join centre_invoices ci on ci.id = cl.invoice_id and ci.org_id = cl.org_id
                        where cl.lesson_id = l.id and cl.org_id = p_org and ci.status <> 'void')
  ), cls as (
    select b.*,
      case
        when b.is_trial and not v_trials then 'free_trial'
        when b.ppend and b.lstatus <> 'cancelled' then 'pending'             -- T6 step 3: a tutor-made lesson whose price the centre has not confirmed yet
        when v_post and b.att in ('absent', 'cancelled_early', 'late_cancelled') and b.comp is null then 'pending'
        when b.lstatus = 'done' or (not v_post and b.lstatus = 'scheduled') then case when b.price > 0 then 'line' else 'no_price' end
        when v_post and b.lstatus = 'cancelled' and coalesce(b.comp, 0) > 0 then 'line'
        when v_post and b.lstatus = 'scheduled' and b.ldate < p_today then 'unmarked'
        else 'skip' end as st,
      case when b.lstatus = 'cancelled' then b.comp else b.price end as cents
      from base b
  ), keyed as (
    select c.*, st8.name as sname, st8.household_id as hid, st8.created_at as screated,
           case when v_stu then c.sid::text else coalesce(st8.household_id::text, c.sid::text) end as ukey,
           case when v_stu or st8.household_id is null then c.sid end as ustu,
           case when v_stu then st8.name else coalesce(h.name, st8.name) end as uname
      from cls c
      join students st8 on st8.id = c.sid and st8.org_id = p_org
      left join households h on h.id = st8.household_id and h.org_id = p_org
     where c.st <> 'skip'
  ), billed as (select * from keyed where st = 'line'),
  stu as (                                          -- per child billed in this run
    select b.sid, b.hid, min(b.screated) as screated, sum(b.cents)::bigint as total, sum(least(v_sib_fix, b.cents))::bigint as fixed_off,
           bool_or(not b.is_trial) as any_nontrial,
           (array_agg(b.ukey))[1] as ukey, (array_agg(b.ustu))[1] as ustu, (array_agg(b.uname))[1] as uname, (array_agg(b.sname))[1] as sname
      from billed b group by b.sid, b.hid
  ), ranked as (
    select st.*, case when st.hid is null then 1 else row_number() over (partition by st.hid order by st.screated, st.sid) end as rn from stu st
  ), disc as (
    select r.*, case v_sib when 'percent' then least(r.total, centre_div_round(r.total * v_sib_bp, 10000))
                           when 'fixed'   then least(r.total, r.fixed_off) else 0 end as off
      from ranked r where r.rn >= 2
  )
  select b.ukey, b.hid, b.ustu, b.uname, b.sid, b.sname, 'line'::text, 'lesson'::text, 0, b.lid, b.ldate, b.stime,
         left(coalesce(nullif(trim(b.subj), ''), 'Lesson'), 60) || case when b.lstatus = 'cancelled' then ' (cancelled, charged)' else '' end
           || ' · ' || to_char(b.ldate, 'Dy DD Mon') || ', ' || to_char(b.stime, 'FMHH12:MIam'),
         1, b.cents, null::uuid
    from billed b
  union all                                         -- signals the screen explains (no money on them)
  select k.ukey, k.hid, k.ustu, k.uname, k.sid, k.sname, k.st, 'lesson', 0, k.lid, k.ldate, k.stime, null::text, 1, 0::bigint, null::uuid
    from keyed k where k.st in ('pending', 'unmarked', 'no_price', 'free_trial')
  union all
  select d.ukey, d.hid, d.ustu, d.uname, d.sid, d.sname, 'line', 'sibling_discount', 1, null::uuid, null::date, null::time,
         case v_sib when 'percent' then 'Sibling discount (' || v_pct || '%)' else 'Sibling discount (S$' || to_char(v_sib_fix / 100.0, 'FM999990.00') || ' off each lesson)' end,
         1, -d.off, null::uuid
    from disc d where d.off > 0
  union all
  select r.ukey, r.hid, r.ustu, r.uname, r.sid, r.sname, 'line', k.kind, case k.kind when 'registration' then 2 else 3 end, null::uuid, null::date, null::time,
         case k.kind when 'registration' then 'Registration fee' else 'Materials fee' end, 1, k.amt, null::uuid
    from stu r cross join lateral (values ('registration', v_reg), ('materials', v_mat)) k(kind, amt)
   where r.any_nontrial and k.amt > 0
     and not exists (select 1 from centre_invoice_lines fl join centre_invoices fi on fi.id = fl.invoice_id and fi.org_id = fl.org_id
                      where fl.org_id = p_org and fl.student_id = r.sid and fl.fee_kind = k.kind and fi.status <> 'void')
  union all                                         -- a draft already exists for this household / student and month
  select coalesce(ci.student_id::text, ci.household_id::text), ci.household_id, ci.student_id,
         case when v_stu then sd.name else coalesce(hd.name, sd.name) end, ci.student_id, sd.name, 'draft_exists', 'invoice', 0,
         null::uuid, null::date, null::time, null::text, 1, ci.total_cents, ci.id
    from centre_invoices ci
    left join households hd on hd.id = ci.household_id and hd.org_id = ci.org_id
    left join students sd on sd.id = ci.student_id and sd.org_id = ci.org_id
   where ci.org_id = p_org and ci.kind = 'lesson' and ci.status = 'draft' and ci.period_start = ms;
end $$;

-- ---------------------------------------------------------------- 4. internal helpers (no browser role may call these)
-- the centre's own settings as of today, with the credit keys read once
create or replace function public.credit_cfg(p_org uuid, p_today date) returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'rule',              coalesce(s #>> '{billing,credits,rule}', 'none'),
    'earn_absences',     coalesce(s #>> '{billing,credits,earn_absences}', 'notice_only'),
    'earn_tutor_cancel', coalesce(s #>> '{billing,credits,earn_tutor_cancel}', 'staff_decide'),
    'earn_holiday',      coalesce((s #>> '{billing,credits,earn_holiday}')::boolean, false),
    'grant_by',          coalesce(s #>> '{billing,credits,grant_by}', 'manage_timetable'),
    'book_by',           coalesce(s #>> '{billing,credits,book_by}', 'manage_timetable'),
    'makeup_price',      coalesce(s #>> '{billing,credits,makeup_price}', 'free'),
    'expiry_days',       coalesce(nullif(s #>> '{billing,credit_expiry_days}', '')::int, 0))
    from (select org_settings_on(p_org, p_today) as s) x $$;

-- the one place that writes a credit event and its audit row (the caller holds td.credit_write for status changes)
create or replace function public.credit_event(p_credit uuid, p_kind text, p_lesson uuid, p_reason text) returns void
language plpgsql security definer set search_path = public as $$
declare c makeup_credits;
begin
  select * into c from makeup_credits where id = p_credit;
  insert into makeup_credit_events(org_id, credit_id, kind, lesson_id, actor, reason) values (c.org_id, c.id, p_kind, p_lesson, auth.uid(), p_reason);
  insert into audit_log(org_id, actor, action, table_name, row_id, after)
  values (c.org_id, auth.uid(), 'credit_' || p_kind, 'makeup_credits', c.id::text,
          jsonb_build_object('student', c.student_id, 'source', c.source, 'source_lesson', c.source_lesson_id, 'lesson', p_lesson, 'reason', p_reason, 'expires_on', c.expires_on));
end $$;
revoke all on function public.credit_event(uuid, text, uuid, text) from public, anon, authenticated;
revoke all on function public.credit_cfg(uuid, date) from public, anon, authenticated;

-- one status change under the flag: p_from must be the credit's current status (so a double press changes nothing the second time); true = it changed
create or replace function public.credit_move(p_credit uuid, p_from text, p_to text, p_kind text, p_lesson uuid, p_reason text) returns boolean
language plpgsql security definer set search_path = public as $$
declare n int;
begin
  perform set_config('td.credit_write', 'on', true);
  update makeup_credits set status = p_to where id = p_credit and status = p_from;
  get diagnostics n = row_count;
  perform set_config('td.credit_write', '', true);
  if n = 0 then return false; end if;
  perform credit_event(p_credit, p_kind, p_lesson, p_reason);
  return true;
end $$;
revoke all on function public.credit_move(uuid, text, text, text, uuid, text) from public, anon, authenticated;

-- ---------------------------------------------------------------- 5. earning: when a lesson becomes a missed lesson the centre credits
-- Called by the lesson trigger after a mark / cancel. Does nothing for a solo organisation, for a make-up lesson (a missed make-up never earns a second
-- credit: one missed lesson = one credit; staff may grant one by hand), or when the centre's rule is `none`.
create or replace function public.credit_consider(l lessons) returns void
language plpgsql security definer set search_path = public as $$
declare tz text; today date; cfg jsonb; src text; why text; days int; cid uuid; c makeup_credits; absences text[];
begin
  select o.timezone into tz from organisations o where o.id = l.org_id and o.kind = 'centre';
  if tz is null or l.makeup_credit_id is not null then return; end if;
  today := (now() at time zone tz)::date;
  cfg := credit_cfg(l.org_id, today);
  select * into c from makeup_credits where source_lesson_id = l.id;

  absences := case cfg ->> 'earn_absences' when 'notice_only' then array['cancelled_early']
                                           when 'notice_and_late' then array['cancelled_early', 'late_cancelled']
                                           when 'all_missed' then array['cancelled_early', 'late_cancelled', 'absent']
                                           else '{}'::text[] end;
  if cfg ->> 'rule' = 'one_per_missed' then
    if l.attendance = any(absences) then src := 'absence'; why := 'Missed lesson: ' || replace(l.attendance, '_', ' ');
    elsif l.status = 'cancelled' and l.attendance is null and l.changed_by_tutor_what = 'cancelled' and cfg ->> 'earn_tutor_cancel' = 'automatic' then
      src := 'tutor_cancel'; why := 'Cancelled by the tutor';
    elsif l.status = 'cancelled' and l.attendance is null and (cfg ->> 'earn_holiday')::boolean and coalesce(l.charge_note, '') like 'Holiday%'
          and exists (select 1 from holidays h where h.org_id = l.org_id and h.branch_id is null and l.lesson_date between h.starts_on and h.ends_on) then
      src := 'holiday'; why := 'Cancelled for a holiday';
    end if;
  end if;

  if src is not null and c.id is null then
    days := (cfg ->> 'expiry_days')::int;
    insert into makeup_credits(org_id, student_id, source, source_lesson_id, reason, earned_on, expires_on, created_by)
    values (l.org_id, l.student_id, src, l.id, why, today, case when days > 0 then today + days end, auth.uid())
    on conflict (source_lesson_id) where source_lesson_id is not null do nothing
    returning id into cid;
    if cid is not null then perform credit_event(cid, 'earned', l.id, why); end if;
  elsif src is null and c.id is not null and c.status = 'open' and c.source = 'absence' and cfg ->> 'rule' = 'one_per_missed'
        and (l.attendance is null or l.attendance = 'attended') then
    -- the mark was corrected to "attended" (or cleared): the lesson was not missed after all, so its UNUSED credit goes (a booked or used one stays)
    perform credit_move(c.id, 'open', 'revoked', 'revoked', null, 'The lesson''s mark was corrected, so it no longer earns a credit');
  end if;
end $$;
revoke all on function public.credit_consider(lessons) from public, anon, authenticated;

-- ---------------------------------------------------------------- 6. the lesson triggers
-- after a mark / cancel on a lesson: (a) a make-up that has been marked uses its credit up; (b) a missed lesson may earn a credit
create or replace function public.lessons_credit_after() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if coalesce(current_setting('td.deleting_org', true), '') <> '' then return new; end if;
  if new.makeup_credit_id is not null then
    if new.attendance is not null and new.attendance is distinct from old.attendance then
      perform credit_move(new.makeup_credit_id, 'booked', 'used', 'used', new.id, 'Make-up lesson marked ' || replace(new.attendance, '_', ' '));
    end if;
    return new;
  end if;
  perform credit_consider(new);
  return new;
end $$;
drop trigger if exists lessons_credit_after on public.lessons;
create trigger lessons_credit_after after update of attendance, status, changed_by_tutor_what, charge_note on public.lessons
  for each row when (old.attendance is distinct from new.attendance or old.status is distinct from new.status
                  or old.changed_by_tutor_what is distinct from new.changed_by_tutor_what or old.charge_note is distinct from new.charge_note)
  execute function public.lessons_credit_after();

-- a make-up lesson that is deleted while its credit is booked gives the credit back (so a credit can never be left booked to a lesson that is gone)
create or replace function public.lessons_credit_before_delete() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if old.makeup_credit_id is not null and coalesce(current_setting('td.deleting_org', true), '') = '' then
    perform credit_move(old.makeup_credit_id, 'booked', 'open', 'returned', old.id, coalesce(nullif(current_setting('td.credit_reason', true), ''), 'The make-up lesson was removed'));
  end if;
  return old;
end $$;
drop trigger if exists lessons_credit_before_delete on public.lessons;
create trigger lessons_credit_before_delete before delete on public.lessons for each row when (old.makeup_credit_id is not null) execute function public.lessons_credit_before_delete();

-- ---------------------------------------------------------------- 7. the gate every credit function starts with (internal)
-- p_need: 'look' (any owner / staff) | 'grant' (grant + revoke) | 'book' (book + unbook). Returns the centre's own "today".
-- A write also needs the feature switched on: rule <> 'none' (NOT_ENABLED), so a centre that never chose credits is never changed by a stray call.
create or replace function public.credit_gate(p_org uuid, p_need text) returns date
language plpgsql stable security definer set search_path = public as $$
declare tz text; today date; cfg jsonb; who text;
begin
  if auth.uid() is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  select o.timezone into tz from organisations o where o.id = p_org and o.kind = 'centre';
  if tz is null or not exists (select 1 from memberships m where m.org_id = p_org and m.user_id = auth.uid() and m.status = 'active'
                               and m.role in ('owner', 'staff')) then
    raise exception 'NOT_FOUND' using errcode = 'P0001';
  end if;
  today := (now() at time zone tz)::date;
  if p_need = 'look' then return today; end if;
  cfg := credit_cfg(p_org, today);
  who := case p_need when 'grant' then cfg ->> 'grant_by' else cfg ->> 'book_by' end;
  if who = 'owner' then
    if not org_can(p_org, 'owner') then raise exception 'NOT_ALLOWED: at this centre only the owner can do this' using errcode = '42501'; end if;
  elsif not org_can(p_org, 'manage_timetable') then
    raise exception 'NOT_ALLOWED: your account can''t change make-up credits at this centre' using errcode = '42501';
  end if;
  if cfg ->> 'rule' = 'none' then
    raise exception 'NOT_ENABLED: make-up credits are switched off at this centre (Settings, How lessons are billed)' using errcode = 'P0001'; end if;
  return today;
end $$;
revoke all on function public.credit_gate(uuid, text) from public, anon, authenticated;

-- ---------------------------------------------------------------- 8. THE OWED LIST (read)
-- p_status: open (default: what the centre still owes) | booked | used | expired | revoked | all. p_student: only that student (the chip on the student sheet).
-- Every row carries the missed lesson (when, with whom, how it was marked) and, once booked, the make-up lesson. NO money: no rate, amount, charge or cents.
-- can_grant / can_book already include the caller's permission and the centre's settings, so the screen doesn't guess.
create or replace function public.staff_credit_list(p_org uuid, p_status text default 'open', p_student uuid default null, p_page int default 1, p_size int default 25)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare today date := credit_gate(p_org, 'look'); cfg jsonb := credit_cfg(p_org, today); pg int := coalesce(p_page, 1); sz int := coalesce(p_size, 25);
        can_g boolean; can_b boolean; rows jsonb; total int; cnt jsonb;
begin
  if p_status is null or p_status not in ('open', 'booked', 'used', 'expired', 'revoked', 'all') then
    raise exception 'BAD_FILTER: choose open, booked, used, expired, revoked or all' using errcode = 'P0001'; end if;
  if pg < 1 or pg > 100000 then raise exception 'BAD_PAGE: no such page' using errcode = 'P0001'; end if;
  if sz < 1 or sz > 100 then raise exception 'BAD_PAGE: ask for 1 to 100 credits at a time' using errcode = 'P0001'; end if;
  if p_student is not null and not exists (select 1 from students s where s.id = p_student and s.org_id = p_org) then
    raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  can_g := cfg ->> 'rule' <> 'none' and case cfg ->> 'grant_by' when 'owner' then org_can(p_org, 'owner') else org_can(p_org, 'manage_timetable') end;
  can_b := cfg ->> 'rule' <> 'none' and case cfg ->> 'book_by' when 'owner' then org_can(p_org, 'owner') else org_can(p_org, 'manage_timetable') end;

  select jsonb_build_object('open', count(*) filter (where status = 'open'), 'booked', count(*) filter (where status = 'booked'),
                            'used', count(*) filter (where status = 'used'), 'expired', count(*) filter (where status = 'expired'),
                            'revoked', count(*) filter (where status = 'revoked'))
    into cnt from makeup_credits where org_id = p_org and (p_student is null or student_id = p_student);
  select count(*) into total from makeup_credits c where c.org_id = p_org and (p_student is null or c.student_id = p_student) and (p_status = 'all' or c.status = p_status);

  select coalesce(jsonb_agg(r order by r_ord, r_id), '[]'::jsonb) into rows from (
    select jsonb_build_object(
             'credit_id', c.id, 'student_id', c.student_id, 'student_name', st.name, 'status', c.status, 'source', c.source, 'reason', c.reason,
             'earned_on', c.earned_on, 'expires_on', c.expires_on,
             'days_left', case when c.expires_on is not null and c.status = 'open' then c.expires_on - today end,
             'expired_by_date', (c.status = 'open' and c.expires_on is not null and c.expires_on < today),
             'missed', case when sl.id is null then null else jsonb_build_object('lesson_id', sl.id, 'date', sl.lesson_date, 'start_time', sl.start_time,
                         'subject', sl.subject, 'attendance', sl.attendance, 'tutor_name', stm.display_name) end,
             'makeup', case when ml.id is null then null else jsonb_build_object('lesson_id', ml.id, 'date', ml.lesson_date, 'start_time', ml.start_time,
                         'end_time', ml.end_time, 'attendance', ml.attendance, 'billing', ml.makeup_billing, 'tutor_name', mtm.display_name) end,
             'can_revoke', (c.status = 'open' and can_g),
             'can_book', (c.status = 'open' and can_b and not (c.expires_on is not null and c.expires_on < today)),
             'can_unbook', (c.status = 'booked' and can_b and ml.id is not null and ml.attendance is null and lesson_change_blocker(ml.id) is null)
           ) as r, c.earned_on as r_ord, c.id as r_id
      from makeup_credits c
      join students st on st.id = c.student_id and st.org_id = c.org_id
      left join lessons sl on sl.id = c.source_lesson_id and sl.org_id = c.org_id
      left join memberships stm on stm.id = sl.taught_by and stm.org_id = sl.org_id
      left join lessons ml on ml.makeup_credit_id = c.id and ml.org_id = c.org_id
      left join memberships mtm on mtm.id = ml.taught_by and mtm.org_id = ml.org_id
     where c.org_id = p_org and (p_student is null or c.student_id = p_student) and (p_status = 'all' or c.status = p_status)
     order by c.earned_on, c.id offset (pg - 1) * sz limit sz) z;

  return jsonb_build_object('today', today, 'page', pg, 'size', sz, 'total', total, 'counts', cnt, 'rows', rows,
                            'enabled', cfg ->> 'rule' <> 'none', 'can_grant', can_g, 'can_book', can_b,
                            'makeup_price', cfg ->> 'makeup_price', 'expiry_days', (cfg ->> 'expiry_days')::int);
end $$;

-- ---------------------------------------------------------------- 9. GRANT by hand (a tutor's cancel, a goodwill make-up, a missed lesson the rules didn't credit)
-- p_lesson (optional) = the missed lesson it is for: it must be this student's, and a lesson earns ONE credit ever (ALREADY_HAS_CREDIT).
-- A reason (3-300 characters) is always required and is kept on record. The same student and reason within a minute is refused (DUPLICATE: a double press).
create or replace function public.staff_grant_credit(p_org uuid, p_student uuid, p_reason text, p_lesson uuid default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare today date := credit_gate(p_org, 'grant'); cfg jsonb := credit_cfg(p_org, today); why text := nullif(trim(coalesce(p_reason, '')), ''); l lessons; cid uuid; days int;
begin
  if not exists (select 1 from students s where s.id = p_student and s.org_id = p_org) then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  if why is null then raise exception 'REASON_REQUIRED: say why this credit is given' using errcode = 'P0001'; end if;
  if char_length(why) < 3 or char_length(why) > 300 then raise exception 'BAD_REASON: the reason must be 3-300 characters' using errcode = 'P0001'; end if;
  if p_lesson is not null then
    select * into l from lessons where id = p_lesson and org_id = p_org and student_id = p_student;
    if not found then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
    if l.makeup_credit_id is not null then raise exception 'IS_MAKEUP: a make-up lesson can''t earn another credit' using errcode = 'P0001'; end if;
    if exists (select 1 from makeup_credits c where c.source_lesson_id = p_lesson) then
      raise exception 'ALREADY_HAS_CREDIT: this lesson already has its credit' using errcode = 'P0001'; end if;
  end if;
  if exists (select 1 from makeup_credits c where c.org_id = p_org and c.student_id = p_student and c.source = 'manual' and c.reason = why
               and c.created_at > now() - interval '1 minute') then
    raise exception 'DUPLICATE: this credit was just given' using errcode = 'P0001'; end if;
  days := (cfg ->> 'expiry_days')::int;
  insert into makeup_credits(org_id, student_id, source, source_lesson_id, reason, earned_on, expires_on, created_by)
  values (p_org, p_student, 'manual', p_lesson, why, today, case when days > 0 then today + days end, auth.uid())
  returning id into cid;
  perform credit_event(cid, 'earned', p_lesson, why);
  return jsonb_build_object('credit_id', cid, 'expires_on', case when days > 0 then today + days end);
end $$;

-- ---------------------------------------------------------------- 10. REVOKE (only an unused credit; a booked or used one is refused)
create or replace function public.staff_revoke_credit(p_credit uuid, p_reason text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare c makeup_credits; today date; why text := nullif(trim(coalesce(p_reason, '')), '');
begin
  if auth.uid() is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  select * into c from makeup_credits where id = p_credit;
  if not found then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  today := credit_gate(c.org_id, 'grant');
  if why is null then raise exception 'REASON_REQUIRED: say why this credit is taken back' using errcode = 'P0001'; end if;
  if char_length(why) < 3 or char_length(why) > 300 then raise exception 'BAD_REASON: the reason must be 3-300 characters' using errcode = 'P0001'; end if;
  select * into c from makeup_credits where id = p_credit for update;
  if c.status in ('booked', 'used') then
    raise exception 'IN_USE: a make-up lesson is already booked or taught with this credit; remove the make-up first' using errcode = 'P0001'; end if;
  if c.status <> 'open' then raise exception 'NO_CHANGE: this credit is already %', c.status using errcode = 'P0001'; end if;
  perform credit_move(c.id, 'open', 'revoked', 'revoked', null, why);
  return jsonb_build_object('credit_id', c.id, 'status', 'revoked');
end $$;

-- ---------------------------------------------------------------- 11. BOOK the make-up lesson
-- Creates an ordinary one-off lesson (the tick-star kind) for the credit's student, copying subject, level, rate and tutor from the missed lesson (or, for a credit
-- with none, from the student's latest lesson), and links it to the credit. The date is today or later, within a year, and not after the credit's last day.
-- p_end is the end time; p_tutor (a memberships.id) defaults to the missed lesson's tutor when that person is still active, else nobody.
-- PRICE (frozen on the lesson as makeup_billing): see the header. 'free' lessons are skipped by the invoice run; 'normal' ones are billed like any lesson, once.
create or replace function public.staff_book_makeup(p_credit uuid, p_date date, p_start time, p_end time, p_tutor uuid default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare c makeup_credits; today date; cfg jsonb; t lessons; src lessons; tut uuid; bill text; lid uuid; hours numeric; amt numeric; pending boolean; charged boolean;
begin
  if auth.uid() is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  select * into c from makeup_credits where id = p_credit;
  if not found then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  today := credit_gate(c.org_id, 'book');
  cfg := credit_cfg(c.org_id, today);
  select * into c from makeup_credits where id = p_credit for update;                 -- two people pressing together: one waits, then finds it booked
  if c.status = 'booked' then raise exception 'ALREADY_BOOKED: a make-up lesson is already booked with this credit' using errcode = 'P0001'; end if;
  if c.status <> 'open' then raise exception 'NOT_OPEN: this credit is %', c.status using errcode = 'P0001'; end if;
  if c.expires_on is not null and c.expires_on < today then
    raise exception 'EXPIRED: this credit ended on %', to_char(c.expires_on, 'DD Mon YYYY') using errcode = 'P0001'; end if;
  if p_date is null or p_start is null or p_end is null then raise exception 'BAD_TIME: choose a day, a start and an end time' using errcode = 'P0001'; end if;
  if p_end <= p_start then raise exception 'BAD_TIME: the lesson must end after it starts' using errcode = 'P0001'; end if;
  if p_date < today or p_date > today + 365 then raise exception 'BAD_DATE: choose a day from today to a year ahead' using errcode = 'P0001'; end if;
  if c.expires_on is not null and p_date > c.expires_on then
    raise exception 'TOO_LATE: this credit can only be used up to %', to_char(c.expires_on, 'DD Mon YYYY') using errcode = 'P0001'; end if;
  if exists (select 1 from students s where s.id = c.student_id and s.org_id = c.org_id and s.end_date is not null and s.end_date < p_date) then
    raise exception 'ENDED: this student''s lessons end before that day' using errcode = 'P0001'; end if;

  select * into src from lessons where id = c.source_lesson_id and org_id = c.org_id;
  select * into t from lessons where org_id = c.org_id and student_id = c.student_id and makeup_credit_id is null and trial is not true
   order by lesson_date desc, start_time desc limit 1;
  if src.id is not null then t := src; end if;
  if t.id is null then raise exception 'NO_TEMPLATE: add one lesson for this student first, so the make-up knows the subject and rate' using errcode = 'P0001'; end if;

  tut := coalesce(p_tutor, t.taught_by);
  if tut is not null and not exists (select 1 from memberships m where m.id = tut and m.org_id = c.org_id and m.status <> 'disabled' and m.role = 'tutor') then
    if p_tutor is not null then raise exception 'NOT_AVAILABLE: that person can''t be given lessons here' using errcode = 'P0001'; end if;
    tut := null;
  end if;
  if exists (select 1 from lessons x where x.org_id = c.org_id and x.student_id = c.student_id and x.lesson_date = p_date and x.start_time = p_start) then
    raise exception 'DUPLICATE: this student already has a lesson at that time' using errcode = 'P0001'; end if;

  -- the price rule
  if cfg ->> 'makeup_price' = 'free' then bill := 'free';
  elsif src.id is null then bill := 'normal';
  else
    pending := src.status = 'cancelled' and src.compensation is null;
    charged := src.status = 'done' or coalesce(src.compensation, 0) > 0;
    if pending then raise exception 'CHARGE_PENDING: type the charge for the missed lesson first, so the family isn''t charged twice' using errcode = 'P0001'; end if;
    bill := case when charged then 'free' else 'normal' end;
  end if;
  hours := extract(epoch from (p_end - p_start)) / 3600;
  amt := case when bill = 'free' then 0 else round(round(t.rate * hours, 2) / greatest(coalesce(t.split, 1), 1), 2) end;

  perform set_config('td.credit_write', 'on', true);
  insert into lessons(tutor_id, org_id, student_id, lesson_date, start_time, end_time, subject, level, rate, split, amount, status, paid, one_off, taught_by,
                      makeup_credit_id, makeup_billing)
  values (t.tutor_id, c.org_id, c.student_id, p_date, p_start, p_end, t.subject, t.level, t.rate, coalesce(t.split, 1), amt, 'scheduled', false, true, tut, c.id, bill)
  returning id into lid;
  perform set_config('td.credit_write', '', true);
  perform credit_move(c.id, 'open', 'booked', 'booked', lid, 'Make-up booked for ' || to_char(p_date, 'DD Mon YYYY') || ' (' || bill || ')');
  return jsonb_build_object('credit_id', c.id, 'lesson_id', lid, 'billing', bill, 'date', p_date);
end $$;

-- ---------------------------------------------------------------- 12. UNBOOK: take the make-up away and give the credit back
-- Only a make-up nobody has marked, that isn't paid or invoiced (lesson_change_blocker). The lesson is REMOVED (it existed only for this credit); the credit
-- goes back to open with a "returned" event (the delete trigger does that, so a lesson deleted any other way returns its credit too).
create or replace function public.staff_unbook_makeup(p_credit uuid, p_reason text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare c makeup_credits; today date; why text := nullif(trim(coalesce(p_reason, '')), ''); l lessons; blocker text;
begin
  if auth.uid() is null then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  select * into c from makeup_credits where id = p_credit;
  if not found then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  today := credit_gate(c.org_id, 'book');
  if why is null then raise exception 'REASON_REQUIRED: say why the make-up is taken away' using errcode = 'P0001'; end if;
  if char_length(why) < 3 or char_length(why) > 300 then raise exception 'BAD_REASON: the reason must be 3-300 characters' using errcode = 'P0001'; end if;
  select * into c from makeup_credits where id = p_credit for update;
  if c.status = 'open' then raise exception 'NO_CHANGE: no make-up is booked with this credit' using errcode = 'P0001'; end if;
  if c.status = 'used' then raise exception 'IN_USE: the make-up was already marked, so the credit is used up' using errcode = 'P0001'; end if;
  if c.status <> 'booked' then raise exception 'NO_CHANGE: this credit is %', c.status using errcode = 'P0001'; end if;
  select * into l from lessons where makeup_credit_id = c.id and org_id = c.org_id;
  if not found then raise exception 'NOT_FOUND' using errcode = 'P0001'; end if;
  blocker := lesson_change_blocker(l.id);
  if blocker is not null then
    raise exception 'LOCKED: this make-up can''t be removed (%)', lower(blocker) using errcode = 'P0001'; end if;
  perform set_config('td.credit_write', 'on', true);
  perform set_config('td.credit_reason', why, true);
  delete from lessons where id = l.id and org_id = c.org_id;
  perform set_config('td.credit_reason', '', true);
  perform set_config('td.credit_write', '', true);
  return jsonb_build_object('credit_id', c.id, 'status', (select status from makeup_credits where id = c.id));
end $$;

-- ---------------------------------------------------------------- 13. EXPIRY (a job: no signed-in person may call it)
-- Open credits whose last day (expires_on) is BEFORE the given day become expired, with an event and an audit row each. A credit expires the day AFTER its last
-- day: on expires_on itself it is still usable. A booked credit never expires (its make-up is already arranged). Safe to run any number of times.
-- The day defaults to today in Singapore (the only time zone). Called by api/credits-cron.js with the service key; NOT scheduled by this migration.
create or replace function public.credits_expire_due(p_today date default null) returns int
language plpgsql security definer set search_path = public as $$
declare d date := coalesce(p_today, (now() at time zone 'Asia/Singapore')::date); r record; n int := 0;
begin
  for r in select id from makeup_credits where status = 'open' and expires_on is not null and expires_on < d order by expires_on, id loop
    if credit_move(r.id, 'open', 'expired', 'expired', null, 'Passed its last day') then n := n + 1; end if;
  end loop;
  return n;
end $$;

